import{_ as n,P as s,d as r,e as o,y as t,q as i}from"./chunks/framework.D7CAgLCq.js";const g=JSON.parse(`{"title":"Part 6 Operation and Evolution","description":"","frontmatter":{"title":"Part 6 Operation and Evolution","xkChars":0,"xkWords":5584,"xkLessons":{"intro-06-part":{"title":"Part Six: Operation and Evolution","lead":"‘The system is operating’, ‘the system received feedback’, and ‘the system learned’ sound similar but make different commitments. Part Six separates them into checkable process questions, preventing an impressive name from replacing an entire evidence chain.","explanation":["Chinese source location: lines 1318—1321; source anchor part_6; short quotation: ‘the mechanism's name itself does not constitute a sufficient condition’ (translated from Chinese). The current source appears in the corresponding subsection on this page; the downloadable original research excerpt preserves the historical manuscript.","This part develops object contracts into process explanations. An object contract specifies boundaries, states, relations, interfaces, time, scale, and identity criteria; a process explanation asks how inputs change subsequent states through carriers or channels, what conditions enable the process, and which comparisons rule out other explanations. Clearly defining an object does not mean its process mechanism is established.","Operation, feedback, learning, maintenance, load, phase, and selection are not interchangeable narrative terms. An operation can occur without return; a return that causes change need not form learning across rounds; maintaining identity or function need not be learning; a load gap need not form lasting damage; phase change is not automatically object conversion; and differential outcomes do not automatically constitute repeated selection.","Each conditional mechanism must separately state inferential premises, enabling conditions, a mechanism chain, minimum evidence, counterfactuals/competing explanations, and stopping points. ‘What the definition requires’ and ‘why it happens in reality’ are also separate: method checks specify how the analysis verifies claims; they do not add a physical cause in the world.","Only when tests of dependencies, conditions, minimum evidence, and competing explanations all pass proportionately may a mechanism instance be registered within the specified SP, T, and K. SP is the scale profile, T the window, and K the identity criterion rather than the entire object contract. Complete fields, correct names, or a coherent story do not replace actual evidence. Existing domain research retains its conclusions and scope and is not invalidated by lacking formal status under this framework.","This part also limits extrapolation: effective does not mean improved, persistent does not mean it ought to be maintained, retention through selection does not mean superiority, and feasible repair does not mean authority to implement it. Empirical mechanisms are judged separately from normative evaluation, responsibility, and action permission; with insufficient evidence, retain candidates and specific gaps rather than filling unknowns with proven failure or proven success."],"distinctions":[{"leftTitle":"Mechanism name","leftText":"Points to a set of conditions and materials that should be satisfied.","rightTitle":"Support for a mechanism instance","rightText":"Those conditions have actual grounds for a specific object and scope."},{"leftTitle":"Inferential dependencies/method checks","leftText":"Specify how an argument is assembled and tested.","rightTitle":"Empirical cause","rightText":"A channel of effects in the world, which cannot be generated by a method's name."},{"leftTitle":"A process has effects","leftText":"It correspondingly affects subsequent states.","rightTitle":"Net benefits and normative justification","rightText":"Also require predetermined tasks, prices to be paid, and normative comparisons."}],"boundaries":["This introduction is not a replacement summary of the entire part; each subsequent mechanism still requires an independent explanation of its distinctive conditions.","No real-world mechanism certification is completed automatically by a definitional name.","The same event can involve multiple mechanisms, but citing the same material repeatedly does not create multiple independent pieces of evidence."],"questions":["Why is a one-time return that changes a state not directly called learning?","If a mechanism receives bounded support, does that imply it deserves permanent maintenance?","Why must a mechanism be tied to SP/T/K?"],"diagramPath":"/reading-assets/S-6-1/figures/intro-06-part.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"intro-06-part","start_line":1364,"end_line":1367,"startLine":1364,"endLine":1367}],"outputId":"intro-06-part","sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","argumentSteps":["Separate everyday narratives into specific mechanism claims; do not let one name account for the whole process.","Declare the object contract and SP/T/K scope, then state process variables and channels.","List this mechanism's own dependencies, enabling conditions, chain, and minimum materials.","Check the claim using proportionate counterfactuals, competing explanations, and failure conditions.","Report supported domain conclusions, formal mechanism qualification, candidates, and unknowns separately.","Stop extrapolation beyond the window, scale, identity, or claim scope; evaluation and action go to separate normative/authorization procedures."],"teachingExamples":[{"title":"Teaching construction: the same word ‘improvement’ actually hides three questions","text":"A fictional device receives an output-error signal and changes its next control quantity; this indicates only possible one-time feedback. If its parameters reset every round, this cannot establish learning across rounds. Someone else replaces worn parts and thereby preserves a predetermined function; that is a maintenance question. All three may coexist, but return, retained use, and maintenance comparisons must be checked separately; calling everything ‘the system evolved’ does not finish the work.","assumptions":"The device, behaviors, and conditions are constructed, not an assumption of successful actual experiments; formal establishment of each mechanism still requires its own materials.","boundary":"Do not infer overall net benefit, value progress, or operational authority from behavioral change."}],"counterexamples":[{"identity":"constructed_boundary","text":"The system has operated for years, so learning, maintenance, selection, and coevolution are all declared established.","effect":"Long-term existence is insufficient to satisfy the distinctive conditions of these different mechanisms.","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"A method check passes, so it is treated as a new empirical cause of system change.","effect":"This confuses methodological responsibilities with object-level causal relations; register them separately.","sourceIds":["theory"]}],"questionAnswers":[{"question":"Why is a one-time return that changes a state not directly called learning?","answer":"Learning additionally requires materials such as updates being retained/used and task comparisons, which one feedback event does not automatically supply.","basis":"The source text of this section and the public derivation above"},{"question":"If a mechanism receives bounded support, does that imply it deserves permanent maintenance?","answer":"No. Empirical effects are separate from normative choices, costs, protection, and authority.","basis":"The source text of this section and the public derivation above"},{"question":"Why must a mechanism be tied to SP/T/K?","answer":"Scale, time, and identity conditions limit the conclusion's scope; outside them, the original support cannot be directly reused.","basis":"The source text of this section and the public derivation above"}],"figures":[{"path":"/reading-assets/S-6-1/figures/intro-06-part.png","alt":"Feedback: return causes subsequent change without automatically forming learning. Learning: updates are retained and actually used; task results and net benefits remain separate. Maintenance: specified channels affect preservation of K/F without automatically generating an obligation to persist. Load: commensurate demand and capacity; an immediate gap need not accumulate damage. Phase: regions and thresholds within the same K, without automatic object conversion. Selection: variation, differential retention, and reproduction, without automatic superiority or justification. These six cards are six kinds of conditional mechanisms, not a staircase of stages; operation records supply process materials, while formal support requires each mechanism's own evidence.","caption":"These six cards are six kinds of conditional mechanisms, not a staircase of stages; operation records supply process materials, while formal support requires each mechanism's own evidence."}],"diagramBrief":"The current deliverable is a static diagram; interaction has not been implemented, and the following references to selecting, switching, or clicking describe future design ideas only. The six-card navigation has no arrows of automatic upgrading. K is the identity criterion and F the current functional criterion; the figure certifies no actual mechanism.","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"The part introduction explains how to read conditional mechanisms, using explicit constructions to identify questions rather than forcibly attaching historical mechanisms that have not been fully identified."},"openQuestions":[],"taskId":"S-6-1","sources":[{"id":"theory","title":"Historical research manuscript: Xikari: On Conditions, Structure, and Transformation, source text supplied by the user","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Lines 1294—1301 of the complete historical Chinese research manuscript; see sourceRefs for each section's precise range","claim_support":["intro-06-part: terms, contracts, burdens of argument, and source boundaries; not a basis for certifying empirical facts","6.1: terms, contracts, burdens of argument, and source boundaries; not a basis for certifying empirical facts"],"limits":["The author's theoretical text is the object being explained, not a substitute for external empirical material. Skill version 5.3.1 is not the theory's version.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"nasa114-operation","title":"NASA STS-114: imagery assessment and gap-filler removal","url":"https://www.nasa.gov/mission/sts-114/","source_type":"primary","version_or_date":"Mission 2005-07-26—08-09; webpage updated 2025-05-01","locator":"Mission Highlights, the gap-fillers account and EVA No.3 paragraph","claim_support":["6.1: imagery revealed protruding gap fillers, mission managers evaluated action, and Robinson actually removed them on August 3, 2005."],"limits":["The institutional mission record covers this operation; it does not establish long-term net benefits of all improvements or a formal G instance."],"access_status":"partially_read"},{"id":"theory-d0","title":"Historical Chinese research manuscript: Xikari §3.1, the object interface and K","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Chinese source, lines 425—448","claim_support":["Introduction and 6.1: a complete object declaration includes B/X/R/I/T/SP/K; K is only the identity criterion."],"limits":["A definition does not establish object validity in advance.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-history","title":"Historical Chinese research manuscript: Xikari §4.5, historical formation, carriers, and conditional increments","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Chinese source lines 620–640","claim_support":["6.1: separate the three historical questions; a sufficient current carrier may leave no additional historical increment, and known current states must not be omitted."],"limits":["Formal models do not replace evidence collection for real-world routes.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-scale","title":"Historical Chinese research manuscript: Xikari §§3.4 and 4.8.5, cross-scale and evidential responsibilities","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Chinese source, lines 473—494 and 698—700","claim_support":["6.1: crossing scales requires D3/E5 mappings of objects/variables/tasks, which names or local results cannot replace."],"limits":["This explains responsibilities only and does not certify actual scale transfer.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-v2","title":"Xikari: On Conditions, Structure, and Transformation, v2, November 2026","url":"/downloads/Xikari-条件结构与转化论.md","source_type":"theory_source","version_or_date":"v2 / 2026-11-16","locator":"Part Six: Operation and Evolution; Chinese source, lines 1318—1321; SHA-256 6ef2e508474d4ac1ad07d7e4e068955342c405b5f680afcfc40d68cca3d0149c","claim_support":["The current source section and this text’s conceptual explanation of v2; not a substitute for external empirical materials."],"limits":["Older research attachments retain their original manuscript identity; the previous scope of external reading has not expanded because of this edition change."],"access_status":"read"}],"lecturePath":"/reading-assets/S-6-1/lecture.md","sourcesPath":"/reading-assets/S-6-1/sources.json","sourceSlicePath":"/reading-assets/S-6-1/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-6-1/diagrams.md","editionNote":"This page’s source text and section locations correspond to v2; historical research attachments and prior external-reading records retain their own versions and scopes.","translationOf":{"language":"zh","lesson_sha256":"0f9aea809031e7d4d6f10d79d6c819f063fa375fe4727127e0c8682a23f45f87","source_sha256":"6ef2e508474d4ac1ad07d7e4e068955342c405b5f680afcfc40d68cca3d0149c"}},"6.1":{"title":"6.1 Operation records","lead":"Explaining an operation requires more than recording its start and finish. The record must include where things came from, which path they took, where changes occurred, whether another route existed, and which parts were not observed.","explanation":["Chinese source location: lines 1322—1325; source anchor section-6-1; short quotation: ‘make every delay, loss, alternative channel, break in evidence, and extrapolation boundary testable’ (translated from Chinese). The current source appears in the corresponding subsection on this page; the downloadable original research excerpt preserves the historical manuscript.","The minimum record includes inputs, specified carriers or channels, state transitions, outputs, environmental conditions, time windows, and possible traces. Inputs and outputs are distinguished by the selected object boundary; an output is not necessarily an ultimate social outcome. The carrier, the channel's transmission, and the state fields changed need specific referents; ‘the system processed it’ is insufficient.","‘Possible traces’ does not mean every operation must preserve memory permanently. There may be no persistent trace or only a temporary state; but a claim that a trace supports a subsequent effect must locate its carrier, retention window, and use, rather than treating the existence of a log as the entire mechanism.","If an output returns, separately register the return channel, receiving position, and fields changed. Clarify whether the returned signal derives from an earlier output or is an independent external input; signal arrival and subsequent field change must also remain separate. Basic operation records do not directly establish effective feedback, whose formal mechanism requires comparisons under the conditions in 6.2.","For intertemporal effects, first follow 4.5's three questions: how the past formed the current state; how the current carrier retains, updates, and affects later outcomes; and whether history still supplies an additional conditional increment given the currently registered state. The first two do not have a hard G3 requirement; only the third requires comparing a history-aware model with a current-state-sufficient model and taking on the corresponding historical-increment contract.","When crossing scales, additionally complete D3/E5 mappings: source and target objects, tasks, variables, preservation/change/loss, and errors must be compatible. Recording names of two levels cannot replace mapping, nor can a local effect automatically become an effect on the entire organization or population.","These records do not force an actual process into a one-way straight line. There may be parallel inputs, branching, loops, common conditions, and alternative paths; specify delays, losses, capacities, or boundaries individually so each can be observed, compared, or retained as unknown. If evidence breaks at a segment, identify the conclusion it limits rather than inferring that all intermediate channels were correct from a normal final output.","Use process records together with their windows and extrapolation boundaries. One execution can support what happened in that round, but does not alone establish long-term stability, continuous learning, comprehensive repair, or net benefit. Preserve the types of unobserved periods and missing fields; connecting lines in a process diagram must not become proofs unsupported by materials."],"distinctions":[{"leftTitle":"Output","leftText":"A result under the current object boundary and window.","rightTitle":"Long-term ultimate effects","rightText":"Require separate intertemporal materials and targets and are not guaranteed by one output."},{"leftTitle":"Trace formation","leftText":"A carrier preserves a record or state.","rightTitle":"Subsequent effect","rightText":"A trace is used and affects the predetermined outcome; evidence is still required."},{"leftTitle":"Return signal","leftText":"A feedback path from an earlier output/state.","rightTitle":"Independent input","rightText":"May also change the system but is not that return channel."},{"leftTitle":"Process records","leftText":"Make paths and gaps inspectable.","rightTitle":"Linear-chain assumption","rightText":"Not a recording requirement; networks, loops, and parallel channels are permitted."}],"boundaries":["Do not require G3 for every intertemporal effect or treat failure to pass G3 as proof of the carrier route.","Absence of traces does not automatically cancel a round of operation or transient feedback; claims of persistence require proportionate preservation materials.","A normal output can result from compensation through alternative channels and cannot establish that every original path was functioning normally.","A process example is not certification of an actual mechanism; action still requires independent authority and protection."],"questions":["Why is the inventory example 4 rather than 3 or 5?","If the planning field has changed, may the next round's actual output be recorded as improved?","Do all intertemporal effects require comparison with a history-aware model?","Must a process record be drawn as a straight line?"],"diagramPath":"/reading-assets/S-6-1/figures/section-6-1.png","caseLinks":[{"title":"STS-114: imagery, analysis, and actual action occupy different positions","href":"https://www.nasa.gov/mission/sts-114/"}],"caseNotes":[{"title":"STS-114: imagery, analysis, and actual action occupy different positions","text":"NASA's STS-114 mission record describes how imagery during the 2005 flight revealed two protruding gap fillers, after which mission managers studied whether they needed attention; on August 3, Robinson pulled them out during an extravehicular activity. The record separates observation, analysis/decision, and execution; ‘obtaining imagery’ cannot substitute for completion of the action.","sourceLabel":"NASA STS-114 mission page, updated 2025-05-01","sourceUrl":"https://www.nasa.gov/mission/sts-114/","sourceLocator":"Mission Highlights: imagery and gap-fillers paragraphs, and EVA No.3 paragraph; mission 2005-07-26 to 08-09","boundary":"An institutional mission record supporting this imagery and removal operation; a single operation does not establish that all safety improvements were effective, long-term learning, or a complete formal feedback instance.","href":"https://www.nasa.gov/mission/sts-114/"}],"sourceRefs":[{"section":"6.1","start_line":1368,"end_line":1371,"startLine":1368,"endLine":1371}],"outputId":"section-6-1","sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","argumentSteps":["Before results, fix the object boundary, task, variables, time window, and environment, and clarify the definitions of inputs and outputs.","Specify each carrier/channel's start, endpoint, transmitted content, and state-update rule.","Register parallel and alternative paths, delays, losses, and possible traces without forcing a single chain.","Where return exists, trace it to the original output, receiving position, and changed fields, then compare according to feedback responsibilities.","For intertemporal claims, select the historical-formation, carrier-transmission, or additional-historical-increment route and list their materials separately.","For cross-scale claims, add D3/E5 object and variable bridges and retain task-relevant losses.","Explain checkable facts, breaks in evidence, and extrapolation ceilings segment by segment; do not invent intermediate processes from a normal endpoint."],"teachingExamples":[{"title":"Mathematical construction: parallel inputs and losses both affect state records","text":"A fictional container begins with inventory x=5, two input channels u₁=2 and u₂=1, delivered output q=3 this round, and environmental leakage ℓ=1. Stipulate common units and the same window, with inputs arriving first and combined delivery and leakage no greater than the available quantity. The update is x′=x+u₁+u₂−q−ℓ=4. Recording only the first channel incorrectly predicts 3; omitting leakage predicts 5. The endpoint 4 alone cannot tell us which combination of inputs and losses produced it; process materials must be checked.","assumptions":"An exact nonnegative inventory model with no additional unregistered flows; all numbers are artificial stipulations, not actual equipment observations.","boundary":"This establishes only the accounting mapping and identifies neither actual causation nor long-term capacity stability."},{"title":"Teaching construction: trace a return to its output source","text":"Continuing the fictional container, let the predetermined delivery target be r=4. A comparator reads this round's actual q=3, computes e=r−q=1, returns it through the specified channel to the scheduling position, and changes next round's plan for the first channel u₁ from 2 to 3. The record should preserve q, e's source, the receiving position, and the planning-field change separately. If the plan has not yet been executed, actual delivery in the next round cannot be declared improved; if the signal is merely an independent external notice, it cannot masquerade as a return from q.","assumptions":"The target, comparator, and planning rule are all constructed; only the planning field's rule-governed update is claimed, without assuming execution or future benefits.","boundary":"Actual feedback, subsequent delivery, and persistent learning must be judged from their respective materials."},{"title":"Mathematical construction: a sufficient current carrier needs no additional history","text":"Let state s update by s′=0.5s+u. Histories (4,0) and (0,2), starting from 0, both reach current s=2. With next input 0, both reach 1. Past inputs have affected current s, but given complete s no additional history is needed to calculate the next step. If only ‘whether s>0’ is stored, history may recover lost distinctions; that is a representation choice that must be disclosed.","assumptions":"An exact fixed rule and complete current s; no actual historical-effect detection.","boundary":"Model sufficiency does not establish the sufficiency of an actual current state; actual carrier and history routes require separate evidence."}],"counterexamples":[{"identity":"constructed_boundary","text":"Final delivery is normal, so none of the original channels failed.","effect":"Substitute channels may compensate; an endpoint cannot uniquely recover the path.","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"A plan changes after receiving a notice, so it must be output feedback.","effect":"Trace whether the notice actually arose from earlier output; otherwise it may be an independent input.","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"An operating log exists, so long-term learning and reduced risk are proved.","effect":"Traces, invocation, task results, and net benefit each require evidence.","sourceIds":["theory"]}],"questionAnswers":[{"question":"Why is the inventory example 4 rather than 3 or 5?","answer":"Both inputs arrive and leakage occurs: 5+2+1−3−1=4; 3 omits the second input, while 5 omits leakage.","basis":"The source text of this section and the public derivation above"},{"question":"If the planning field has changed, may the next round's actual output be recorded as improved?","answer":"No. Check whether plans enter execution and actual results occur; a field update cannot replace future observation.","basis":"The source text of this section and the public derivation above"},{"question":"Do all intertemporal effects require comparison with a history-aware model?","answer":"No. Only a claim of additional historical increment beyond currently registered states requires the corresponding comparison; formation and carrier transmission have separate routes.","basis":"The source text of this section and the public derivation above"},{"question":"Must a process record be drawn as a straight line?","answer":"Not necessarily. Parallel, return, branching, and substitute channels may be recorded; each segment needs a checkable identity and boundary.","basis":"The source text of this section and the public derivation above"}],"figures":[{"path":"/reading-assets/S-6-1/figures/section-6-1.png","alt":"Inputs: u1=2,u2=1, two parallel channels; specified channels and timing: same units/window, inputs arrive first; state update: x=5, x′=5+2+1−3−1=4; output: this round delivers q=3, which is not long-term net effect; environmental conditions: leakage of 1 this round cannot be silently omitted; possible return and traces: source/receiver/changed fields, with execution checked separately. All numbers are a fictional inventory model; environment and return cards are additional records, and a single line does not replace the actual network.","caption":"All numbers are a fictional inventory model; environment and return cards are additional records, and a single line does not replace the actual network."}],"diagramBrief":"The current deliverable is a static diagram; interaction has not been implemented, and the selections, switches, or clicks described below are ideas for a later design only. Six cards retain inputs, channels, states, outputs, environment, and return/traces. Arrows indicate recording order; the equations and timing in the text specify the actual model.","applicability":{"realCase":"applicable","diagram":"applicable","reason":"Specific task records provide distinct stages from observation to execution, suitable for operation records; the diagram and inventory example are separate explicit constructions and fabricate no NASA numbers."},"openQuestions":[],"taskId":"S-6-1","sources":[{"id":"theory","title":"Historical research manuscript: Xikari: On Conditions, Structure, and Transformation, source text supplied by the user","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Lines 1294—1301 of the complete historical Chinese research manuscript; see sourceRefs for each section's precise range","claim_support":["intro-06-part: terms, contracts, burdens of argument, and source boundaries; not a basis for certifying empirical facts","6.1: terms, contracts, burdens of argument, and source boundaries; not a basis for certifying empirical facts"],"limits":["The author's theoretical text is the object being explained, not a substitute for external empirical material. Skill version 5.3.1 is not the theory's version.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"nasa114-operation","title":"NASA STS-114: imagery assessment and gap-filler removal","url":"https://www.nasa.gov/mission/sts-114/","source_type":"primary","version_or_date":"Mission 2005-07-26—08-09; webpage updated 2025-05-01","locator":"Mission Highlights, the gap-fillers account and EVA No.3 paragraph","claim_support":["6.1: imagery revealed protruding gap fillers, mission managers evaluated action, and Robinson actually removed them on August 3, 2005."],"limits":["The institutional mission record covers this operation; it does not establish long-term net benefits of all improvements or a formal G instance."],"access_status":"partially_read"},{"id":"theory-d0","title":"Historical Chinese research manuscript: Xikari §3.1, the object interface and K","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Chinese source, lines 425—448","claim_support":["Introduction and 6.1: a complete object declaration includes B/X/R/I/T/SP/K; K is only the identity criterion."],"limits":["A definition does not establish object validity in advance.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-history","title":"Historical Chinese research manuscript: Xikari §4.5, historical formation, carriers, and conditional increments","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Chinese source lines 620–640","claim_support":["6.1: separate the three historical questions; a sufficient current carrier may leave no additional historical increment, and known current states must not be omitted."],"limits":["Formal models do not replace evidence collection for real-world routes.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-scale","title":"Historical Chinese research manuscript: Xikari §§3.4 and 4.8.5, cross-scale and evidential responsibilities","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Chinese source, lines 473—494 and 698—700","claim_support":["6.1: crossing scales requires D3/E5 mappings of objects/variables/tasks, which names or local results cannot replace."],"limits":["This explains responsibilities only and does not certify actual scale transfer.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-v2","title":"Xikari: On Conditions, Structure, and Transformation, v2, November 2026","url":"/downloads/Xikari-条件结构与转化论.md","source_type":"theory_source","version_or_date":"v2 / 2026-11-16","locator":"6.1 Operation Record; Chinese source lines 1322–1325; SHA-256 6ef2e508474d4ac1ad07d7e4e068955342c405b5f680afcfc40d68cca3d0149c","claim_support":["The current source section and this text’s conceptual explanation of v2; not a substitute for external empirical materials."],"limits":["Older research attachments retain their original manuscript identity; the previous scope of external reading has not expanded because of this edition change."],"access_status":"read"}],"lecturePath":"/reading-assets/S-6-1/lecture.md","sourcesPath":"/reading-assets/S-6-1/sources.json","sourceSlicePath":"/reading-assets/S-6-1/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-6-1/diagrams.md","editionNote":"This page’s source text and section locations correspond to v2; historical research attachments and prior external-reading records retain their own versions and scopes.","translationOf":{"language":"zh","lesson_sha256":"692c9c24037583ada841eb2ba2b7296a80596ad6721902c7c74abc942448d08f","source_sha256":"6ef2e508474d4ac1ad07d7e4e068955342c405b5f680afcfc40d68cca3d0149c"}},"6.2":{"title":"6.2 CM-FEEDBACK Effective Feedback","lead":"Receiving comments, receiving an alarm, or saving a report is not yet effective feedback in this section’s sense. Trace how an earlier output returns and precisely where that return changes the next step.","explanation":["Source location: Chinese source lines 1326–1335; source anchor section-6-2; short quotation translated from Chinese: ‘Effective feedback says only that return caused a subsequent change.’ See the corresponding section on this page for the current original text; the downloadable original research excerpt retains the historical draft.","This mechanism expands D2’s definition into empirical responsibilities. D2 defines effective feedback, and G2 identifies the specified return channel’s effect; E4, CAUSAL, and EVIDENCE set methods for competing explanations, causal identification, and material review, rather than adding causes of change in the world. Basic feedback requires neither G3 nor permanently retained history.","Enabling conditions include three indispensable connections. First, the signal must originate in a prior state or output and enter a later process through a named channel. Second, relative to no return or blockage, at least one preregistered subsequent state, transition probability, or constraint must differ beyond a threshold. Third, timing and changed fields must be registered before results, not selected as targets after seeing what changed.","The mechanism chain is prior state/output, return signal, transmission through the specified channel, uptake at the receiver, subsequent field change, and blocked-counterfactual review. The first five describe the claimed causal path; the last is the comparative responsibility for testing that path, not a physical blockage that must occur after every actual operation. A diagram without material for its segments remains a candidate explanation.","Formal minimum evidence includes a G2-instance passing the preregistration gate, return channel and receiver, temporal order, changed fields, subsequent differences, and a proportionate no-return/blockage comparison. Controlled intervention, controlled perturbation, or natural variation with identification conditions must follow the preselected plan; identifying actual feedback does not justify arbitrarily shutting safety channels. Suitable existing material can be analyzed first; experiments separately require authority and risk review.","Three failures occur at different positions: a signal arrives but leaves subsequent transitions unchanged, so reception cannot masquerade as effect; shared external input adequately explains the change, so this return has not been distinguished; differences persist after blocking the specified return, failing to support its claimed contribution. Compensation by substitute channels, an intervention not actually taking effect, and insensitive measurement still require checks; one nonsignificant result does not prove that ‘no feedback of any kind exists’.","Effective means that return has an effect, not that it is good. It may correct deviations or amplify error, delay decisions, or cause losses; one effective return is not automatically learning across rounds, repair, or net benefit. Section 6.2.1 uses a fully specified mathematical model to prove that ‘the same first-step change’ and ‘different long-term stability’ can coexist. Model comparisons are not real G2-instance qualification.","Process facts and causal research in domain reports retain their standing under their own material. Absence of this framework’s complete instance contract does not cancel rule changes or actual execution that occurred; equally, those facts cannot retrospectively establish every specified mechanism and long-term effect. Conclusions should explicitly distinguish observed changes, mechanism candidates, and still-unidentified parts."],"distinctions":[{"leftTitle":"Signal arrival","leftText":"The receiver has the signal, which may generate only a receipt.","rightTitle":"Effective feedback","rightText":"The specified return creates an identifiable difference in a predetermined subsequent field."},{"leftTitle":"Return effect","leftText":"May follow a fixed rule and occur only once.","rightTitle":"Learning","rightText":"Additionally requires retention of updates, actual invocation, task comparison, and other conditions."},{"leftTitle":"No-return counterfactual","leftText":"A comparison condition helping distinguish this channel’s effect.","rightTitle":"Actual forced disconnection required","rightText":"Not a logical requirement; real tests remain constrained by safety, authority, and feasibility."},{"leftTitle":"Methodological gates","leftText":"Constrains testing and treatment of competing explanations.","rightTitle":"Causes in the object","rightText":"Channels or conditions actually transmitting change."}],"boundaries":["Parameter blockage in a formal model can be calculated exactly but does not automatically validate real channels or experimental implementability.","Measuring one state change this round does not additionally establish channel capacity, reliability, costs, or long-term effects.","Negative or oscillating results may also contain effective feedback; effective does not mean beneficial.","Failure at the positive gate may reflect counterevidence or insufficient measurement; record them separately rather than treating uncertainty as proof of zero effect."],"questions":["If a receipt appears on time but subsequent scheduling is exactly the same as with no return, may effective feedback be recorded directly?","Why might a controller reset each round still have effective feedback when it adjusts once using actual output error?","If the difference remains after blockage, is zero effect already proved?","Can feedback known to increase error on one occasion still be called effective?"],"diagramPath":"/reading-assets/S-6-2/figures/section-6-2.png","caseLinks":[{"title":"Maryland renewals: process changes and complete channel identification are separate","href":"https://health.maryland.gov/mmcp/Documents/JCRs/2023/eligibilityredetprocessJCRfinal4-24.pdf"}],"caseNotes":[{"title":"Maryland renewals: process changes and complete channel identification are separate","text":"Maryland’s health department’s 2024 report recalls CMS clarification in August 2023 that renewals based on existing data should occur at the individual rather than household level. The state subsequently records system changes and explicitly states that the updated process entered actual use in November 2023. This section adds the location of material between problem return and subsequent execution: receipt of a report alone does not establish an effect, while recorded actual process changes should not be erased.","sourceLabel":"Maryland FY24 Quarter 4 report, submitted 2024-05-14","sourceUrl":"https://health.maryland.gov/mmcp/Documents/JCRs/2023/eligibilityredetprocessJCRfinal4-24.pdf","sourceLocator":"Printed pp. 8–9, Medicaid Mitigation of Ex Parte Renewals, final paragraph: ‘updated process was utilized beginning November 2023’","boundary":"Administrative self-report supports the problem description and process-use facts. The passage supplies no preregistered G2, separate blockage comparison, or identification of long-term health effects; no formal feedback instance is retrospectively awarded, and this is not current eligibility advice.","href":"https://health.maryland.gov/mmcp/Documents/JCRs/2023/eligibilityredetprocessJCRfinal4-24.pdf"}],"sourceRefs":[{"section":"6.2","start_line":1372,"end_line":1381,"startLine":1372,"endLine":1381}],"outputId":"section-6-2","sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","argumentSteps":["First record object, window, target fields, return origin, and receiver, confirming that the signal is not an independent external input.","List D2/G2 inferential responsibilities separately from E4/CAUSAL/EVIDENCE methodological responsibilities; do not add G3 as a mandatory gate for basic feedback.","Before results, fix the primary comparison, threshold, timing, and measured channel dimensions, and check the execution version.","Trace transmission, uptake, and subsequent change through material, separating arrival, traces, and effect.","Use proportionate no-return, blockage, or alternative comparisons with identification conditions, addressing shared inputs, substitute channels, and measurement changes.","With insufficient evidence, record only candidates and gaps; null conclusions additionally require their rules, sensitivity, and tolerances.","For a supported effect, separately ask about stability, learning, target improvement, loss distribution, and authority; ‘effective’ cannot answer everything."],"teachingExamples":[{"title":"Mathematical construction: transient feedback exists without permanent memory","text":"Each round, a device outputs a=0 with target r=1. A comparator reads actual a and generates e=r−a=1, returning it through a channel to a controller, which updates a←a+e to 1. Blocking return leaves the rule without input, so a remains 0. With a predetermined model criterion of a within-round output difference greater than 0.5, difference 1 passes. Every state resets to zero after each round, the next round repeats, and no parameters, logs, or experience are retained. The construction thus has return effects this round but no cross-round learning through retained updates.","assumptions":"Exact deterministic rules, with return as the sole update source and blockage changing no other conditions; entirely a mathematical setup, not a real device experiment.","boundary":"The calculation cannot establish identification of real G2; absence of cross-round memory does not cancel this round’s effect."},{"title":"Mathematical construction: shared input can masquerade as feedback","text":"Let external variable U be 0 or 1, alarm R=U, and subsequent action Y=U. Observation shows R=Y, but cutting only the alarm connection while preserving U and the action rule leaves Y equal to U. Alarm and action share a source; observed correlation does not establish that R causes Y. Changing the actual rule to Y=R creates another model and cannot be done silently after results.","assumptions":"Variables and intervention meanings are fully stipulated, with U affecting both endpoints; the comparison removes only R’s information to the receiver.","boundary":"Whether shared inputs, substitute channels, or intervention side effects actually exist requires material and is not prejudged by this example."}],"counterexamples":[{"identity":"constructed_boundary","text":"Comments are stored in a database, every field next round still follows old rules, yet ‘the feedback loop is closed’ is declared.","effect":"Archiving can establish a trace, not a subsequent effect.","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"Performance remains unchanged after closing one return channel, so the whole system is declared to have no feedback.","effect":"Other compensating paths or failed intervention may remain; evaluate only the specified claim under checked conditions.","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"First-step error declines, so stability, learning, and repair are all declared complete.","effect":"These are different tasks; the subsection provides explicit models with opposite stability outcomes.","sourceIds":["theory"]}],"questionAnswers":[{"question":"If a receipt appears on time but subsequent scheduling is exactly the same as with no return, may effective feedback be recorded directly?","answer":"No. There is only arrival/recording; check whether the specified return changed predetermined subsequent fields.","basis":"The source text of this section and the public derivation above"},{"question":"Why might a controller reset each round still have effective feedback when it adjusts once using actual output error?","answer":"A return-caused difference this round suffices; persistent historical traces are not necessary for basic feedback.","basis":"The source text of this section and the public derivation above"},{"question":"If the difference remains after blockage, is zero effect already proved?","answer":"Not automatically. Check successful blockage, substitute channels, comparison sensitivity, and predetermined null-conclusion rules; otherwise it may simply be an unsupported or unresolved claim.","basis":"The source text of this section and the public derivation above"},{"question":"Can feedback known to increase error on one occasion still be called effective?","answer":"It may be called effective if the effect is identified, but target improvement does not hold; report the effect and adverse outcome separately.","basis":"The source text of this section and the public derivation above"}],"figures":[{"path":"/reading-assets/S-6-2/figures/section-6-2.png","alt":"Prior state or output: traceable origin, not independent external input; return signal and channel: transmission to a specified position, recording timing and version; receiver and subsequent fields: arrival is not change, check states/probabilities/constraints; comparative responsibility: no return or blockage, checking execution and side effects; competing explanations: shared inputs/substitute channels, measurement and selection changes; support ceiling: return has an effect this round, while learning/stability/net benefit need separate checks. The upper row is a candidate causal chain; the lower row contains testing responsibilities and conclusion boundaries, not additional physical causes.","caption":"The upper row is a candidate causal chain; the lower row contains testing responsibilities and conclusion boundaries, not additional physical causes."}],"diagramBrief":"The current deliverable is a static diagram; interaction has not been implemented, and the selections, switches, or clicks described below are ideas for a later design only. Six cards separate the actual effect chain from comparative responsibility; absent subsequent differences or proportionate identification, retain a candidate without automatically supporting zero effect.","applicability":{"realCase":"applicable","diagram":"applicable","reason":"The actual administrative report distinguishes problem return, system change, and actual use without pretending to provide full G2-mechanism certification; transient control and common causes use separate explicit constructions."},"openQuestions":[],"taskId":"S-6-2","sources":[{"id":"theory","title":"Historical research manuscript: Xikari: On Conditions, Structure, and Transformation, source text supplied by the user","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Historical research draft, full text, lines 1302–1319; see sourceRefs for each section’s exact range","claim_support":["6.2: terminology, contracts, burdens of argument, and boundaries of the original text; no empirical facts are certified on this basis","6.2.1: terminology, contracts, burdens of argument, and boundaries of the original text; no empirical facts are certified on this basis"],"limits":["The author's theoretical text is the object being explained, not a substitute for external empirical material. Skill version 5.3.1 is not the theory's version.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"maryland-renewal","title":"Maryland FY24 Quarter 4 Medicaid Redetermination report","url":"https://health.maryland.gov/mmcp/Documents/JCRs/2023/eligibilityredetprocessJCRfinal4-24.pdf","source_type":"primary","version_or_date":"Report dated April 2024; submission cover letter 2024-05-14","locator":"Printed pp. 8–9 (PDF pages 12–13), Medicaid Mitigation of Ex Parte Renewals","claim_support":["6.2: August 2023 clarification of individual-renewal requirements, state system changes, and actual use of the updated process beginning November 2023."],"limits":["The administrative report lacks the complete G2 contract or independent channel-blockage identification required here; it is not extended to current eligibility or long-term health outcomes."],"access_status":"partially_read"},{"id":"theory-d2","title":"Historical research draft: Xikari 3.3: D2 Effective Feedback","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Chinese source lines 462–471","claim_support":["6.2: return, reception, subsequent fields, and no-return comparison; one effect, stability, and target improvement are separate."],"limits":["A definition is not empirical evidence of actual feedback.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-g2","title":"Historical research draft: Xikari 4.4: G2 Specified Channels","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Chinese source lines 610–619; four-state responsibilities at lines 577–581","claim_support":["6.2: G2 preselected claims and separate channel-dimension measurements; a failed positive gate is not support for zero effect."],"limits":["Retain existing domain evidence’s status without retrospectively awarding formal qualification.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-c10","title":"Historical research draft: Xikari Appendix C.10: Strict Stability Conditions for Fixed-Delay Feedback","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Chinese source lines 4470–4493","claim_support":["6.2.1: characteristic polynomial, stability at small positive gain, unit-circle boundary and outward-crossing proofs; critical values for four delays."],"limits":["Constrains only the disclosed fixed linear model and supplies no prescription for actual parameters.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-v2","title":"Xikari: On Conditions, Structure, and Transformation, v2, November 2026","url":"/downloads/Xikari-条件结构与转化论.md","source_type":"theory_source","version_or_date":"v2 / 2026-11-16","locator":"6.2 CM-FEEDBACK Effective Feedback; Chinese source lines 1326–1335; SHA-256 6ef2e508474d4ac1ad07d7e4e068955342c405b5f680afcfc40d68cca3d0149c","claim_support":["The current source section and this text’s conceptual explanation of v2; not a substitute for external empirical materials."],"limits":["Older research attachments retain their original manuscript identity; the previous scope of external reading has not expanded because of this edition change."],"access_status":"read"}],"lecturePath":"/reading-assets/S-6-2/lecture.md","sourcesPath":"/reading-assets/S-6-2/sources.json","sourceSlicePath":"/reading-assets/S-6-2/source-slice.md","supplementaryFiles":[{"title":"delay-trajectories.csv","path":"/reading-assets/S-6-2/figures/delay-trajectories.csv"}],"diagramsPath":"/reading-assets/S-6-2/diagrams.md","editionNote":"This page’s source text and section locations correspond to v2; historical research attachments and prior external-reading records retain their own versions and scopes.","translationOf":{"language":"zh","lesson_sha256":"feb8443b3b1d0a6ab705f6c574bd1dd6514f256102096fb042037a490b0613bd","source_sha256":"6ef2e508474d4ac1ad07d7e4e068955342c405b5f680afcfc40d68cca3d0149c"}},"6.2.1":{"title":"6.2.1 Feedback Delay and Stability Intervals","lead":"With the same corrective strength, a later response may be more prone to repeated overshoot. Rather than an empirical slogan that ‘delay is dangerous’, this section calculates an exact stability range in a small model with fully disclosed assumptions.","explanation":["Source location: Chinese source lines 1336–1343; source anchor section-6-2-1; short quotation translated from Chinese: ‘Equality is not included in the stability region.’ See the corresponding section on this page for the current original text; the downloadable original research excerpt retains the historical draft.","The model is x_{t+1}=x_t−k x_{t−d}. x is signed, dimensionless deviation from a target; k is a fixed real gain; d is a fixed nonnegative integer delay; sampling intervals are fixed. Given a finite initial history x_{−d},…,x_0, the subsequent trajectory is unique. There are no external shocks, measurement noise, actuator saturation, or state boundaries. Negative x means crossing the target, not a negative task count.","The result proved is that the zero solution is asymptotically stable for all finite initial histories if and only if 0<k<k_c(d), where k_c(d)=2sin[π/(4d+2)]. Asymptotic stability requires small deviations not to escape control as they evolve and to tend to zero in the long run; for this finite-dimensional fixed linear system, it is characterized by every characteristic root having modulus strictly below 1. This is not selecting one attractive initial trajectory or merely observing decline for a few steps.","Store current and delayed states together as z_t=(x_t,x_{t−1},…,x_{t−d}), giving fixed-matrix recurrence z_{t+1}=Az_t. Substituting mode x_t=λ^t yields characteristic polynomial p(λ,k)=λ^{d+1}−λ^d+k. If all roots lie inside the unit circle, every mode decays; even with repeated roots, polynomial factors in t multiplied by an exponential with base strictly below 1 tend to zero. A root with modulus ≥1 supplies a nondecaying or growing mode for a corresponding real initial history, violating ‘all histories tend to zero’.","First exclude k≤0. At k=0 there is a root 1, and any nonzero constant history persists, so asymptotic stability fails. For k<0, p(1,k)=k<0, while p>0 for sufficiently large positive λ, so continuity gives at least one real root λ>1. For d=0, directly use x_{t+1}=(1−k)x_t: |1−k|<1 is exactly 0<k<2.","For d≥1 and sufficiently small positive k, the root 1 at k=0 is simple and implicit differentiation shows inward motion λ=1−k+O(k²); the other d roots start near 0 and remain inside by continuity. Thus a stable small-positive-gain interval exists. Finding its endpoint requires locating the first contact of characteristic roots with the unit circle, not merely running several floating-point trials.","Let a boundary root be λ=e^{iθ}, 0<θ<2π. From p=0, k=λ^d(1−λ)=2sin(θ/2)exp{i[(d+1/2)θ−π/2]}. Since sin(θ/2)>0, positive real k requires the phase to be an integer multiple of 2π, giving θ=(π+4πm)/(2d+1), m=0,…,d. Among all possible positive boundaries, the minimum 2sin(θ/2) comes from the smallest angle θ=π/(2d+1) and its conjugate, yielding k_c=2sin[π/(4d+2)]. Roots vary continuously with k and remain bounded on finite parameter intervals; leaving the unit circle requires crossing one of these boundaries, so stability holds for 0<k<k_c.","Necessity also requires ruling out “leaving and then returning.” At the boundary, p_λ=λ^{d−1}[(d+1)λ−d] is nonzero, since ((d+1)λ=d) requires |λ|=d/(d+1)<1. Every unit-circle root is therefore simple. Differentiating p=0 gives λ′/λ=(λ−1)/{k[(d+1)λ−d]}. Multiplying numerator and denominator by the denominator's conjugate and taking real parts yields numerator real part (2d+1)(1−cosθ), hence d log|λ|/dk=(2d+1)(1−cosθ)/{k|(d+1)e^{iθ}−d|²}>0. Every positive-gain crossing goes outward, with no inward reentry, so complete stability cannot return above the first boundary. d=0 was already handled directly.","At k=k_c, at least one root has unit modulus, yielding a nondecaying mode, so equality is excluded. A numerical value 0.999999… caused by rounding cannot justify inclusion. Beyond the boundary, a growing mode exists, but not every history grows: an all-zero history stays zero, and special histories containing no unstable mode may behave differently. “System instability” concerns the family of all histories; it does not mean every curve diverges.","Fix k=0.8. For d=0,1,2,3, critical values are respectively 2,1, approximately 0.618034 and 0.445042: the first two are stable and the latter two unstable. If every required initial-history value is 1, the first step is always 1−0.8=0.2. Under complete blockage k=0, the trajectory stays 1. Return thus produces a first-step difference of 0.8 while long-term stability differs, showing that “has an effect” and “stable” are nonequivalent.","More closely, d=1 gives first updates 0.2,−0.6,−0.76: despite asymptotic stability, absolute deviation can increase between adjacent steps and overshoot occurs. Stability guarantees neither stepwise decrease, reaching arbitrary tolerance within a finite window, safe transient peaks, nor affordable execution costs. The figures show only model calculations for t=0…24; the long-term conclusion comes from proof, not visual inspection of curves.","Actual use separately requires checking error definitions, sampling frequency, fixed versus varying delay, actuator saturation, service constraints, external inputs, and strategic human responses. Real queues have nonnegative task counts and heterogeneous service and demand; institutional correction also involves authority and costs. None is modeled by this equation. This section therefore cannot prescribe k=0.8 directly for an actual process."],"distinctions":[{"leftTitle":"Effective feedback","leftText":"Compared with blockage, return has changed a subsequent state.","rightTitle":"Asymptotic stability","rightText":"Every finite initial history tends to zero over time and satisfies this linear stability property."},{"leftTitle":"System instability","leftText":"A nondecaying or growing mode exists.","rightTitle":"Every trajectory diverges","rightText":"A much stronger, false claim; zero history is a counterexample."},{"leftTitle":"Asymptotic convergence to zero","leftText":"A property over sufficiently long time.","rightTitle":"Improvement at every step and acceptable peaks","rightText":"Separate finite-time tasks and constraints."},{"leftTitle":"Signed deviation","leftText":"Negative values mean overshooting the target.","rightTitle":"Actual task count","rightText":"Usually has separate nonnegativity constraints and cannot be directly equated with deviation."}],"boundaries":["The stability region is a strictly open interval, excluding both endpoints k=0 and k=k_c.","A finite trajectory alone cannot prove asymptotic stability for all histories. Root analysis and crossing direction provide that proof.","The criterion applies only to fixed discrete delay and fixed real gain. Time-varying delay, random disturbances, nonlinearities, and saturation require new analysis.","A within-model return effect is not empirical G2 certification and supplies no authority for actual action.","The four trajectory panels share a horizontal axis but label vertical ranges separately. Visual slopes cannot be used to compare magnitudes across panels."],"questions":["Do d=1 and k=1 satisfy strict asymptotic stability?","Why does finding the first unit-circle intersection not yet prove instability for every larger k?","For d=3 and k=0.8, does an all-zero initial history remaining zero refute instability?","Does the d=1 sequence from 0.2 to −0.6 contradict asymptotic stability?","If an actual processing queue has a measured average delay of 2 steps, may control parameters directly use k<0.618034?"],"diagramPath":"/reading-assets/S-6-2/figures/section-6-2-1.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"6.2.1","start_line":1382,"end_line":1389,"startLine":1382,"endLine":1389}],"outputId":"section-6-2-1","sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","argumentSteps":["Disclose the model assumptions: signed deviation, fixed gain/delay, finite initial history, and absence of noise/constraints.","Extend to a finite-dimensional linear state and explain the equivalence between all roots strictly inside the unit circle and decay for all histories.","Use root 1 and a real root greater than 1 to exclude k≤0, and solve d=0 separately.","Prove stability for sufficiently small positive k, then set a unit-circle root e^{iθ} to find the first positive boundary.","Derive θ and k_c from the positive-real phase condition, using root continuity to establish stability before the first boundary.","Implicitly differentiate boundary roots and prove all positive-k crossings go outward, ruling out renewed stability.","Exclude equality and distinguish existence of unstable modes from growth of every trajectory; substitute the four d values to check numerical values.","Compare first-step blockage and feedback, then assess effect, asymptotic stability, transient metrics, and actual adoption separately."],"teachingExamples":[{"title":"Mathematical construction: four delays share the first step but differ afterward","text":"Let k=0.8 and all initial-history values required by each delay be 1. For t=0…4, d=0 gives 1,0.2,0.04,0.008,0.0016; d=1 gives 1,0.2,−0.6,−0.76,−0.28; d=2 gives 1,0.2,−0.6,−1.4,−1.56; d=3 gives 1,0.2,−0.6,−1.4,−2.2. Each value follows the preceding recursion; for example, at d=2, x₃=x₂−0.8x₀=−0.6−0.8=−1.4. The figure shows every integer step through t=24 under the same assumptions, with a [step-by-step calculation CSV](figures/delay-trajectories.csv).","assumptions":"Pure mathematical calculation without external inputs, noise, saturation, or state boundaries. Initial histories are completely specified for each d.","boundary":"Finite trajectories do not replace the necessary-and-sufficient proof above and are not device or organizational measurements."},{"title":"Mathematical construction: stable does not mean better at every step","text":"For d=1, k=0.8 lies in 0<k<1. x₁=0.2 and x₂=−0.6, so |x₂|=0.6>|x₁|=0.2: stepwise decrease fails. A predetermined task requiring absolute deviation≤0.1 at t=2 also fails. Asymptotic convergence cannot rewrite that deadline requirement.","assumptions":"All-one initial history. Absolute error and the t=2 threshold are explicit teaching tasks, not real safety thresholds.","boundary":"Evaluate eventual convergence, meeting deadlines, transient peaks, and costs separately."},{"title":"Mathematical construction: the boundary and zero history","text":"For d=0 and k=2, x_{t+1}=−x_t; starting at x₀=1 gives 1,−1,1,−1, never tending to zero, showing why equality is excluded. Although d=2 and k=0.8 exceed the critical value, setting x_{−2}=x_{−1}=x₀=0 keeps the recursion at 0, showing that instability does not mean growth of every trajectory.","assumptions":"Fully specified recursion and initial values; no actual experiment.","boundary":"Zero history cannot establish system stability, while one nondecaying history suffices to refute “all histories tend to zero.”"}],"counterexamples":[{"identity":"source_counterexample","text":"Observing a first-step decrease from 1 to 0.2 leads to declaring the 2-step-delay system stable.","effect":"The same model may grow later; fixed 0.8 exceeds this delay's critical 0.618034.","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"A floating-point root modulus of 0.9999999999999999 is obtained at the boundary, so equality is counted as stable.","effect":"The analytic boundary has a unit-modulus root. Numerical error cannot change the strict condition.","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"Negative deviation is interpreted as a negative number of people queuing, and the corrective gain is deployed directly.","effect":"Variable status and model constraints are incompatible. Actual use requires independent identification and authorization.","sourceIds":["theory"]}],"questionAnswers":[{"question":"Do d=1 and k=1 satisfy strict asymptotic stability?","answer":"No. The critical value is 1, equality is excluded, and a nondecaying mode exists.","basis":"The source text of this section and the public derivation above"},{"question":"Why does finding the first unit-circle intersection not yet prove instability for every larger k?","answer":"One must also rule out roots crossing inward again. The always-positive boundary radial derivative does this.","basis":"The source text of this section and the public derivation above"},{"question":"For d=3 and k=0.8, does an all-zero initial history remaining zero refute instability?","answer":"No. Instability means some nondecaying/growing modes exist, not that every history grows.","basis":"The source text of this section and the public derivation above"},{"question":"Does the d=1 sequence from 0.2 to −0.6 contradict asymptotic stability?","answer":"No contradiction: asymptotic stability does not require absolute error to decrease stepwise.","basis":"The source text of this section and the public derivation above"},{"question":"If an actual processing queue has a measured average delay of 2 steps, may control parameters directly use k<0.618034?","answer":"No. Average delay is not fixed delay. Nonnegative tasks, service constraints, shocks, and execution authority are also unverified; independent modeling and risk analysis are required.","basis":"The source text of this section and the public derivation above"}],"figures":[{"path":"/reading-assets/S-6-2/figures/section-6-2-1.png","alt":"d=0, critical 2, k=0.8: stable, x1=0.2. d=1, critical 1, k=0.8: stable, x1=0.2. d=2, critical 0.618034, k=0.8: unstable, x1=0.2. d=3, critical 0.445042, k=0.8: unstable, x1=0.2. Mathematical construction: k=0.8, all-one initial history; every panel covers t=0…24 with individually labeled vertical axes; dashed k=0 baseline stays 1.","caption":"Mathematical construction: k=0.8, all-one initial history; every panel covers t=0…24 with individually labeled vertical axes; dashed k=0 baseline stays 1."}],"diagramBrief":"The current deliverable is a static diagram; interaction has not been implemented. References below to selecting, switching, or clicking are future design ideas only. Four panels plot stepwise computed trajectories of the same recursion with shared horizontal but different vertical axes. All 25 integer time points are displayed, and the blocked baseline stays 1. Graphics do not replace the analytic stability proof.","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"This is a mathematical proposition under complete assumptions. Proof and reproducible trajectories best show the nonequivalence; no real organization is forced into the role of a verified instance of this equation."},"openQuestions":[],"taskId":"S-6-2","sources":[{"id":"theory","title":"Historical research manuscript: Xikari: On Conditions, Structure, and Transformation, source text supplied by the user","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Historical research draft, full text, lines 1302–1319; see sourceRefs for each section’s exact range","claim_support":["6.2: terminology, contracts, burdens of argument, and boundaries of the original text; no empirical facts are certified on this basis","6.2.1: terminology, contracts, burdens of argument, and boundaries of the original text; no empirical facts are certified on this basis"],"limits":["The author's theoretical text is the object being explained, not a substitute for external empirical material. Skill version 5.3.1 is not the theory's version.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"maryland-renewal","title":"Maryland FY24 Quarter 4 Medicaid Redetermination report","url":"https://health.maryland.gov/mmcp/Documents/JCRs/2023/eligibilityredetprocessJCRfinal4-24.pdf","source_type":"primary","version_or_date":"Report dated April 2024; submission cover letter 2024-05-14","locator":"Printed pp. 8–9 (PDF pages 12–13), Medicaid Mitigation of Ex Parte Renewals","claim_support":["6.2: August 2023 clarification of individual-renewal requirements, state system changes, and actual use of the updated process beginning November 2023."],"limits":["The administrative report lacks the complete G2 contract or independent channel-blockage identification required here; it is not extended to current eligibility or long-term health outcomes."],"access_status":"partially_read"},{"id":"theory-d2","title":"Historical research draft: Xikari 3.3: D2 Effective Feedback","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Chinese source lines 462–471","claim_support":["6.2: return, reception, subsequent fields, and no-return comparison; one effect, stability, and target improvement are separate."],"limits":["A definition is not empirical evidence of actual feedback.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-g2","title":"Historical research draft: Xikari 4.4: G2 Specified Channels","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Chinese source lines 610–619; four-state responsibilities at lines 577–581","claim_support":["6.2: G2 preselected claims and separate channel-dimension measurements; a failed positive gate is not support for zero effect."],"limits":["Retain existing domain evidence’s status without retrospectively awarding formal qualification.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-c10","title":"Historical research draft: Xikari Appendix C.10: Strict Stability Conditions for Fixed-Delay Feedback","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Chinese source lines 4470–4493","claim_support":["6.2.1: characteristic polynomial, stability at small positive gain, unit-circle boundary and outward-crossing proofs; critical values for four delays."],"limits":["Constrains only the disclosed fixed linear model and supplies no prescription for actual parameters.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-v2","title":"Xikari: On Conditions, Structure, and Transformation, v2, November 2026","url":"/downloads/Xikari-条件结构与转化论.md","source_type":"theory_source","version_or_date":"v2 / 2026-11-16","locator":"6.2.1 Feedback delay and stability intervals; Chinese source lines 1336–1343; SHA-256 6ef2e508474d4ac1ad07d7e4e068955342c405b5f680afcfc40d68cca3d0149c","claim_support":["The current source section and this text’s conceptual explanation of v2; not a substitute for external empirical materials."],"limits":["Older research attachments retain their original manuscript identity; the previous scope of external reading has not expanded because of this edition change."],"access_status":"read"}],"lecturePath":"/reading-assets/S-6-2/lecture.md","sourcesPath":"/reading-assets/S-6-2/sources.json","sourceSlicePath":"/reading-assets/S-6-2/source-slice.md","supplementaryFiles":[{"title":"delay-trajectories.csv","path":"/reading-assets/S-6-2/figures/delay-trajectories.csv"}],"diagramsPath":"/reading-assets/S-6-2/diagrams.md","editionNote":"This page’s source text and section locations correspond to v2; historical research attachments and prior external-reading records retain their own versions and scopes.","translationOf":{"language":"zh","lesson_sha256":"0705cb9fe44793a39e3ca6c767b6b3f2a29346199adc176048197c343332f27f","source_sha256":"6ef2e508474d4ac1ad07d7e4e068955342c405b5f680afcfc40d68cca3d0149c"}},"6.3":{"title":"6.3 CM-LEARNING Feedback-mediated learning","lead":"Hearing feedback yesterday and changing something today does not establish future use. Feedback-mediated learning traces what changed, what retains it, whether it was actually used later, and where the predetermined task consequently differs.","explanation":["Source location: Chinese source lines 1344–1361; original anchor section-6-3. Short quotation translated from Chinese: “Current-carrier transmission and historical increments beyond the current representation are two branches requiring separate evidence.” See the corresponding section on this page for the current original; downloaded original research excerpts retain the historical draft.","The basic dependency is CM-FEEDBACK: return from a prior state or output actually causes change; E4, CAUSAL, and EVIDENCE provide review methods. Only then ask whether the update is locatable, retainable, and later used. A before/after comparison of system operation alone cannot distinguish feedback learning from continued external training, member replacement, or changed measurement.","The carrier branch CM-LEARNING-carried has five stages: effective feedback → internal update → carrier retention or continuous updating → actual use in subsequent rounds → changed predetermined task results. Updates may reside in parameters, rules, memory, structure, or other internal states, not only readable archives. Retention may depend on continued maintenance rather than a one-time immutable write. The key is specifying location, version, sequence, and the use path.","Minimum material must connect pre/post-update states, carrier maintenance, repeated use, and task comparisons. Causal explanation additionally requires proportionate interruption, replacement, restoration, or comparisons meeting identification conditions, addressing shared inputs, continued training, selection, attrition, and measurement changes. All comparisons follow targets and permitted operations. Necessary support must not be removed, nor people forcibly intervened upon, merely to validate the theory. Cross-context transfer or out-of-sample predictive-gain claims require proportionate independent-task or out-of-sample material.","One parameter change, one success, one write-back, and archiving each cover only part of the chain. If updates are not retained or later used, shared inputs explain results, or only proxy scores improve without changing the predetermined task, the corresponding learning mechanism lacks support. Report where the chain breaks. Uncertain net effects do not establish no learning, and changed practices do not establish every mechanism.","Beyond the carrier chain, the historical-increment branch CM-LEARNING-history asks whether past history adds explanation or prediction of predetermined subsequent outcomes conditional on an explicitly registered current representation, supported by a qualified G3-instance. Carrier-mediated learning may be fully retained in current parameters, leaving no need for extra history without canceling what was learned. Conversely, useful historical variables alone do not establish the whole return–update–retention–use chain.","The two routes therefore need separately declared comparisons, counterexamples, and failure conditions beforehand. Known current parameters cannot be deleted to manufacture historical increments. Missing use evidence on the carrier route cannot be rescued by saying “history matters,” nor can failed historical-increment checks prompt retrospective switching of the primary criterion. The carrier route may hold independently, but through its own material, not the room left by another branch's failure.","Ordinary learning need not wait for this framework's formal certification. Repeatable new-task performance, retained skills, or traceable teaching/organizational processes within a domain may support learning judgments within their respective scopes. “Practices changed,” “the feedback-mediated mechanism is insufficiently identified,” and “subsequent net benefit remains uncertain” can all be reported without contradiction. Missing framework eligibility does not erase independent facts; domain conclusions do not automatically establish every framework mechanism either.","Established learning does not mean improvement and creates neither a unified objective nor authority to act. Changed targets require public reasons and decision procedures, retention of failures, results, and costs under old targets, and a new comparison for the new task. Retrospectively renaming the original mistaken task “exploration” cannot declare success.","Also distinguish supported completion, independent transfer after support withdrawal, and subsequent life outcomes. Necessary support may constitute part of a collaborative/expression task, in which case failure without it does not cancel prior supported success. If the predetermined target is independent transfer, assisted performance cannot masquerade as independent capability. Whether support must remain, target selection is reasonable, updates persist, performance improves, and net benefits arise each carries its own evidential responsibility.","If learning changes the target, register under §2.14 who proposes reopening, which new material or omissions justify it, and who decides, while retaining results and costs under the old target. If training later shifts to another occupation, for example, learning on the new task can be evaluated, but failure at the original occupational task cannot become success of the original plan. Ordinary skill formation, current-carrier transmission, and G3 additional historical increments remain separate judgments."],"distinctions":[{"leftTitle":"Update retention","leftText":"The carrier retains or continuously maintains the update into later windows.","rightTitle":"Actual use","rightText":"Later tasks actually read and use it; storage is not use."},{"leftTitle":"Carrier-based learning","leftText":"The current carrier takes up the update and affects later tasks.","rightTitle":"Additional historical increment","rightText":"History still supplies a conditional increment given the current representation; G3 is additionally required."},{"leftTitle":"Supported performance","leftText":"Completion with tools or collaborative support under the original task contract.","rightTitle":"Independent transfer","rightText":"Completion under explicitly specified support-withdrawal/new-context conditions. The two cannot masquerade as each other."},{"leftTitle":"Task difference","leftText":"A reviewable change in the predetermined task outcome.","rightTitle":"Net benefit","rightText":"A separate judgment combining objectives, costs, risks, and distribution."}],"boundaries":["Effective feedback whose update resets each round may have a one-time effect without cross-round learning through that carrier.","Additional historical increments may be zero when the current carrier is sufficient; learning does not disappear thereby.","Deleting a known parameter within a model creates insufficient representation. Concealing that deletion cannot justify claiming that history is ontologically irreducible.","When support belongs to the original task, unsupported failure cannot cancel supported success. Independent transfer still requires its own comparison.","Mere evidence insufficiency remains unresolved; reject a specific claim only with proportionate counterevidence. Unknown long-term net benefit is not zero learning of every kind."],"questions":["If model carrier θ=2 is retained but never read by the later program, which link of learning-mechanism evidence is missing?","If current parameters already contain what was learned and the G3 increment is zero, does that negate carrier-mediated learning?","Why is the old parameter's squared error 36 when the mathematical predictor tests u=3?","How should changed organizational practices after training be reported when material is insufficient to assess the net effect?","May completion with an assistive tool directly establish independent capability?"],"diagramPath":"/reading-assets/S-6-3/figures/section-6-3.png","caseLinks":[{"title":"Maryland's new renewal process: starting use still differs from long-term learning","href":"https://health.maryland.gov/mmcp/Documents/JCRs/2023/eligibilityredetprocessJCRfinal4-24.pdf"},{"title":"London taxi trainees: distinguish qualification, task performance, and learning mechanisms","href":"/en/cases/london-taxi-learning"}],"caseNotes":[{"title":"Maryland's new renewal process: starting use still differs from long-term learning","text":"The 2024 Maryland report explicitly records use of the updated ex parte renewal process beginning in November 2023 and states that future renewals will continue using the modifications. This section adds the evidential tense distinction between “already used” and “will continue to be used”: the former is an implementation fact reported in the document, the latter a prospective arrangement. A future plan alone cannot establish multi-round retention, stable use, or long-term net effects.","sourceLabel":"Maryland FY24 Quarter 4 report, submitted 2024-05-14","sourceUrl":"https://health.maryland.gov/mmcp/Documents/JCRs/2023/eligibilityredetprocessJCRfinal4-24.pdf","sourceLocator":"Final paragraph of printed p.9, “updated ex parte systems process was utilized beginning November 2023” and the immediately following “Moving forward” sentence","boundary":"Supports the process change already in use at the report date. It supplies neither causal comparisons for this section's complete feedback-carrier chain, task effects across rounds, nor long-term health benefits. The administrative implementation fact remains.","href":"https://health.maryland.gov/mmcp/Documents/JCRs/2023/eligibilityredetprocessJCRfinal4-24.pdf"}],"sourceRefs":[{"section":"6.3","start_line":1390,"end_line":1407,"startLine":1390,"endLine":1407}],"outputId":"section-6-3","sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","argumentSteps":["Specify the task, baseline, window, and support conditions, then locate effective return and the internal fields it changes.","Trace update-carrier versions, retention/continuous updating, and repeated later use. Archiving cannot replace use.","Compare predetermined task outcomes and check shared inputs, continued training, selection, attrition, and measurement changes.","Transfer or predictive-gain claims require separate independent-task/out-of-sample evaluation. Comparisons must not cause unauthorized interruption of support.","Separate carrier and historical-increment routes beforehand. The latter additionally requires G3 relative to a fully explicit current representation.","Independently retain evidence of ordinary learning and changed organizational practices, while closing specific mechanisms and net benefits separately.","Changed targets retain the old task's accounting and initiate new comparisons. Acquired function, independent transfer, later life outcomes, and authority are not merged."],"teachingExamples":[{"title":"Mathematical construction: feedback writes a parameter, and later use yields calculable differences","text":"A fictional predictor outputs y=θu, initially θ=0, with target rule y*=2u. In training round u=1, actual output is 0; comparing against target 2 returns error e=2−0=2, and θ←θ+e writes parameter 2. Training then stops; θ is retained and actually used in two new rounds u=2 and u=3, yielding outputs 4 and 6 with squared errors 0 and 0. The baseline retaining old θ=0 outputs 0 and 0, with squared errors 16 and 36. Replacing the carrier with θ=0 only before use restores errors 16 and 36; restoring θ=2 returns them to 0 and 0. The complete model connects return, update, retention, use, and task differences.","assumptions":"Target, training and update rules, test inputs, and carrier replacement are all artificial assumptions. No other external inputs or parameter changes occur. There is one training round and two subsequent use rounds.","boundary":"This is a mathematically computable construction, not an actual machine experiment. Different test inputs do not establish arbitrary real-world generalization across contexts or a formal G instance."},{"title":"Mathematical construction: learning retained in the current state, with zero historical increment","text":"Continue with the predictor. The complete current registration includes θ=2 and input u, so the output must be 2u. Whatever the number or ordering of earlier training rounds, histories ending in the same θ give identical future outputs; additional history cannot reduce an already zero prediction error. Carrier learning is therefore compatible with disappearance of an additional historical increment. If the current representation is deliberately changed to “whether the parameter is nonzero,” θ=1 and θ=2 collapse together, and history may help distinguish them. This coarsening must be disclosed; a known θ cannot be deleted while pretending that no current carrier exists.","assumptions":"The output rule is fixed and deterministic; θ contains all callable learned content in this example, and the comparison model may read it.","boundary":"Whether an actual carrier is sufficient requires evidence; sufficiency in this construction cannot be directly generalized."},{"title":"Teaching construction: supported and independent tasks are different examinations","text":"A fictional decoding task permits a code table, and a participant correctly completes three decodings. If the original target was “complete with the table,” the table cannot suddenly be removed and failure used to cancel the original success. If the original target was “decode independently without the table,” the first three performances do not establish it. This example only illustrates the evaluation contract; three performances alone do not prove feedback-mediated learning or retained updates.","assumptions":"A purely teaching scenario, with no actual participants, measurements, or support-withdrawal trial; whether the code table is available is declared before evaluation.","boundary":"This does not advocate withdrawing necessary support in reality; independent comparisons must account for ethics, risks, and permissions."},{"title":"Mathematical construction: rewriting a target cannot erase failure on the old task","text":"If the original target requires output 2 and the actual output is 3, squared loss is (3−2)²=1. Setting a new target of 3 afterward makes the new task's loss 0, but the original task's loss remains 1. The new target also requires a reasonable formation process and subsequent comparisons. Changing the numbers changes the evaluation question, not the past output.","assumptions":"The two targets and shared output are constructed; the new target is not presumed inherently wrong or right.","boundary":"Success under a new target cannot remove the old target's failure record, costs, or responsibility."}],"counterexamples":[{"identity":"constructed_boundary","text":"The parameter file has been updated, but the executing program still reads the old version; nevertheless, later tasks are said to have been learned.","effect":"Storage and actual use are disconnected, so this carrier chain is unsupported.","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"A task is completed with support but fails after support is withdrawn, so all acquired functions are declared nonexistent.","effect":"The evaluation conditions have changed; supported completion and independent transfer should be reported separately.","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"The current parameters sufficiently predict the result, and history no longer improves prediction, so learning is said not to have occurred.","effect":"This wrongly treats an additional historical increment as necessary for carrier learning.","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"A proxy score rises while the prespecified actual task remains unchanged; the target is then changed to the score and learning declared successful.","effect":"A target change must be disclosed and separately compared; it cannot rescue the original task.","sourceIds":["theory"]}],"questionAnswers":[{"question":"If model carrier θ=2 is retained but never read by the later program, which link of learning-mechanism evidence is missing?","answer":"Evidence of actual use and the prespecified task difference caused by that use is missing; storage alone is insufficient.","basis":"The source text of this section and the public derivation above"},{"question":"If current parameters already contain what was learned and the G3 increment is zero, does that negate carrier-mediated learning?","answer":"No. Carrier learning and historical increments beyond the current representation require separate evidence; the former does not necessarily require the latter.","basis":"The source text of this section and the public derivation above"},{"question":"Why is the old parameter's squared error 36 when the mathematical predictor tests u=3?","answer":"Old θ=0 outputs 0, the target is 2×3=6, and squared error is (0−6)²=36.","basis":"The source text of this section and the public derivation above"},{"question":"How should changed organizational practices after training be reported when material is insufficient to assess the net effect?","answer":"Preserve the fact that the practice changed. Separately list evidence/gaps for the feedback-learning mechanism and unresolved net effects, rather than compressing them into a single success or failure.","basis":"The source text of this section and the public derivation above"},{"question":"May completion with an assistive tool directly establish independent capability?","answer":"No, unless the original target and proportionate evaluation cover independent transfer. Likewise, unproven independent transfer cannot cancel completion under the original conditions.","basis":"The source text of this section and the public derivation above"}],"figures":[{"path":"/reading-assets/S-6-3/figures/section-6-3.png","alt":"Effective feedback: return actually causes change, the basic dependency; locatable update: state / parameters / rules, with versions and timing recorded; explicit carrier: retention or continuing updates, since archiving is not use; subsequent repeated use: entering the prespecified task, checking interruption / replacement / restoration; task comparison: differences against a prespecified baseline, with net benefit and authorization checked separately; additional-history branch: G3 relative to the current representation, not necessary for carrier learning. Arrows indicate connections to check. The lower-left branch is a separately declarable historical branch, not an additional mandatory gate for carrier learning.","caption":"Arrows indicate connections to check. The lower-left branch is a separately declarable historical branch, not an additional mandatory gate for carrier learning."}],"diagramBrief":"The current deliverable is a static diagram; interaction has not been implemented. Any selection, switching, or clicking described below is only a future design proposal. Six cards show return, carriers, use, and results; the historical branch adds G3 only for a separate claim of an increment beyond the current representation. Support, independent transfer, and net benefit are evaluated separately.","applicability":{"realCase":"applicable","diagram":"applicable","reason":"Actual implementation records help distinguish material on updates, completed use, and future continuation. The mathematical example fully discloses its assumed mechanism, without retroactively granting an administrative report formal learning-instance status."},"openQuestions":[],"taskId":"S-6-3","sources":[{"id":"theory","title":"Historical research manuscript: Xikari: On Conditions, Structure, and Transformation, source text supplied by the user","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Historical research manuscript, Chinese source lines 1320–1337; see sourceRefs for each section's exact range","claim_support":["6.3: terminology, contracts, burdens of argument, and boundaries of the original text; not a basis for certifying empirical facts"],"limits":["The author's theoretical text is the object being explained, not a substitute for external empirical material. Skill version 5.3.1 is not the theory's version.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"maryland-use","title":"Maryland FY24 Quarter 4 report: actual use and continuation plans","url":"https://health.maryland.gov/mmcp/Documents/JCRs/2023/eligibilityredetprocessJCRfinal4-24.pdf","source_type":"primary","version_or_date":"Report dated April 2024; submission cover letter 2024-05-14","locator":"Printed p. 9, final paragraph of Medicaid Mitigation of Ex Parte Renewals","claim_support":["6.3: the new process was actually used from November 2023; the following sentence describes an arrangement for future continued use."],"limits":["Beginning use and a plan do not alone establish long-term retention and use, causal learning, or net health benefits."],"access_status":"partially_read"},{"id":"theory-history","title":"Historical research manuscript: Xikari 4.5: current carriers and historical increments","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Chinese source lines 620–640","claim_support":["6.3: separate formation, current transmission, and additional historical increments; known current states cannot be deleted to manufacture residuals."],"limits":["Mathematical sufficiency cannot replace measurement of actual carriers.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-feedback","title":"Historical research manuscript: Xikari 6.2: effective feedback","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Chinese source lines 1302–1311","claim_support":["6.3: the basic dependency is return with an effect, without requiring persistent history or G3."],"limits":["Basic feedback does not automatically constitute learning.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-v2","title":"Xikari: On Conditions, Structure, and Transformation, v2, November 2026","url":"/downloads/Xikari-条件结构与转化论.md","source_type":"theory_source","version_or_date":"v2 / 2026-11-16","locator":"6.3 CM-LEARNING Feedback-Mediated Learning; Chinese source lines 1344–1361; SHA-256 6ef2e508474d4ac1ad07d7e4e068955342c405b5f680afcfc40d68cca3d0149c","claim_support":["The current source section and this text’s conceptual explanation of v2; not a substitute for external empirical materials."],"limits":["Older research attachments retain their original manuscript identity; the previous scope of external reading has not expanded because of this edition change."],"access_status":"read"}],"lecturePath":"/reading-assets/S-6-3/lecture.md","sourcesPath":"/reading-assets/S-6-3/sources.json","sourceSlicePath":"/reading-assets/S-6-3/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-6-3/diagrams.md","editionNote":"The relevant explanation in this section has been revised for v2; the original research attachments and the scope of external-source review retain their historical status.","translationOf":{"language":"zh","lesson_sha256":"56208d5909b207e3b524555114797b35d28201e6af7cf49ae136cdf844268291","source_sha256":"6ef2e508474d4ac1ad07d7e4e068955342c405b5f680afcfc40d68cca3d0149c"}},"6.4":{"title":"6.4 A Fictional Appeal Example of Feedback, Institutional Write-Back, and Learning","lead":"The same appeal may stop at “received,” change case fields, be implemented, or even influence processing across later rounds. Every additional level of claim adds an evidential responsibility; one acknowledgment cannot cross every step.","explanation":["Chinese source location: lines 1362–1375; original anchor: section-6-4; short quotation, translated from the Chinese: “This example only demonstrates a classification method.” See the corresponding section on this page for the current original text; the downloaded original research excerpt preserves the historical manuscript.","The original text explicitly posits a fictional institution, so the following teaches classification rather than reporting an actual appeal or providing external empirical proof. We fix the same object, appeal, and observation window, varying subsequent conditions to see how far a claim may go. This is not a maturation ladder that real institutions necessarily follow.","In the first scenario, the appeal is received and an acknowledgment generated, while the registered records, rules, resources, roles, responsibilities, memory, and stopping conditions all remain unchanged. The acknowledgment establishes signal arrival, not automatic change in any relevant subsequent field. Define acknowledgment metadata and the institutional fields in question beforehand. If an actual acknowledgment itself triggers scheduling or stopping conditions, it is no longer this example's “all unchanged” case; actual channels and effects require rechecking.","In the second scenario, the appeal changes a case-status field through a specified channel, but execution has not begun. Given proportionate causal comparison, this can satisfy D2's return effect: a status field is also a subsequent state, and feedback need not await a changed final outcome. H3, however, requires field change and actual execution, so complete institutional write-back cannot yet be claimed. A field changing later in time is not itself evidence that “the appeal caused it.”","The third scenario carries the field change into actual execution, separately recording acceptance, before/after field versions, execution, and duration, satisfying the example's write-back classification. Duration is part of the contract; one execution does not imply permanent validity. H3 is a classification rule, not an abstract empirical truth or permission to alter an institution. C11 additionally requires G2 and D2 comparisons for the specified feedback channel. Successful classification and complete empirical-mechanism support must not be conflated.","The fourth scenario additionally requires a retainable rule or state update, actual use in multiple later rounds of similar cases, prespecified task comparisons, and corresponding causal grounds before a carrier-based feedback-mediated learning candidate can be proposed. One write-back does not automatically establish preservation and use across rounds. Repeated identical later outcomes may also arise from continuing external instructions or shared environments; proportionate competing explanations must be excluded. A further claim of an additional historical increment beyond the current state is tested separately by G3.","Evidential gates increase with claim strength in this example, but this does not mean learning in every field must first pass through institutional write-back. The fixed route here is “how an appeal changes an institution and affects later cases.” Learning generally may occur in other carriers, assessed separately under 6.3. Diagram arrows also do not guarantee that receipt eventually leads to learning; every connection may stop.","A write-back fact guarantees neither institutional justification nor long-term repair. Executing an improper rule may still involve actual field changes and implementation; record facts and normative issues separately. A rule's unjustified character cannot erase effects that occurred, and successful execution cannot endorse its justification. Repair targets, responsibility, authorization, and implementation procedures remain separate judgments.","For actual material, list “already occurred,” “insufficient evidence,” and “plan only” individually. An open entry point, public response, field modification, actual execution, retained use, and task effects each have their place. Missing execution evidence cannot justify inventing implementation, while missing long-term material cannot deny an evidenced short-term change. Teaching tables merely organize material; entering “yes” is not the material itself."],"distinctions":[{"leftTitle":"Acceptance / acknowledgment","leftText":"Confirms arrival or the start of processing.","rightTitle":"Field change","rightText":"Requires locating before/after differences in relevant fields and checking their source."},{"leftTitle":"Effective feedback","leftText":"A specified return produces differences in subsequent states or related quantities.","rightTitle":"Complete institutional write-back","rightText":"This example additionally requires institutional-field changes to enter actual execution, with duration recorded."},{"leftTitle":"One write-back","leftText":"The modification in this round has been implemented.","rightTitle":"Carrier-based learning","rightText":"A retainable update is repeatedly used later and changes the prespecified task."},{"leftTitle":"H3 classification","leftText":"Distinguishes acceptance, modification, and execution under given rules.","rightTitle":"Empirical support or authorization","rightText":"Requires corresponding evidence or norms/procedures; classification cannot replace them."}],"boundaries":["This section has no actual appeal object; its constructed states, counts, and losses must not be treated as administrative statistics.","The successive added conditions here concern only the appeal route, not a claim that all learning depends on H3 institutional write-back.","Field change can coexist with lack of execution; incomplete final implementation cannot cancel evidenced state feedback.","One execution guarantees neither persistence, learning, repair, nor justification; duration cannot be left blank and then assumed permanent.","Knowing that no relevant change occurred differs from lacking material observing change. With insufficient material, retain unresolved status rather than treating missing records as absent events."],"questions":["If a case field changes from 0 to 1 but execution has not occurred, why can we not simply say “nothing happened”?","If an announcement says a new rule was approved but implementers still use the old rule, at which level should the claim stop?","Does version D's three uses automatically establish a historical increment independent of the current state?","If the original target is correct review, old output is 0, and new output is 1, what are the mean squared losses across the three cases?","Must all feedback learning first undergo institutional write-back?"],"diagramPath":"/reading-assets/S-6-4/figures/section-6-4.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"6.4","start_line":1408,"end_line":1421,"startLine":1408,"endLine":1421}],"outputId":"section-6-4","sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","argumentSteps":["Declare this to be the author's fictional classification example; fix the object, fields, time window, and appeal route without fabricating an actual case.","First check arrival/acknowledgment, then field changes caused by the specified return; do not merge the two.","A field change with proportionate return comparison may constitute feedback. If it has not entered execution, stop there without upgrading to complete write-back.","After actual execution, separately record acceptance, versions, execution, and duration, classifying under H3 while separately checking causal-mechanism eligibility.","Only after checking retention, multi-round use, prespecified task comparisons, and causal material should a carrier-learning candidate be proposed.","If an additional historical increment is claimed, check G3 independently; do not make it a mandatory gate for every write-back or learning claim.","Finally distinguish write-back facts, learning, long-term repair, justification, and permissions, locating gaps at specific levels."],"teachingExamples":[{"title":"Teaching construction: distinguishing four versions item by item","text":"A fictional system defines case status s=0 as awaiting the original process and s=1 as entering review. It also registers actual execution e, rule retention p, and subsequent use count n. Version A only receives the appeal, with s=0, e=0, p=0, n=0: arrival only. Version B changes s to 1 under the given return rule, but e=0: state feedback within the model, without complete write-back. Version C adds review execution e=1 to B, recording acceptance, field change, execution time, and a two-day validity period: it permits a one-time write-back classification. Version D additionally retains the update p=1, uses it in three later similar cases n=3, and adds task and causal comparisons: only then does the material reach the level needed to propose a carrier-learning candidate.","assumptions":"Entirely constructed. B's rule explicitly states s=1 with this return and s=0 without it, holding other conditions fixed. The flags are given model states, not certification produced by filling out a real-world form.","boundary":"Even D cannot establish an actual mechanism merely from p=1 and n=3; corresponding actual material is required, and neither additional history nor net benefit has thereby been proved."},{"title":"Mathematical construction: task comparison needs explicit rules","text":"Continue with version D. For all three new cases, the prespecified task is correct entry into review, with ideal output y*=1. The old rule outputs 0 for all three specified inputs; the new retained rule outputs 1. Old mean squared loss is [(0−1)²×3]/3=1; new loss is 0. In the model, replacing only the rule with the old version before use returns loss to 1; restoring the new rule returns it to 0. This provides a computable connection between use and outcome. “Used three times” without these comparisons cannot directly count as success.","assumptions":"Inputs, targets, both rule versions, and the meaning of replacement are artificially fixed; no shared external instruction changes outputs.","boundary":"The model contains no actual case rights, resource costs, or legal effects; it cannot adjudicate an actual institution."},{"title":"Teaching construction: an acknowledgment may trigger an effect, but the question must change","text":"A fictional system stipulates that generating a receipt acknowledgment pauses the case-deadline clock for 24 hours. If this rule is actually executed, a stopping condition has changed, so the case cannot remain in version A, where “all relevant fields remain unchanged.” Register the changed field and channel, distinguishing the clock pause from subsequent substantive review. The pause alone proves neither ultimate appeal success nor long-term learning.","assumptions":"An explicit conditional counterfactual, not a description of any current appeal system; 24 hours is a teaching assumption.","boundary":"Not every actual acknowledgment can be presumed to suspend deadlines, and this provides no advice on legal time limits."}],"counterexamples":[{"identity":"source_counterexample","text":"Original fictional example A has only an acknowledgment; all relevant institutional fields remain unchanged.","effect":"An entry point or response alone cannot establish effective feedback and write-back.","sourceIds":["theory"]},{"identity":"source_counterexample","text":"Original fictional example B changes a field but has no execution.","effect":"State feedback in D2's sense may exist, but complete H3 write-back cannot be claimed.","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"An appeal prompts modification and actual execution of a harmful rule, so the institution is declared justified and repair complete.","effect":"Factual classification, normative evaluation, and long-term repair cannot replace one another.","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"No subsequent execution record is found, so it is concluded that execution never occurred in reality.","effect":"Missing evidence does not automatically mean an event was absent; distinguish verified nonexecution from non-observation.","sourceIds":["theory"]}],"questionAnswers":[{"question":"If a case field changes from 0 to 1 but execution has not occurred, why can we not simply say “nothing happened”?","answer":"If proportionate evidence supports the specified return's effect, the state has changed; it still fails the execution condition for complete institutional write-back.","basis":"The source text of this section and the public derivation above"},{"question":"If an announcement says a new rule was approved but implementers still use the old rule, at which level should the claim stop?","answer":"Preserve the announcement/approval fact and check specific field changes; an announcement cannot masquerade as actual execution and complete write-back.","basis":"The source text of this section and the public derivation above"},{"question":"Does version D's three uses automatically establish a historical increment independent of the current state?","answer":"No. A carrier update may sufficiently contain what was learned; additional increments require separate G3 testing relative to an explicit current representation.","basis":"The source text of this section and the public derivation above"},{"question":"If the original target is correct review, old output is 0, and new output is 1, what are the mean squared losses across the three cases?","answer":"The old loss is 1 and the new loss 0, holding only within the given model, target, and three-input scope.","basis":"The source text of this section and the public derivation above"},{"question":"Must all feedback learning first undergo institutional write-back?","answer":"No. This section fixes an institutional appeal route; learning in other carriers is tested independently under 6.3.","basis":"The source text of this section and the public derivation above"}],"figures":[{"path":"/reading-assets/S-6-4/figures/section-6-4.png","alt":"A: receipt acknowledgment only, relevant fields unchanged, register arrival only; B: return changes fields but has not entered execution, so feedback may exist while write-back remains incomplete; C: field change implemented, with acceptance / versions / execution and duration recorded separately; D: retained update and use in subsequent repeated cases, with task and causal comparisons; carrier-learning candidate, not equivalent to long-term repair and conferring neither justification nor authorization; a separate historical claim requires G3 relative to the current representation, which is not required for every preceding level. Entirely fictional conditional versions; arrows are not records of actual upgrading. This route does not mean all learning must involve institutional write-back.","caption":"Entirely fictional conditional versions; arrows are not records of actual upgrading. This route does not mean all learning must involve institutional write-back."}],"diagramBrief":"The current deliverable is a static diagram; interaction has not yet been implemented. Any selection, switching, or clicking described below is only a design proposal for later. Six cards develop the original example through receipt, feedback, write-back, repeated use, candidate learning, and an optional separately proposed historical branch. Every arrow requires checking conditions; the diagram certifies no real institution.","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"The original section explicitly teaches classification through a fictional institution. Its identity is retained and developed through conditional variants, without forcing in real historical facts or inventing appeal cases presented as real."},"openQuestions":[],"taskId":"S-6-4","sources":[{"id":"theory","title":"Historical research manuscript: Xikari: On Conditions, Structure, and Transformation, source text supplied by the user","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Historical Chinese research draft, full text lines 1338–1351; see sourceRefs for each section's exact range","claim_support":["6.4: terminology, contracts, argumentative responsibilities, and source boundaries; no empirical facts are certified on this basis"],"limits":["The author's theoretical text is the object being explained, not a substitute for external empirical material. Skill version 5.3.1 is not the theory's version.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-h3","title":"Historical research draft: Xikari 7.1, H3 institutional write-back classification and authority boundaries","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Chinese source lines 1467–1482, especially 1477 and 1482","claim_support":["6.4: H3 is a classification rule; field changes require actual execution. Classification does not authorize modifying records or rules."],"limits":["Neither an empirical instance nor a ruling on legal effect.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-c11","title":"Historical research draft: Xikari 4.13.4, C11 institutional write-back","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Chinese source lines 885–897","claim_support":["6.4: D2/G2 and H3 have different responsibilities; acceptance for processing, field change, execution, and duration are separate."],"limits":["Having the fields does not automatically establish a causal mechanism.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-learning","title":"Historical research draft: Xikari 6.3, two branches of feedback-mediated learning","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Chinese source lines 1320–1337","claim_support":["6.4: retainable updates, use across multiple rounds, task comparisons, and causal grounds; add G3 only for additional history."],"limits":["This section's fictional example certifies no real learning.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-v2","title":"Xikari: On Conditions, Structure, and Transformation, v2, November 2026","url":"/downloads/Xikari-条件结构与转化论.md","source_type":"theory_source","version_or_date":"v2 / 2026-11-16","locator":"6.4 A fictional appeal example of feedback, institutional write-back, and learning; Chinese source lines 1362–1375; SHA-256 6ef2e508474d4ac1ad07d7e4e068955342c405b5f680afcfc40d68cca3d0149c","claim_support":["The current source section and this text’s conceptual explanation of v2; not a substitute for external empirical materials."],"limits":["Older research attachments retain their original manuscript identity; the previous scope of external reading has not expanded because of this edition change."],"access_status":"read"}],"lecturePath":"/reading-assets/S-6-4/lecture.md","sourcesPath":"/reading-assets/S-6-4/sources.json","sourceSlicePath":"/reading-assets/S-6-4/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-6-4/diagrams.md","editionNote":"This page’s source text and section locations correspond to v2; historical research attachments and prior external-reading records retain their own versions and scopes.","translationOf":{"language":"zh","lesson_sha256":"9cca81ed3274e4e91550eb649f2e18a1948b96652730b3b5a455032ea9232802","source_sha256":"6ef2e508474d4ac1ad07d7e4e068955342c405b5f680afcfc40d68cca3d0149c"}},"6.5":{"title":"6.5 CM-MAINTENANCE Maintenance and preservation–dissolution","lead":"A machine that keeps running or a service that stays open may depend on someone continuously replenishing, replacing, correcting, or clearing obstacles. Maintenance analysis identifies how those specific inputs preserve identity or function, while asking what is preserved, who bears the work, and whether a backup can actually take over when failure occurs.","explanation":["Chinese source location: lines 1376–1391; source anchor section-6-5; short quotation, translated from Chinese: ‘Redundancy is tested against failure conditions, not merely by counting backups.’ See the corresponding section on this page for the current source; the downloadable original research excerpt preserves the historical draft.","The basic dependencies are D0 and G2: first specify the complete object contract, in which K is only the identity criterion, then identify the specified maintenance channel. D1 bounds state terms such as persistence, disintegration, and repair, while E4, CAUSAL, and EVIDENCE review explanations and evidence. Declare the current K or functional criterion F and the window in advance to determine what maintenance preserves. ‘It still seems to be there’ does not automatically mean every function is normal.","The mechanism chain is wear, drift, loss, or component exit → specified maintenance channel → replenishment/replacement/correction/clearance → changed duration of K or F preservation or failure probability. The result may extend usable time or change failure risk without returning the state to its initial value each time. Minimum comparison requires more than ‘a work order exists’: appropriate evidence across maintenance, reduced-maintenance, mismatched-maintenance, and stopping conditions, with G2 channel identification, is also needed. Real comparisons involving stopping maintenance are constrained by risk and authority; essential services cannot be arbitrarily shut down for verification.","The current branch asks about current inputs' effects on preserving K/F within the current window. The carried-cumulative branch additionally traces how earlier inputs form current wear or capability carriers, how they are retained/replenished across windows, and the longitudinal and causal grounds for maintenance changing subsequent preservation. cumulative is the additional historical-increment branch: add G3 only when claiming that history has extra effects given the current representation. When current wear already sufficiently takes up the past, there may be no additional historical increment.","If an object preserves K/F without sustained maintenance within the target window, maintenance necessity cannot be extrapolated into that window. If changes to maintenance inputs do not change relevant outcomes, or supposed wear actually comes from an independent shock, narrow or withdraw the corresponding claim. If comparisons lack sensitivity, retain unresolved status rather than treating unmeasured differences as zero effects. Continuing to use an old criterion after K has changed conflates maintenance with object transformation; recheck the object contract.","A need for maintenance is not a normative reason for permanent persistence. A replenishment channel's existence does not automatically assign its burden to someone or create an obligation to sacrifice. Mismatched maintenance may sustain an old object's K while damaging the target F; orderly stopping, transformation, or disintegration may also be permitted outcomes. Whether to maintain, toward which target, and who decides and executes remain questions for norms, authorization, and procedures. Technical feasibility does not imply obligation.","Normal operation, migration, failure, and recovery are different tasks. Interface standards describe conditions for possible interoperability; implementation versions, operational semantics, environmental loads, testing, and on-site adaptation determine actual compatibility in this instance. Parts in storage still require checking specifications, quality, transportation, on-site skills, and shutdown authority. ‘Exists’ cannot be collapsed into ‘usable in time.’ Replaceability under ordinary conditions also differs from completing replacement within an emergency window.","Maintenance may move outside the original object boundary and be supplied by users, families, outsourced workers, or other institutions. Fewer central work orders with maintained output need not mean less total maintenance labor. Record where external burdens are borne, the workload, time, support, and right to stop. Only same-type quantities may be summed under explicit definitions; heterogeneous labor, risk, time, and rights must not be compressed into a unitless universal cost.","Redundancy must address failure conditions, not merely count backups. Two paths may share power, software state, transportation, suppliers, operators, or approval nodes. They may substitute for one another normally yet fail together during a fault. Check backup capacity, common-cause exposure, switching time, on-site skills, and actual switching authority separately; do not presume that two units mean independent reliability.","Recovery also depends on communications, roads, fuel, spare parts, and personnel, whose accessibility must be checked within the same failure window. If lost communications prevent obtaining switching permission, or blocked roads prevent parts from arriving, a backup on paper may not become actual recovery. Adding backups, reducing coupling, and retaining locally independent operation are all candidate designs; their net effects still depend on failure types, maintenance costs, and specific tasks."],"distinctions":[{"leftTitle":"Preserve K","leftText":"The object continues to satisfy the declared identity criterion.","rightTitle":"Preserve F","rightText":"Continue to meet specific functional requirements; the two can diverge."},{"leftTitle":"A backup exists","leftText":"Another component or path is present.","rightTitle":"Usable during failure","rightText":"Capacity, common exposure, switching, arrival on site, and authority all fit the current window."},{"leftTitle":"Standard interface","leftText":"Specifies types and rules for possible interoperability.","rightTitle":"Actual compatibility","rightText":"A usable connection under specific implementations, semantics, environments, and loads."},{"leftTitle":"Maintenance is necessary","leftText":"Function depends on certain inputs within a specified scope.","rightTitle":"Someone must continue bearing the burden","rightText":"Still requires norms, responsibility, and authority; it does not follow directly."}],"boundaries":["No need for sustained maintenance in a short window does not imply no need in every longer window; long-window evidence also cannot replace the original short-task conclusion.","Current wear may sufficiently take up the past; G3 need not be required before recognizing cumulative carrier effects.","If one still says ‘maintaining the same object’ after the original K fails, check whether transformation or disintegration has occurred; do not silently retain the old contract.","Redundancy tests under normal power and transportation conditions do not automatically cover common-cause failures and recovery phases.","Improved central metrics may accompany increased external labor; maintenance capability does not directly create an obligation for any named person."],"questions":["Why does the wear model with m=1 first fail at step four?","Why can model B's dual failure not be calculated as 0.1×0.1?","If maintenance is necessary to preserve function, does that suffice to designate a particular employee to continue bearing it?","Why might recovery targets remain unmet despite an existing backup with enough capacity?","If current wear fully reflects the past and additional history provides no increment, does this exclude cumulative maintenance effects?"],"diagramPath":"/reading-assets/S-6-5/figures/section-6-5.png","caseLinks":[{"title":"STS-114: spare parts must enter actual replacement","href":"https://www.nasa.gov/mission/sts-114/"}],"caseNotes":[{"title":"STS-114: spare parts must enter actual replacement","text":"NASA's mission record states that during the second extravehicular activity on August 1, 2005, Noguchi and Robinson removed failed CMG-1, moved a new control moment gyroscope out of the payload bay, and installed it. The record then reports four working CMGs on the space station. This section adds the distinction among a spare part's existence, transportation to position, personnel operations, installation, and operating state, rather than repeating the image-feedback case.","sourceLabel":"NASA STS-114 mission page, updated 2025-05-01","sourceUrl":"https://www.nasa.gov/mission/sts-114/","sourceLocator":"Mission Highlights, EVA No.2 (Aug.1) entry; for CMG function, see the sentence following the preceding EVA No.1 entry","boundary":"This supports the mission record of that replacement and the operating count at the time. It does not quantify long-term reliability, independent redundancy, or every counterfactual concerning maintenance necessity, and does not confer formal G2 eligibility.","href":"https://www.nasa.gov/mission/sts-114/"}],"sourceRefs":[{"section":"6.5","start_line":1422,"end_line":1437,"startLine":1422,"endLine":1437}],"outputId":"section-6-5","sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","argumentSteps":["Fix the complete object contract, K/F, window, and normal/migration/failure/recovery task, avoiding conflation of identity and function.","Locate the wear carrier, maintenance input, and effect path; predefine outcomes such as preservation duration or failure probability.","Identify channels using appropriate maintenance, reduced-maintenance, mismatch, and stopping comparisons, addressing independent shocks, selection, and measurement limitations.","Register current, carrier-cumulative, and additional historical-increment branches separately; only the last additionally requires G3.","Check actual interface compatibility, part quality and arrival, personnel skills, and shutdown/switching authority, not just inventory.","Include externally taken-up labor and recovery dependencies within the boundary; give explicit definitions for same-type quantities and list heterogeneous costs separately.","Evaluate redundancy against common failure conditions and switching deadlines; then separately deliberate on whether to maintain, replace/stop, and assign responsibility and authorization."],"teachingExamples":[{"title":"Mathematical construction: maintenance changes preservation time; windows must not be swapped","text":"A fictional device starts with wear w₀=0, gains 2 per step, and receives maintenance input m that offsets wear, following w_{t+1}=max(0,w_t+2−m). Predefined function F requires w≤3 at every inspection time. No maintenance, m=0, gives 0,2,4, first failing at step two; reduced maintenance, m=1, gives 0,1,2,3,4, first failing at step four; maintenance m=2 keeps wear at 0 and preserves F throughout the chosen four-step window. If the task window is only the first step, all three satisfy F. Differences over a longer window cannot establish that first-step function necessarily requires sustained maintenance.","assumptions":"Wear and compensation use the same units, rules are fixed, and there are no additional shocks. Only F is compared; this single variable is not claimed to validate the complete object contract or identity criterion K.","boundary":"Entirely a mathematical model; real wear, maintenance timing, and failure thresholds require independent measurement. No maintenance amount is prescribed on this basis."},{"title":"Mathematical construction: the same two backup paths, but different independent and common-cause failure","text":"Assume function is achieved when at least one of two paths is available. In model A, each path fails independently with probability 0.1, so dual-failure probability is 0.01. In model B, a common event with probability 0.05 causes both paths to fail; absent that event, each path fails conditionally independently with probability 1/19. Each path's marginal failure probability is still 0.05+0.95/19=0.1, but dual-failure probability is 0.05+0.95×(1/19)²=1/19≈0.052632. The number of paths and individual marginal probabilities are identical, but system-failure probabilities differ. Counting backups cannot replace examination of shared conditions.","assumptions":"Both probability models are entirely stipulated, with instantaneous switching and sufficient capacity; model B is independent only conditional on no common-cause event.","boundary":"These are not reliability statistics for actual equipment; reality also requires switching time, authority, skills, and capacity."},{"title":"Teaching construction: enough backup capacity can still miss the functional window","text":"A fictional service allows at most 2 minutes of interruption. Its backup has sufficient capacity but requires on-site personnel to switch it over, taking at least 5 minutes. A backup's existence does not satisfy F of ‘interruption no longer than 2 minutes.’ Restoring service after 5 minutes is still another real result; the backup is not therefore entirely useless, nor can late recovery be written as meeting the original window.","assumptions":"Deadlines, capacity, and switching rules are teaching assumptions, with no real shutdown or personnel experiment.","boundary":"This is not a real safety threshold or switching recommendation; task requirements must be fixed beforehand."},{"title":"Mathematical construction: lower central workload may coincide with more external replacement work","text":"Suppose maintenance labor for the same registered activity in the same week initially totals 8 person-hours centrally and 0 externally. After a change it totals 3 centrally and 7 externally. Central labor falls by 5 person-hours, but total labor under this accounting definition rises from 8 to 10 person-hours. External replacement work can explain maintained output; central work orders alone cannot establish reduced total maintenance.","assumptions":"Constructed same-type labor time, covering both sides without double counting. Person-hours serve only as time accounting, without assuming equal fatigue, opportunity losses, or rights across people.","boundary":"Time, health, risk, and responsibility are not combined into a universal cost; no real family or institution is described."}],"counterexamples":[{"identity":"constructed_boundary","text":"Two backup units share the same power source and sole approver, yet are declared two fully independent recovery paths.","effect":"Common exposure and switching authority may block both simultaneously; test against failure conditions.","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"An old process retains its identity while its task function remains impaired, so continued maintenance of the old process is called repair.","effect":"Preserving K differs from meeting F; mismatched maintenance may require stopping or transformation.","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"Someone continually fills gaps to keep a service normal, so they are presumed permanently obliged to continue.","effect":"Separate empirical uptake from normative obligation; check voluntariness, responsibility, and the right to stop.","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"Having purchased parts conforming to an interface standard, declaring that the on-site fault can immediately be solved.","effect":"Implementation versions, semantics, environment, quality, arrival, skills, and shutdown authority may still be inadequate.","sourceIds":["theory"]}],"questionAnswers":[{"question":"Why does the wear model with m=1 first fail at step four?","answer":"Wear proceeds through 1,2,3,4. F permits ≤3, so the threshold is first exceeded at step four.","basis":"The source text of this section and the public derivation above"},{"question":"Why can model B's dual failure not be calculated as 0.1×0.1?","answer":"The two paths are conditionally independent only in the absence of the common event; overall, they are coupled by the common cause. First condition the probability calculation on that event.","basis":"The source text of this section and the public derivation above"},{"question":"If maintenance is necessary to preserve function, does that suffice to designate a particular employee to continue bearing it?","answer":"No. Maintenance mechanisms, responsibility, obligation, voluntariness, and authority are different judgments.","basis":"The source text of this section and the public derivation above"},{"question":"Why might recovery targets remain unmet despite an existing backup with enough capacity?","answer":"There may be common failure, switching delays, gaps in on-site skills or authority, and recovery dependencies may be unavailable within the same window.","basis":"The source text of this section and the public derivation above"},{"question":"If current wear fully reflects the past and additional history provides no increment, does this exclude cumulative maintenance effects?","answer":"No. The carrier-cumulative route holds on separate longitudinal/causal evidence; only the additional historical branch requires G3.","basis":"The source text of this section and the public derivation above"}],"figures":[{"path":"/reading-assets/S-6-5/figures/section-6-5.png","alt":"Predefine target and window: K identity / F function, separating normal operation, failure, and recovery; wear or capability carrier: how prior inputs form it, with a sufficient current state possibly having no G3 increment; specified maintenance channel: replenishment / replacement / correction / clearance, comparing preservation time and failure; actual usability: versions, semantics, quality, personnel arrival, and shutdown authority; redundancy and recovery dependencies: common causes, capacity, switching time, communications / roads / fuel, and so forth; burdens and stopping choices: gaps may be filled outside the center, and need does not automatically become obligation. The six cards are a maintenance checklist, not claims that every item is proven; K is only the identity criterion within the complete object contract.","caption":"The six cards are a maintenance checklist, not claims that every item is proven; K is only the identity criterion within the complete object contract."}],"diagramBrief":"The current deliverable is a static diagram; interaction has not yet been implemented. Any selection, switching, or clicking described below is only a design proposal for later. The top row locates targets, carriers, and channels; the bottom row lists actual compatibility and recovery accessibility, common-cause failures, and uptake boundaries. Backup count cannot replace conditions during failure.","applicability":{"realCase":"applicable","diagram":"applicable","reason":"The real mission supplies specific replacement actions and operating states. Reliability, wear, switching, and external time accounting are explicit mathematical/teaching constructions, not presented as NASA data."},"openQuestions":[],"taskId":"S-6-5","sources":[{"id":"theory","title":"Historical research manuscript: Xikari: On Conditions, Structure, and Transformation, source text supplied by the user","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Historical Chinese research draft, full text lines 1352–1367; see sourceRefs for each section's exact range","claim_support":["6.5: terminology, contracts, argumentative responsibilities, and source boundaries; no empirical facts are certified on this basis"],"limits":["The author's theoretical text is the object being explained, not a substitute for external empirical material. Skill version 5.3.1 is not the theory's version.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"nasa-cmg","title":"NASA STS-114: CMG replacement and operating state","url":"https://www.nasa.gov/mission/sts-114/","source_type":"primary","version_or_date":"Mission 2005-07-26—08-09; webpage updated 2025-05-01","locator":"Mission Highlights, EVA No.2 (2005-08-01), and the CMG explanation following EVA No.1","claim_support":["6.5: failed CMG-1 was removed, and a new CMG was moved from the payload bay and installed; four were recorded as working at that time."],"limits":["One mission record does not establish long-term reliability, independent redundancy, or complete G2 counterfactuals."],"access_status":"partially_read"},{"id":"theory-d0d1","title":"Historical research draft: Xikari 3.1–3.2, object contracts and states","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Chinese source lines 425–461","claim_support":["6.5: K is the identity criterion; function F is separate from an object's continuing identity; disintegration/repair do not automatically have a normative direction."],"limits":["Definitions, factual support, and normative judgments each bear their own responsibilities.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-carried","title":"Historical research manuscript: Xikari 4.5: current carriers and historical increments","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Chinese source lines 620–640","claim_support":["6.5: current wear/capability may take up history; only an additional conditional-increment claim separately requires G3."],"limits":["Historical narrative does not replace causal identification of the carrier.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-v2","title":"Xikari: On Conditions, Structure, and Transformation, v2, November 2026","url":"/downloads/Xikari-条件结构与转化论.md","source_type":"theory_source","version_or_date":"v2 / 2026-11-16","locator":"6.5 CM-MAINTENANCE Maintenance and preservation–dissolution; Chinese source lines 1376–1391; SHA-256 6ef2e508474d4ac1ad07d7e4e068955342c405b5f680afcfc40d68cca3d0149c","claim_support":["The current source section and this text’s conceptual explanation of v2; not a substitute for external empirical materials."],"limits":["Older research attachments retain their original manuscript identity; the previous scope of external reading has not expanded because of this edition change."],"access_status":"read"}],"lecturePath":"/reading-assets/S-6-5/lecture.md","sourcesPath":"/reading-assets/S-6-5/sources.json","sourceSlicePath":"/reading-assets/S-6-5/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-6-5/diagrams.md","editionNote":"This page’s source text and section locations correspond to v2; historical research attachments and prior external-reading records retain their own versions and scopes.","translationOf":{"language":"zh","lesson_sha256":"0eed63674e120d90c5a2e5620936495bb16abe67d2e6cb6c459c81b9493a4708","source_sha256":"6ef2e508474d4ac1ad07d7e4e068955342c405b5f680afcfc40d68cca3d0149c"}},"6.6":{"title":"6.6 CM-LOAD Load, capacity, and recovery","lead":"‘We cannot keep up’ and ‘recovery is complete’ both need explicit definitions. Where, during which period, for what demand, and with how much available capacity? Has the day's output recovered, identity and function, or depleted reserves? A single overall percentage cannot answer these questions.","explanation":["Chinese source location: lines 1392–1407; source anchor section-6-6; short quotation, translated from Chinese: ‘A recovery judgment should state what has recovered, for whom, under which supporting conditions, and as of when.’ See the corresponding section on this page for the current source; the downloadable original research excerpt preserves the historical draft.","CM-LOAD first uses D0 to specify objects and locations, then G2 to identify measured channels and relevant dimensions; E4, CAUSAL, and EVIDENCE are methodological gates. Demand and capacity must be of the same type, or have explicit units and conversion mappings, measured at the same location and within the same window. Tasks per hour cannot directly be subtracted from total inventory, nor headcounts from budgets. Processing time, task types, accounting boundaries, and mappings must be provided before comparison becomes possible.","The mechanism chain is comparable demand entering a specified channel, occupying available capacity, and producing an immediate shortfall or cross-boundary spillover, followed by load reduction, replenishment, or expansion changing the shortfall. The instant branch registers only demand-capacity and immediate shortfall within the same window; one shortfall does not automatically imply accumulated damage. carried-cumulative additionally traces historical exposure forming current damage/capacity carriers, retention or recovery across windows, subsequent outcomes, and proportionate causal comparisons; only the cumulative branch for additional history separately adds G3.","Load need not accumulate monotonically. Capacity may expand with demand and absorb the increment; a brief shortfall may end without persistent differences. Delayed recovery or later collapse requires explaining how damage, reserves, backlog, or another carrier connects one window to the next. “Was once overloaded” cannot be a sufficient cause of every later problem.","Averages cannot replace location and distribution. Total demand below total capacity does not ensure that every location avoids overload. Spare capacity that cannot reach the shortfall location within the window cannot directly offset it. Distinguish peak from sustained capacity, alternative-channel capacity, and replenishment rate; a brief peak cannot silently promise long-term supply. Register where cross-boundary spillover lands rather than deleting it from central indicators.","Recovery has at least three targets: whether output returns, whether original K or predefined F recovers, and whether internal margins are replenished. Normal output quantity may coexist with differences in quality, continuity, or accessibility. A restored F may coexist with unrestored staff rest, spare parts, maintenance backlog, or funding continuity. Conversely, confirming an accurately bounded function need not wait for every other life outcome to improve.","A recovery claim must specify what recovers, for whom, under which support, and through what date. Quantity, quality, continuity, and accessibility of physical or service outputs require separate evidence. Internal rest/spares/backlog/funding, external caregiving/commuting/borrowing/alternative-service burdens, and later interruptions and near misses cannot be inferred from central output alone. List unlike burdens separately; the need for recovery does not itself generate duties of sacrifice or operational authorization.","The denominator is part of the claim. Predisaster population, current population, eligible people, and actual users answer different questions, and the numerator must belong to the corresponding set. “100% service connection among those meeting safety conditions” can be true without meaning “100% recovery of all aspects of life for all predisaster residents.” Explain reasons, timing, and excluded positions when changing denominators; do not overwrite the old definition with the new.","Temporary premises, continued external aid, or assistive equipment can support genuine functional repair. Dependence on support is not failure; check how long support can last, its expiry, whether replacement uptake is actually operating, and peak loads, seasonal exposure, or maintenance cycles not yet experienced. Support does not mean recovery can never count, nor may supported success be generalized into independent success after withdrawal.","“False recovery” should identify only a claim exceeding evidence for objects, populations, functions, or persistence conditions, without thereby presuming deception. Later renewed instability requires comparing continuing old damage, unreplenished reserves, interrupted support, new shocks, and changed definitions. A new failure may reveal boundaries without erasing earlier accurately bounded achievements; necessary support must not be withdrawn to test recovery."],"distinctions":[{"leftTitle":"Immediate shortfall","leftText":"Demand exceeds available capacity at the same location and in the same window.","rightTitle":"Cumulative damage","rightText":"Requires a carrier bringing past exposure forward; it does not follow directly from a shortfall."},{"leftTitle":"Output recovery","leftText":"A particular output, such as quantity, returns to a predefined level.","rightTitle":"Margin recovery","rightText":"Restoring reserves, rest, backlog, and continuity capacity is another task."},{"leftTitle":"Functional recovery under support","leftText":"Temporary aid can form part of genuine function.","rightTitle":"Independent maintenance after support withdrawal","rightText":"Requires proportionate later material; the former cannot substitute."},{"leftTitle":"Bounded percentage","leftText":"Explicit population, numerator and denominator, function, and time.","rightTitle":"Comprehensive recovery","rightText":"Covers more objects and outcomes; one percentage does not automatically establish it."}],"boundaries":["Quantities of different types, times, or locations cannot be directly subtracted; dispatchability is also a bridging condition.","Brief overload may leave no long-term damage; long-term capacity shortage may also have other independent causes.","A bounded function holding does not mean every outcome has recovered, nor must every outcome recover before that function is acknowledged.","If support will expire without an operating successor, persistence remains unresolved; do not invent future supply.","Renewed instability does not automatically overturn earlier bounded success, establish deception by prior personnel, or require withdrawing support."],"questions":["Why can 3 tasks remain unfinished when capacities at two sites total 10 and demand totals 8?","In the damage example, why does output 3 meeting demand in round 1 not establish margin recovery?","If function meets its target with assistive equipment, must the equipment first be removed for recovery to count as real?","Does a 100% connection rate among eligible people imply 100% among predisaster accounts?","Which explanations should be compared for renewed instability?"],"diagramPath":"/reading-assets/S-6-6/figures/section-6-6.png","caseLinks":[{"title":"Puerto Rico electricity restoration: denominators and temporary support jointly bound recovery","href":"https://www.gao.gov/assets/gao-19-296.pdf"}],"caseNotes":[{"title":"Puerto Rico electricity restoration: denominators and temporary support jointly bound recovery","text":"GAO's 2019 report relays PREPA's estimate that, by August 2018, all customers who could safely receive electricity had service restored. The report explicitly says this did not mean all predisaster customers, because some buildings were unsafe to reconnect. GAO also records that, as of December 11, 2018, USACE still supported 7 generators powering microgrids on Vieques and Culebra. This section focuses on recovery denominators and conditions of continued support: electricity service can genuinely recover without establishing full restoration of all old customers, original grid configurations, and long-term continuity.","sourceLabel":"GAO-19-296，2019-04-18","sourceUrl":"https://www.gao.gov/assets/gao-19-296.pdf","sourceLocator":"Printed pp.6–7: Status of electricity restoration and the temporary-generator passage after Figure 1; PDF pp.10–11","boundary":"The report itself openly limits its definition; it is not evidence of deception. Connection counts do not establish recovery of personal lives, health, or all reserves, and no judgment is made about the current grid.","href":"https://www.gao.gov/assets/gao-19-296.pdf"}],"sourceRefs":[{"section":"6.6","start_line":1438,"end_line":1453,"startLine":1438,"endLine":1453}],"outputId":"section-6-6","sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","argumentSteps":["First declare object, location, population, time window, and demand/capacity types and units, supplying necessary conversion mappings.","Measure actually available capacity, demand, replenishment, and spillover by location, distinguishing peak from sustained capability.","State immediate, carrier-cumulative, and additional-historical-increment claims separately; the latter two require cross-window material, and the last separately requires G3.","Provide proportionate identification grounds for load reduction/replenishment/expansion effects, addressing common shocks and alternative channels.","Recovery claims separately register output, K/F, and internal reserves, listing quantity/quality/continuity/accessibility and internal/external burdens.","Fix numerator and denominator; disclose support conditions, expiry, whether successor uptake is operating, and stress windows not yet experienced.","For renewed instability, distinguish old damage, reserves, support, new shocks, and measurement changes; preserve bounded successes and separately review authority to act."],"teachingExamples":[{"title":"Mathematical construction: overall surplus conceals local shortfall","text":"At two fictional service points in the same hour, demands are 8 and 0 items and available capacities 5 and 5, for comparable tasks. Total demand 8 is below total capacity 10, but if transfer between sites is unavailable that hour, local shortfalls are max(0,8−5)=3 and 0, leaving 3 unfinished. An additional instantaneous, lossless, authorized dispatch channel could move those 3 tasks to the second site and clear this window's shortfall. That is an extra condition, not something totals automatically provide.","assumptions":"Capacity units are items/this hour and demand has a fixed task type; permission for intersite transfer is explicitly separated into two constructions.","boundary":"Not actual organizational data; mathematical dispatchability does not imply real permission or lossless channels."},{"title":"Mathematical construction: output returns before reserves","text":"A fictional system has rated capacity 5, with current damage z reducing available capacity to c=5−z; z stays between 0 and 5 throughout this example. Initially z₀=0. Round 0 demand is 7, giving shortfall g₀=max(0,7−5)=2. This round has no recovery, and the shortfall is written into damage, so z₁=2. Thereafter demand is 3 each round, shortfall max(0,3−c), and recovery is 1 unit through z_{t+1}=max(0,z_t+g_t−1). Round 1: c₁=3, output 3, z₂=1; round 2: c₂=4, output 3, z₃=0; round 3: c₃=5. Output already meets demand in round 1, but available capacity and margin have not returned to 5 and 2.","assumptions":"Stipulated damage-formation and recovery rules; output=min(demand,capacity), with no other shocks, inputs, or capacity adjustments.","boundary":"Real overload need not produce this damage; the model establishes only that “output meets target” and “reserves restored” can occur at different times."},{"title":"Mathematical construction: immediate shortfall need not leave damage","text":"Consider another fictional system with rated capacity 5, capacity fixed at 5 every round, and no retained damage. Demand is 7 in the first round and 3 in the second, giving outputs 5 and 3, with 2 unmet tasks in the first. If unfinished tasks terminate under an explicit rule instead of accumulating, the second round retains no state difference from that shortfall. The prior example's damage equation cannot be imposed merely because a shortfall of 2 occurred.","assumptions":"Explicitly no backlog or persistent damage; unmet tasks still entail loss within that round and are not called impact-free.","boundary":"Does not apply to actual objects known to have backlog, persistent harm, or other carriers."},{"title":"Mathematical construction: three true ratios answer different questions","text":"A fictional community had 100 predisaster accounts, now has 90, and 80 meet this round's safe-connection conditions and have all reconnected; there are 70 actual users. Assume the sets and times have been checked with no double counting. Eligible connection rate is 80/80=100%; the reconnected share of predisaster accounts is 80/100=80%; actual usage among current accounts is 70/90≈77.8%. Each numerator and denominator has its own meaning; 100% cannot be rewritten as restored use by every predisaster account.","assumptions":"Pure teaching numbers; connected accounts, actual use, and safety eligibility are different fields. All 80 reconnected accounts are assumed to belong to both predisaster and current sets.","boundary":"Does not correspond to actual Puerto Rico population counts or evaluate power quality, continuity, or health outcomes."}],"counterexamples":[{"identity":"constructed_boundary","text":"Average demand is below average capacity, so every location has no load problem.","effect":"This does not eliminate local overload or inability to dispatch resources.","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"Temporary generation or continuing external aid remains, so local function never genuinely recovered.","effect":"Support can form genuine functional recovery; specify its conditions, continuity, and scope.","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"A new shock causes another interruption, so all earlier records of supply recovery within a bounded period were false.","effect":"Different windows and shocks require separate checks; do not erase accurate facts backward or directly presume deception.","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"Central output recovers, so staff rest, spare parts, maintenance backlog, and external caregiving burdens have all recovered.","effect":"Obtain separate evidence for output, internal/external reserves, and distribution.","sourceIds":["theory"]}],"questionAnswers":[{"question":"Why can 3 tasks remain unfinished when capacities at two sites total 10 and demand totals 8?","answer":"Demand is concentrated at the first site with capacity 5, and dispatch is unavailable in this window; its local shortfall is not automatically offset by spare capacity at the second site.","basis":"The source text of this section and the public derivation above"},{"question":"In the damage example, why does output 3 meeting demand in round 1 not establish margin recovery?","answer":"Capacity was only 3 against demand 3, leaving margin 0; the margin of 2 for the same demand at rated capacity 5 had not returned.","basis":"The source text of this section and the public derivation above"},{"question":"If function meets its target with assistive equipment, must the equipment first be removed for recovery to count as real?","answer":"No. Recovery may already hold under the original support conditions. Independent maintenance after withdrawal is a separate claim; necessary support must not be removed merely for validation.","basis":"The source text of this section and the public derivation above"},{"question":"Does a 100% connection rate among eligible people imply 100% among predisaster accounts?","answer":"No: the denominators differ. In the construction the former is 80/80, the latter 80/100.","basis":"The source text of this section and the public derivation above"},{"question":"Which explanations should be compared for renewed instability?","answer":"Continuing old damage, unreplenished reserves, support interruption, new shocks, and changed measurement definitions, checking the timing and carriers for each.","basis":"The source text of this section and the public derivation above"}],"figures":[{"path":"/reading-assets/S-6-6/figures/section-6-6.png","alt":"Load definitions: same type/unit/location/window, separating peak and sustained capacity; immediate shortfall: demand enters a specified channel without automatically leaving accumulated damage; cross-window carriers: damage/reserves/backlog, with G3 added only for an additional-history claim; what recovers and for whom: output/K or F/internal margin, without switching numerators or denominators; support and continuity: temporary support can be genuinely effective, with expiry and operating successor uptake checked; distribution and renewed instability: internal rest, external burdens, and separate comparison of old damage/new shocks. Six cards distinguish same-window shortfall, carriers across windows, and recovery conditions; support dependence does not cancel bounded function, nor does bounded function become comprehensive recovery.","caption":"Six cards distinguish same-window shortfall, carriers across windows, and recovery conditions; support dependence does not cancel bounded function, nor does bounded function become comprehensive recovery."}],"diagramBrief":"The current deliverable is a static figure; interaction has not been implemented. References below to selecting, switching, or clicking are ideas for later design only. Six static cards separate immediate from cumulative effects and check function/population/support/time for recovery. The arrow from shortfall to a cross-window carrier explicitly requires separate evidence, not inevitable damage.","applicability":{"realCase":"applicable","diagram":"applicable","reason":"The official investigation directly distinguishes recovery denominators, support conditions, and continuity; local load, damage trajectories, and account ratios are separately labeled mathematical constructions, not disaster-area data."},"openQuestions":[],"taskId":"S-6-6","sources":[{"id":"theory","title":"Historical research manuscript: Xikari: On Conditions, Structure, and Transformation, source text supplied by the user","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Historical research manuscript, Chinese full-text lines 1368–1383; see sourceRefs for each section's exact range","claim_support":["6.6: terminology, contracts, responsibilities of argument, and source boundaries; these do not certify empirical facts."],"limits":["The author's theoretical text is the object being explained, not a substitute for external empirical material. Skill version 5.3.1 is not the theory's version.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"gao-restoration","title":"GAO-19-296: Puerto Rico restoration definitions and temporary power supply","url":"https://www.gao.gov/assets/gao-19-296.pdf","source_type":"primary","version_or_date":"2019-04-18","locator":"Printed pp.6–7, Status of electricity restoration and passage after Figure 1","claim_support":["6.6: the August 2018 restoration definition for customers safely reconnectable differs from all predisaster customers; on 2018-12-11, USACE supported 7 generators serving the Vieques/Culebra microgrids."],"limits":["PREPA estimates relayed by GAO with explicit limitations; this example does not use source-figure curves or infer comprehensive resident recovery or deceptive intent."],"access_status":"partially_read"},{"id":"theory-history","title":"Historical research manuscript: Xikari 4.5, carriers across windows and historical increment","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Chinese source lines 620–640","claim_support":["6.6: separate current damage/capacity carriers from historical increment beyond the representation; the latter separately requires G3."],"limits":["Constructed equations do not establish real damage mechanisms.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-types","title":"Historical research manuscript: Xikari 4.4 and 4.11.2, channel dimensions and comparable quantities","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Chinese source lines 610–619; lines 730–743","claim_support":["6.6: G2 covers only the specified channel and measured dimensions; cross-type comparison needs units, accounting, and conversion mappings."],"limits":["Formal addition/subtraction cannot imply unified costs or authorization.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-v2","title":"Xikari: On Conditions, Structure, and Transformation, v2, November 2026","url":"/downloads/Xikari-条件结构与转化论.md","source_type":"theory_source","version_or_date":"v2 / 2026-11-16","locator":"6.6 CM-LOAD Load, capacity, and recovery; Chinese source lines 1392–1407; SHA-256 6ef2e508474d4ac1ad07d7e4e068955342c405b5f680afcfc40d68cca3d0149c","claim_support":["The current source section and this text’s conceptual explanation of v2; not a substitute for external empirical materials."],"limits":["Older research attachments retain their original manuscript identity; the previous scope of external reading has not expanded because of this edition change."],"access_status":"read"}],"lecturePath":"/reading-assets/S-6-6/lecture.md","sourcesPath":"/reading-assets/S-6-6/sources.json","sourceSlicePath":"/reading-assets/S-6-6/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-6-6/diagrams.md","editionNote":"This page’s source text and section locations correspond to v2; historical research attachments and prior external-reading records retain their own versions and scopes.","translationOf":{"language":"zh","lesson_sha256":"70936b898a1f7ee21274cfa6f5b97e28ea251ac5ad04845300b95d191b594251","source_sha256":"6ef2e508474d4ac1ad07d7e4e068955342c405b5f680afcfc40d68cca3d0149c"}},"6.7":{"title":"6.7 CM-PHASE Phases and threshold conversion","lead":"A system may operate differently in different ranges, but a kinked curve alone does not show that a particular cause triggered it, still less an inevitable upgrade. First confirm that it remains the same object, then distinguish the evidence required for patterns, triggers, persistence, and history.","explanation":["Source location: Chinese source lines 1408–1421; source anchor section-6-7; brief quotation translated from Chinese: “The same curve shape cannot supply evidence for any route by proxy.” See the corresponding section on this page for the current source; the downloadable original research extract preserves the historical draft.","The basic dependencies are D0 and D1. Fix the same candidate-object contract and K, preregister state variables, candidate parameters or triggering conditions, and thresholds, and check robustness to noise and binning before testing at least two reproducibly distinguishable operating ranges. “Same K” means more than unchanged wording: the object must continue to satisfy that identity criterion across the compared ranges. If old K has failed, phase terminology cannot conceal object change.","The pattern branch registers only a range–threshold pattern. Its shared methodological gates are E4 and EVIDENCE, requiring treatment of continuous trends, noise, measurement classification, and other competing explanations, but not causal identification as a prerequisite for every pattern classification. Reproducibly observing different ranges does not establish what caused the transition.","Only the causal-trigger branch requires a specified triggering channel, channel intervention or natural variation with identification conditions, and a separate G2-instance locating the triggering effect, adding CAUSAL responsibility. Temporal sequence, changes near a threshold, or predictive accuracy alone cannot eliminate common inputs, reverse effects, or selection; causal claims carry additional material responsibilities beyond pattern registration.","The carried-persistence branch explains how a current carrier maintains a phase, persistence across windows, or delayed recovery under the same K, requiring carrier, timing, longitudinal comparison, and proportionate causal evidence. In this book hysteretic specifically means hysteresis involving historical increment: history still supplies conditional increment relative to an explicit current representation, separately requiring G3. A hysteresis loop in a domain may have its own physical or empirical explanation, but its looped shape alone cannot retrospectively award eligibility for this branch.","If the current carrier already records states determining what follows, the current state may fully take up path effects and additional historical increment may disappear. Basic reversible phases need no historical path at all. A predictive historical comparison does not automatically become historical causation because it is called “hysteresis”; causal triggering, carrier-persistence mechanisms, and historical causal explanations each add proportionate CAUSAL responsibility.","Three contrary situations require different records: if a continuous trend within one state distribution already suffices, discard unnecessary phase partitioning; if thresholds shift with arbitrary binning, prioritize measurement-classification effects; if K fails before transition, examine object conversion, dissolution, or reclassification. A further formal object-conversion claim still follows its corresponding mapping and G4 contract; changing the wording of K cannot automatically certify it.","Robustness does not require every threshold to be identical; it requires specifying in advance the noise ranges, binning choices, and observation windows under which results remain reviewable. Where classification near boundaries is unreliable, retain transition/unresolved regions rather than deleting inconvenient points afterward. Repeated appearance of a region also does not automatically make it an irreversible stage of maturity.","Phases in this section are not a mandatory S0—S6 sequence. A new phase need not be more efficient, more normatively justified, or more authorized; reversal is not automatically regression. Comparing merits, bearing costs, and implementing interventions still require predetermined tasks, norms, and authority, not a direction on a graph."],"distinctions":[{"leftTitle":"Phase pattern","leftText":"A repeatably distinguishable region–threshold relationship within the same object.","rightTitle":"Triggering causation","rightText":"A change in a specified channel causes a transition between regions; additional identification is required."},{"leftTitle":"Carrier persistence","leftText":"The current internal state takes up the past and maintains the phase.","rightTitle":"Additional historical hysteresis","rightText":"An increment exists beyond the explicit current representation, additionally requiring G3."},{"leftTitle":"A loop in a physical curve","leftText":"May suggest path or state memory, but the model and measurements must be checked.","rightTitle":"Historical-increment qualification","rightText":"Cannot be determined solely by shape and is not automatically causal."},{"leftTitle":"Different regions of the same object","leftText":"The object continues to satisfy the original K.","rightTitle":"Object conversion/dissolution","rightText":"The original K fails or the contract changes; judge separately."}],"boundaries":["The basic pattern has no hard requirement for G3 or every causal gate; an appropriate descriptive pattern may be retained without identifying a trigger.","Repeated regions cannot be artificially manufactured through arbitrary binning; known continuous relationships must be included as competing explanations.","When the current state is already sufficient, zero additional history does not cancel carrier persistence or reversible phases.","K cannot be rewritten after results to obtain a phase conclusion; identity must be checked against the original task and materials.","Physical phases in nature and operating regions in social systems have no automatic equivalence or stage mapping."],"questions":["If a pattern recurs but the triggering channel has not been identified, must the entire pattern description be deleted?","Why can h=0.5 distinguish noisy states in the first construction?","In the hysteresis model, can the next step be uniquely calculated given p=1.5 but unknown s? What if (p,s) is given?","Does every phase study require CAUSAL as a basic gate?","Why does the appearance of a new phase not directly mean improvement?"],"diagramPath":"/reading-assets/S-6-7/figures/section-6-7.png","caseLinks":[{"title":"NIST's triple-point cell: first distinguish physical phases from object boundaries","href":"https://www.nist.gov/video/triple-point-cell"}],"caseNotes":[{"title":"NIST's triple-point cell: first distinguish physical phases from object boundaries","text":"NIST's triple-point cell description, published on December 21, 2016, describes a sealed glass container holding water of a specified isotopic composition and a state of equilibrium among solid, liquid, and vapor phases inside the cell. For this section, ‘this sealed container and its contents’ can explicitly be selected as the candidate object before studying its internal phases. This object delineation is the analyst's declaration; the appearance of different internal states of matter cannot automatically be written as replacement of the container object.","sourceLabel":"NIST Triple-Point Cell，2016-12-21","sourceUrl":"https://www.nist.gov/video/triple-point-cell","sourceLocator":"The webpage's single body paragraph (Triple-Point Cell description) and Uploaded On date; this lesson uses the textual description and does not claim to review video measurements","boundary":"The source supports a phase-state description of an actual metrological apparatus; it supplies neither complete preregistered threshold/noise tests under this framework nor evidence that any organization has the same phases or a maturity sequence.","href":"https://www.nist.gov/video/triple-point-cell"}],"sourceRefs":[{"section":"6.7","start_line":1454,"end_line":1467,"startLine":1454,"endLine":1467}],"outputId":"section-6-7","sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","argumentSteps":["Fix the complete object contract and K, checking that comparison regions continue to satisfy identity; do not change K afterward to preserve the conclusion.","Register states, parameters, thresholds, noise tolerances, and binning tests beforehand, first judging the reproducible pattern.","A pattern reports only relationships between regions; a claim about triggering causes additionally requires G2 for specified channels and proportionate causal identification.","To claim persistence or delayed recovery, locate the current carrier and its cross-window effects; to additionally claim a historical increment, check G3.","Separate predictive historical gains from historical causation; curve shape does not replace branch materials.","Reclassify continuous trends, binning effects, and K failure into their appropriate results; formal conversion claims require a separate check of their contracts.","Preserve the respective scopes of patterns, mechanisms, task merit, and action authorization; do not draw an automatic staircase of maturity."],"teachingExamples":[{"title":"Mathematical construction: two reversible regions without historical memory","text":"A fictional control unit continues to satisfy a predetermined K, with input p∈[0,4] and state rule x=0 when p<2 and x=1 when p≥2; measurement is y=x+ε, with |ε|≤0.1. The two output intervals are [-0.1,0.1] and [0.9,1.1], distinguishable by any classification boundary h∈(0.1,0.9). Inputs 1.5→2.5→1.5 give states 0→1→0, depending only on current p without retaining history. The rule is stipulated within the model, showing that a pattern and reversibility can exist without additional history.","assumptions":"A deterministic state rule with bounded measurement error; p is measured exactly, threshold 2 and the noise bound are specified before calculation, and K does not change with x being 0 or 1.","boundary":"The two regions are mathematical stipulations rather than actual repeated measurements; real-world pattern or causal-trigger qualification still requires its own materials."},{"title":"Mathematical construction: binning can create a false impression of a jump","text":"Let the underlying model instead be y=p, with p varying continuously over [0,4] and no state jump. The reporter publishes only labels L=0 when y<2 and L=1 when y≥2, making the plotted label jump abruptly. Changing the bin boundary to 3 moves the label's jump to 3, while the original y=p remains unchanged. A classification threshold moving with reporting rules is insufficient to establish a phase conversion of the object.","assumptions":"The continuous function is completely known, and the label rule is the analyst's artificial binning; there are no actual observational data.","boundary":"This does not deny that discrete classifications can be useful; it shows only that classification use and identification of object phases are different."},{"title":"Mathematical construction: a current carrier can sufficiently take up a hysteresis loop","text":"Let state s∈{0,1}, with rule s′=1 when p≥2, s′=0 when p≤1, and s′=s when 1<p<2; output is s′. Path A enters 1.5 from p=0.5, with current s=0; path B enters 1.5 from p=2.5, with current s=1. The same p=1.5 can yield different outputs, but the complete current representation (p,s) already determines the next step; recording only p omits the known carrier s. This model with memory explains why a hysteresis shape does not automatically require additional history beyond the complete current representation.","assumptions":"The rule and initial endpoints are artificially given, with no other noise or hidden states; s must be disclosed, not deleted to manufacture historical gains.","boundary":"Mathematical carrier sufficiency does not deny real-world historical increments; actual comparisons still collect evidence according to the selected representation and G3 conditions."},{"title":"Teaching construction: identity criteria determine the question's boundaries","text":"For a fictional lamp, if the predetermined K requires that the same numbered housing and wiring components still constitute the apparatus, on/off can be states within the same object. If a different task takes ‘this particular burning flame’ as its candidate object, K may cease to hold when the flame goes out; a newly lit flame cannot universally be called the original object changing phase. The specific K must be stated with the task in advance, rather than chosen freely after observing results.","assumptions":"The objects and criteria are teaching constructions; no K is claimed to be the uniquely natural boundary.","boundary":"Field definitions only declare candidates; they do not establish empirical object validity or formal conversion."}],"counterexamples":[{"identity":"constructed_boundary","text":"First divide a continuous score into two groups using an arbitrary threshold, then use the two groups to prove natural phases.","effect":"The classification rule itself cannot serve as independent evidence of an object's regional pattern.","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"Observe a hysteresis loop and declare historical-increment causation established without measuring the current carrier.","effect":"Curve shape cannot replace carrier control, G3, and proportionate causal grounds.","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"The original object's identity has already failed, yet it is still described as the same object entering a more mature phase.","effect":"This exceeds both object boundaries and the bounds of value upgrading; check conversion/dissolution and evaluate objectives separately.","sourceIds":["theory"]}],"questionAnswers":[{"question":"If a pattern recurs but the triggering channel has not been identified, must the entire pattern description be deleted?","answer":"No. Register the regional relationships in a bounded way under pattern; record triggering causation separately as unresolved.","basis":"The source text of this section and the public derivation above"},{"question":"Why can h=0.5 distinguish noisy states in the first construction?","answer":"The low interval's maximum is 0.1 and the high interval's minimum is 0.9; 0.5 lies in the gap. Any h in (0.1,0.9) works.","basis":"The source text of this section and the public derivation above"},{"question":"In the hysteresis model, can the next step be uniquely calculated given p=1.5 but unknown s? What if (p,s) is given?","answer":"Knowing only p is insufficient, since s may be 0 or 1; knowing complete (p,s) gives s′=s, so the current carrier determines the future.","basis":"The source text of this section and the public derivation above"},{"question":"Does every phase study require CAUSAL as a basic gate?","answer":"No. The pattern branch's common gates are E4/EVIDENCE; claims of causal triggering, carrier-persistence mechanisms, or historical causal explanations add proportionate causal responsibilities.","basis":"The source text of this section and the public derivation above"},{"question":"Why does the appearance of a new phase not directly mean improvement?","answer":"A phase only classifies operating regions; task benefits, costs, norms, and authority require separate judgments.","basis":"The source text of this section and the public derivation above"}],"figures":[{"path":"/reading-assets/S-6-7/figures/section-6-7.png","alt":"Common starting point: the same candidate contract with K satisfied, variables, thresholds, noise, and binning. pattern: repeatable regions–thresholds without first claiming triggering causation. causal-trigger: a specified channel and identification comparisons, adding G2 and causal responsibilities. carried-persistence: a current carrier maintains effects across windows, with temporal and causal materials. hysteretic increment: check G3 relative to the current representation; prediction does not automatically become causation. Reverse checks: continuous trends/binning effects, with object checks reopened if K fails. The four branches cannot masquerade as one another; the same curve shape does not establish every mechanism, and a new phase is not automatically better or more authorized.","caption":"The four branches cannot masquerade as one another; the same curve shape does not establish every mechanism, and a new phase is not automatically better or more authorized."}],"diagramBrief":"The current deliverable is a static diagram; interaction has not been implemented, and the following references to selecting, switching, or clicking describe future design ideas only. Six cards contain the common starting point, four branches, and reverse checks. No arrows automatically upgrade a pattern into history or value; triggering arrows explicitly require additional claims and materials.","applicability":{"realCase":"applicable","diagram":"applicable","reason":"The official metrological apparatus description supplies concrete physical phases and boundary identification; proofs concerning reversibility, binning, and hysteresis use separate mathematical models with complete assumptions, without substituting physical analogy for social evidence."},"openQuestions":[],"taskId":"S-6-7","sources":[{"id":"theory","title":"Historical research manuscript: Xikari: On Conditions, Structure, and Transformation, source text supplied by the user","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Lines 1384—1397 of the complete historical Chinese research manuscript; see sourceRefs for each section's precise range","claim_support":["6.7: terms, contracts, burdens of argument, and source boundaries; not a basis for certifying empirical facts"],"limits":["The author's theoretical text is the object being explained, not a substitute for external empirical material. Skill version 5.3.1 is not the theory's version.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"nist-phase-cell","title":"NIST: Triple-Point Cell apparatus description","url":"https://www.nist.gov/video/triple-point-cell","source_type":"primary","version_or_date":"2016-12-21","locator":"The single body paragraph and Uploaded On date","claim_support":["6.7: NIST describes water in a sealed glass cell and equilibrium among its solid, liquid, and vapor phases; published 2016-12-21."],"limits":["Only the webpage's textual description was checked; no video frames or measured values are cited. The candidate object contract is this lesson's conditional analysis, not NIST's adoption of the Xikari framework."],"access_status":"read"},{"id":"theory-d0d1","title":"Historical Chinese research manuscript: Xikari §§3.1—3.2, objects and state terms","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Chinese source lines 425–461","claim_support":["6.7: K is the identity criterion; distinguish state changes within the same object from K failure. Evolution does not inherently mean maturity or value."],"limits":["Declaring a candidate does not establish empirical object validity.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-history","title":"Historical Chinese research manuscript: Xikari §4.5, current carriers and additional history","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Chinese source lines 620–640","claim_support":["6.7: separate carrier persistence from increments beyond the representation; do not delete known current states to manufacture increments."],"limits":["A predictive increment is not automatically historical causation.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-g4","title":"Historical Chinese research manuscript: Xikari §4.6, scale closure and conversion","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Chinese source, lines 642—648","claim_support":["6.7: a further formal object-conversion claim requires corresponding mappings and preselected G4 instance conditions."],"limits":["A phase name or textual change to K does not automatically certify conversion.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-v2","title":"Xikari: On Conditions, Structure, and Transformation, v2, November 2026","url":"/downloads/Xikari-条件结构与转化论.md","source_type":"theory_source","version_or_date":"v2 / 2026-11-16","locator":"6.7 CM-PHASE phases and threshold transitions; Chinese source, lines 1408—1421; SHA-256 6ef2e508474d4ac1ad07d7e4e068955342c405b5f680afcfc40d68cca3d0149c","claim_support":["The current source section and this text’s conceptual explanation of v2; not a substitute for external empirical materials."],"limits":["Older research attachments retain their original manuscript identity; the previous scope of external reading has not expanded because of this edition change."],"access_status":"read"}],"lecturePath":"/reading-assets/S-6-7/lecture.md","sourcesPath":"/reading-assets/S-6-7/sources.json","sourceSlicePath":"/reading-assets/S-6-7/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-6-7/diagrams.md","editionNote":"This page’s source text and section locations correspond to v2; historical research attachments and prior external-reading records retain their own versions and scopes.","translationOf":{"language":"zh","lesson_sha256":"a88b86a323a19857acc696238f3d8bfa9f74b0d7cb7368fc4d74a615a7faddda","source_sha256":"6ef2e508474d4ac1ad07d7e4e068955342c405b5f680afcfc40d68cca3d0149c"}},"6.8":{"title":"6.8 CM-SELECTION variation—differential retention—reproduction","lead":"Seeing a practice or type persist makes it tempting to reason backward that ‘it must be better’. This section first sets aside judgments of merit to examine what variations exist, how outcomes differ, whether the differences actually enter the next round, and whether sampling luck alone is sufficient to explain them.","explanation":["Chinese source location: lines 1422—1435; source anchor section-6-8; short quotation: ‘one instance of persistence is not differential retention’ (translated from Chinese). The current source appears in the corresponding subsection on this page; the downloadable original research excerpt preserves the historical manuscript.","D1 only provides rules for using state terms such as change and evolution; ‘evolution occurred’ cannot directly imply selection. CM-SELECTION is a separately operationalized conditional mechanism: E4, CAUSAL, and EVIDENCE handle competing explanations, causation, and material review, while conceptual stories do not generate empirical support. The basic pattern has no hard dependency on G2 or G3, but still requires complete checks of V, D, R, the next round, repeated rounds, and competition with drift explanations.","V consists of distinguishable variations and their sources defined before outcomes; one cannot identify winners first and then treat their shared features as prior variables. D is a differential outcome exceeding a predetermined threshold in comparable environments, with proportionate denominators, exposures, and opportunity conditions; increased population size is not directly equivalent to improved per-unit retention or reproductive capacity. R is the retention that carries this difference into the next round, with repeated rounds available for review, not merely a statistical difference in the current round.","The pattern branch registers a selection pattern with these connections and must compare drift, common external causes, and sampling bias. Random sampling can also produce long-term dominance of a type, and failure to observe another type in a sample may simply reflect missed sampling. If a drift model explains the observations under proportionate sufficiency conditions, do not register a selection pattern beyond it; mere nonsignificance likewise does not establish drift sufficiency, so retain judgment precision and failure records.","Beyond the pattern, the carrier branch identifies which retention or reproduction channel carries the difference, locating it through channel perturbation or natural variation satisfying identification conditions and a G2-instance. If perturbing the candidate channel leaves retention unchanged, it cannot continue to be treated as the claimed specific mechanism; also check whether the perturbation actually took effect, alternative paths, and measurement conditions. Lack of support for a specified channel does not automatically cancel a pattern supported by other materials.","Beyond the pattern, the history branch separately tests conditional increments of cross-round historical terms after controlling for the current state, with G3 support. Repeated rounds are a basic-pattern requirement; an additional historical increment is another requirement. Recurrence does not imply that history remains additionally useful given the complete current state. Conversely, a predictive historical variable alone does not establish V/D/R or selection channels.","When items are missing, stop at the appropriate level: with change but no D, record change; with only one difference but no R, next round, or replication, record a one-time outcome; if drift is sufficient, do not add a selection explanation; if a specified reproductive mechanism has not been distinguished, retain the pattern or candidate without inventing a channel. Results departing from expectations do not permit changing V, thresholds, environments, or historical controls afterward to rescue the original claim.","Being retained does not mean being more advanced, more normatively justified, or even better in every environment and task. A type replicating more under particular conditions is only a bounded process result; environmental changes, tradeoffs, frequency dependence, and coexistence can all limit narratives of ‘winning forever’.","System selection, an agent's choice, and collective governance choices are three different matters. System selection may have no unified decision-maker; agent choice requires a specific agent, options, and decision evidence; collective governance additionally requires normative premises, J-axis authorization, and O procedures. ‘The mechanism retained this institution’ cannot decide public consent on people's behalf or authorize eliminating people and allocating resources."],"distinctions":[{"leftTitle":"Change/evolution","leftText":"Register changes in state or object-contract fields.","rightTitle":"Selection pattern","rightText":"Requires V/D/R, the next round, repetition, and competition with drift explanations."},{"leftTitle":"One-time outcome difference","leftText":"Different types have different outcomes in this round.","rightTitle":"Differential retention","rightText":"The difference actually enters subsequent rounds and can be reviewed."},{"leftTitle":"Selection pattern","leftText":"A structure of differential retention under bounded conditions.","rightTitle":"Specific mechanism","rightText":"Separately identify the specified carrier/reproduction channel."},{"leftTitle":"System retention","leftText":"A process causes some types to continue or increase.","rightTitle":"Governance decision","rightText":"Requires agents, options, norms, authorization, and procedures."}],"boundaries":["Random drift may produce persistent dominance; long-term existence is no shortcut to ruling out drift.","When the current state sufficiently determines what follows, repeated selection can occur without an additional historical increment.","Differential reproduction can occur alongside coexistence and need not cause other types to disappear.","When perturbing a channel fails to produce the expected effect, limit the conclusion to that channel and comparison conditions rather than generalizing to the impossibility of all selection.","A process advantage is not moral superiority, permission to act, or anyone's obligation to sacrifice."],"questions":["What is A's share in the third round of the first construction?","If the ratio resets to 4 to 4 at each round's end, why can the intermediate 8 to 4 not count as cross-round retention?","In the pure-drift example, the probability of an all-A next generation is 1/4. What does this show, and what does it not show?","If the pattern has been observed but channel perturbation does not show the expected change, may the pattern be retained?","Does repeated differential retention automatically satisfy G3's historical increment?"],"diagramPath":"/reading-assets/S-6-8/figures/section-6-8.png","caseLinks":[{"title":"Coexistence in the long-term evolution experiment: selection need not leave only one winner","href":"https://pmc.ncbi.nlm.nih.gov/articles/PMC2430337/"}],"caseNotes":[{"title":"Coexistence in the long-term evolution experiment: selection need not leave only one winner","text":"In their original 2008 study, Blount, Borland, and Lenski report in the results section on frequency-dependent selection that, after combining Cit− and Cit+ types at different initial proportions, both coexisted over subsequent rounds; Cit− approached a minority share rather than being completely eliminated by Cit+. The authors interpreted this result as negative frequency-dependent selection maintaining diversity. This section focuses on evidence containing types, trajectories across rounds, and competitive conditions, rather than merely on who remained at the end.","sourceLabel":"Blount and colleagues, PNAS 105(23):7899–7906, issue dated 2008-06-10","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC2430337/","sourceLocator":"Results: ‘Frequency-Dependent Selection Maintains Ecological Diversity’, first two paragraphs; Methods: ‘Test for Frequency-Dependent Interaction’","boundary":"Retain the ecological conclusion under the original study's bounded conditions; do not retrospectively grant the paper formal G2/G3 status under this framework, extrapolate to every environment, or call retained types more advanced or more normatively justified.","href":"https://pmc.ncbi.nlm.nih.gov/articles/PMC2430337/"}],"sourceRefs":[{"section":"6.8","start_line":1468,"end_line":1481,"startLine":1468,"endLine":1481}],"outputId":"section-6-8","sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","argumentSteps":["Before results, define variations and sources, comparable environments, differential outcomes, thresholds, and next-round units.","Separately check D's denominators and opportunity conditions, R's retention connections, and multiple subsequent rounds.","Make proportionate comparisons with drift, common external causes, and sampling bias; do not rely solely on a one-time advantage or long-term existence.","Report the pattern level first; a specified retention/reproduction mechanism additionally requires channel identification and G2. Do not treat names as causation.","For additional cross-round history, separately control the current state and check G3; do not treat repetition itself as a historical conditional increment.","When items are missing, narrow the result to change, a one-time outcome, a pattern, or an unresolved result; explicitly preserve every failure condition.","Moving from process support to values, agent intentions, and governance authority always requires separate bridging materials; no automatic upgrading."],"teachingExamples":[{"title":"Mathematical construction: how differential replication enters the next round","text":"Take fictional marker types A/B, initially 4 each. Each round, each A marker produces 2 same-type successors and each B produces 1, under one rule with no capacity limits, mutation, or random sampling. Round one gives A=8,B=4, with A proportion 2/3; round two gives A=16,B=4, proportion 4/5. Generally, for current proportion p∈(0,1), p′=2p/(1+p), and p′−p=p(1−p)/(1+p)>0. V is the two types defined beforehand, D is their per-unit copy counts 2 and 1, R is retention in same-type successors, and repeated rounds follow the same recurrence.","assumptions":"A fully specified nonbiological marker-copying model, with no actual experiment; deterministic rules exclude random drift by assumption rather than testing it away with data.","boundary":"Proves only differential retention in the specified model, not a real mechanism, indefinitely available resources, or any value superiority of A."},{"title":"Mathematical construction: a one-round difference without retention across rounds","text":"Keep the model, but after each round an external rule discards every successor and reinstates 4 A and 4 B. The intermediate 8-to-4 difference remains visible each round, but never enters the next round’s initial state; starting proportions stay at 1/2. If the predetermined question concerns frequency evolution across rounds, intermediate outcomes cannot stand for a completed R chain.","assumptions":"The reset rule is explicit; the unit of analysis is a complete round and the start of its successor. Numbers are constructed.","boundary":"A different question about within-round copying differences can retain the corresponding conclusion; failure across rounds does not deny every local fact."},{"title":"Mathematical construction: pure drift can also fix rapidly","text":"Take a fictional population containing one A and one B. Each generation independently samples twice with replacement, equally likely from either parent marker, copying their types into a next generation still of size 2. The types have no capability difference. The probability that the next generation is all A is (1/2)²=1/4; once all A, absence of mutation keeps it all A. Thus persistent all-A fixation may result from pure sampling rather than a higher per-unit reproduction rate for A.","assumptions":"Sampling rules and no mutation are mathematical assumptions, with equiprobable parents; no actual sampling occurred.","boundary":"‘Drift is also possible’ does not directly reject all actual selection; reality requires probability comparisons, repeated material, and predetermined criteria."},{"title":"Mathematical construction: repeated selection needs no additional history","text":"In the first construction, current p and the fixed copying rule uniquely determine p′=2p/(1+p). Any two histories reaching the same p yield the same next proportion; history can explain how current p arose but adds nothing to this predetermined next-step prediction. Unrecorded heritable differences, environments, or carriers in reality prevent direct reuse of this sufficiency result.","assumptions":"The current representation contains every state and rule needed in this example, hiding no further differences.","boundary":"The model’s zero additional increment is not evidence for a real G3 null conclusion."}],"counterexamples":[{"identity":"constructed_boundary","text":"Seeing one type persist for a long time is taken to imply necessarily superior differential-retention capability.","effect":"Equiprobable drift can produce persistent fixation; other explanations still need comparison.","sourceIds":["theory"]},{"identity":"real_counterevidence","text":"In the relevant ecological comparison in Blount et al.’s 2008 study, Cit+ did not fix; Cit− remained a minority and coexisted with it.","effect":"This limits the universal claim that a new advantageous type necessarily eliminates all others; advantage and retention depend on specific environments and frequencies.","sourceIds":["blount2008"]},{"identity":"constructed_boundary","text":"An institution survived prolonged competition, so everyone chose and consented to it and ought to obey it.","effect":"System retention cannot establish agents’ decisions, public consent, or governance authorization.","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"One difference without subsequent tracking is declared an identified cross-round pathway mechanism.","effect":"R, the next round, repetition, and current-state controls require distinct missing material; stop at the single outcome.","sourceIds":["theory"]}],"questionAnswers":[{"question":"What is A's share in the third round of the first construction?","answer":"A=32,B=4, proportion 32/36=8/9; alternatively substitute p=4/5 into 2p/(1+p).","basis":"The source text of this section and the public derivation above"},{"question":"If the ratio resets to 4 to 4 at each round's end, why can the intermediate 8 to 4 not count as cross-round retention?","answer":"The intermediate difference is reset and never enters the next starting state; specify the round boundaries relevant to the task.","basis":"The source text of this section and the public derivation above"},{"question":"In the pure-drift example, the probability of an all-A next generation is 1/4. What does this show, and what does it not show?","answer":"It shows that lasting advantage does not logically entail capability differences; it cannot establish that all actual advantages arise from drift.","basis":"The source text of this section and the public derivation above"},{"question":"If the pattern has been observed but channel perturbation does not show the expected change, may the pattern be retained?","answer":"Retain the pattern on its independent material while marking the specific channel mechanism unsupported or unresolved, checking perturbation implementation and alternative paths.","basis":"The source text of this section and the public derivation above"},{"question":"Does repeated differential retention automatically satisfy G3's historical increment?","answer":"Not automatically. G3 asks whether history adds a conditional increment after controlling for explicitly specified current states.","basis":"The source text of this section and the public derivation above"}],"figures":[{"path":"/reading-assets/S-6-8/figures/section-6-8.png","alt":"V Distinguishable variation: definitions and sources before results, not winners’ traits selected afterward; D Differential outcomes: comparable environments, denominators, thresholds, with opportunities and sampling checked; R Entry into the next round: retention and repeated rounds, not one outcome; competing explanations for the pattern: drift/shared external causes/missed sampling, with persistence not excluding drift; specific-carrier branch: specified channels and identification comparisons, adding G2 beyond the pattern; cross-round history branch: control explicit current states, adding G3 for further increment. Six cards separate pattern, specific carriers, and history branches; retained does not automatically mean better, and system selection is not governance choice.","caption":"Six cards separate pattern, specific carriers, and history branches; retained does not automatically mean better, and system selection is not governance choice."}],"diagramBrief":"The current deliverable is a static diagram; interaction has not been implemented, and the selections, switches, or clicks described below are ideas for a later design only. The upper row connects V/D/R; the lower row gives competing pattern explanations and two additional branches. No arrow connects selection to moral superiority or governance authority.","applicability":{"realCase":"applicable","diagram":"applicable","reason":"The primary study specifically reports coexistence across rounds and the authors’ frequency-dependence interpretation, limiting one-round winner stories; mathematical marker examples are separate from the original study’s data and supply no experimental procedure."},"openQuestions":[],"taskId":"S-6-8","sources":[{"id":"theory","title":"Historical research manuscript: Xikari: On Conditions, Structure, and Transformation, source text supplied by the user","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Historical research draft, full text, lines 1398–1411; see sourceRefs for each section’s exact range","claim_support":["6.8: terminology, contracts, burdens of argument, and boundaries of the original text; no empirical facts are certified on this basis"],"limits":["The author's theoretical text is the object being explained, not a substitute for external empirical material. Skill version 5.3.1 is not the theory's version.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"blount2008","title":"Blount et al.: historical contingency and innovation in long-term experimental populations","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC2430337/","source_type":"primary","version_or_date":"Published online 2008-06-04; issue dated 2008-06-10; DOI 10.1073/pnas.0803151105","locator":"Results: first two paragraphs of Frequency-Dependent Selection Maintains Ecological Diversity; Methods: Test for Frequency-Dependent Interaction","claim_support":["6.8: Cit−/Cit+ coexistence over multiple rounds following different initial proportions, interpreted by the authors as diversity maintained by negative frequency-dependent selection."],"limits":["Only that study’s ecological-results section is cited; no claim is made to have replicated the experiment or read supplementary experimental data, and no formal framework instance is retrospectively awarded."],"access_status":"partially_read"},{"id":"theory-d1","title":"Historical research draft: Xikari 3.2: D1 State Terms","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Chinese source lines 450–461","claim_support":["6.8: the definition of evolution implies neither selection, direction, nor value."],"limits":["An independent mechanism needs its own operationalization and evidence.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-c8","title":"Historical research draft: Xikari 4.13.1: C8 Selection","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Chinese source lines 837–853","claim_support":["6.8: separate differences, retention, the next round, repetition, competing explanations, and conditional branches."],"limits":["A bounded pattern creates neither agents’ choices nor normative authorization.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-v2","title":"Xikari: On Conditions, Structure, and Transformation, v2, November 2026","url":"/downloads/Xikari-条件结构与转化论.md","source_type":"theory_source","version_or_date":"v2 / 2026-11-16","locator":"6.8 CM-SELECTION Variation—Differential Retention—Reproduction; Chinese source lines 1422–1435; SHA-256 6ef2e508474d4ac1ad07d7e4e068955342c405b5f680afcfc40d68cca3d0149c","claim_support":["The current source section and this text’s conceptual explanation of v2; not a substitute for external empirical materials."],"limits":["Older research attachments retain their original manuscript identity; the previous scope of external reading has not expanded because of this edition change."],"access_status":"read"}],"lecturePath":"/reading-assets/S-6-8/lecture.md","sourcesPath":"/reading-assets/S-6-8/sources.json","sourceSlicePath":"/reading-assets/S-6-8/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-6-8/diagrams.md","editionNote":"This page’s source text and section locations correspond to v2; historical research attachments and prior external-reading records retain their own versions and scopes.","translationOf":{"language":"zh","lesson_sha256":"29a550a65cc9d05b40af1f872b565706531ed68cd8844d4cb9c4bbd37cea6071","source_sha256":"6ef2e508474d4ac1ad07d7e4e068955342c405b5f680afcfc40d68cca3d0149c"}},"6.9":{"title":"6.9 Conditions for Coevolution","lead":"Two people, institutions, or species changing together need not be shaping each other. Coevolution requires checking how each direction acts separately; even if both ultimately return to the same point, their speed, risks, and intervention points along the way may differ completely.","explanation":["Source location: Chinese source lines 1436–1443; source anchor section-6-9; short quotation translated from Chinese: ‘The same final state is not the same mechanism.’ See the corresponding section on this page for the current original text; the downloadable original research excerpt retains the historical draft.","A coevolution candidate requires two candidate objects to change one another’s environments, feasible paths, specified channels, or retention conditions, with both directions traceable in their respective windows. ‘Co-’ refers to an interaction structure, not two rising curves, and guarantees no mutual benefit.","Register two complete D0 object contracts, each with its own identity criterion K and SP/T. One overall system name cannot replace the two objects, and K cannot be called the whole contract. They may have different time resolutions, update cycles, and visible ranges; align event timing and explain when A’s change to B might return to affect A, avoiding a synchronous mechanism invented from surface correlations between daily and annual data.","The two G2 directions carry separate identification responsibilities. Support for A→B does not establish B→A; one intervention changing both simultaneously may not distinguish directions either. Record transmitted content, effect locations, temporal order, comparison conditions, and speed differences, and proportionately test common third-party environmental changes, one-way dependence, and synchronized measurement protocols.","For cross-round effects, follow 4.5 to examine both sides’ current carriers, retention/updating, actual invocation, and longitudinal comparisons separately. Add corresponding G3 only for a further claim of historical conditional increment beyond the current representation. Increment in one direction does not automatically establish increment in the other; persistent carriers on both sides also need not yield extra historical gains on both sides.","Coevolution need not be symmetric. Transmission strength, speed, costs, dependence, and ability to exit can differ greatly; the relation may be antagonistic rather than mutually beneficial. Even established two-way influence does not directly imply aligned values, public consent, an obligation to continue the relationship, or either party’s authority to act upon the other.","The same final state is not the same mechanism. A fixed point remains unchanged after updating; its existence alone does not guarantee trajectory convergence. Only separate proof of convergence permits discussing a trajectory’s long-term limit; update rules also determine return speed, transient peaks, and intervention responses. A simpler representation may suffice if the task asks only for a long-term limit under certain conditions. Once it asks about meeting a threshold within two steps, peaks, whom to change selectively, or performance after support removal, relevant distinctions must be retained and tested again.","Recovery, coevolution, and cross-circle continuity can all share terminal values while differing in process. Two curves eventually approaching each other cannot identify two-way channels; nor can an accurate original long-term summary handle new action tasks automatically. Preserve the scope of ‘which representation suffices for which target, horizon, and operation’ so model simplification is not mistaken for the world’s only mechanism."],"distinctions":[{"leftTitle":"Joint change","leftText":"Both sides change during the same period.","rightTitle":"Two-way effects","rightText":"Both causal paths have separate material; correlation cannot substitute."},{"leftTitle":"Interaction","leftText":"Each side can affect the other.","rightTitle":"Symmetry or mutual benefit","rightText":"Magnitudes, speeds, gains, and burdens still require separate measurements."},{"leftTitle":"The same fixed point","leftText":"Two rules share a state unchanged by updating; a common long-term limit requires separate proof of convergence.","rightTitle":"The same dynamics and intervention mechanism","rightText":"Identical updates, transients, and operation responses: a stronger, different claim."},{"leftTitle":"Carriers across rounds","leftText":"Current states preserve the past and affect what follows.","rightTitle":"Additional historical increment","rightText":"History still adds gain given the current representation; check each direction separately."}],"boundaries":["If only one direction is identifiable, retain its one-way effect without filling in the other.","A shared environment or common measurement timing can produce synchrony; report cadence is not object coupling.","A terminal-value summary sufficient for one task is not automatically usable for deadlines, peaks, or targeted intervention.","A relationship’s ability to persist creates no obligation to maintain it; two-way effects can also amplify harm.","This guide cites only conclusions reported in the original authors’ public abstract for the real case; methods and individual data were not independently reviewed here, and no formal G-instance certification is made."],"questions":["Why do two models converging to 0 differ on meeting a second-step threshold?","If only current y increases by one unit, how much does next-step x change in each model?","If A affects B and B also changes, is that enough for two-way coevolution?","If both directions have persistent carriers, must both have G3?","Can coevolution be asymmetric and antagonistic?"],"diagramPath":"/reading-assets/S-6-9/figures/section-6-9.png","caseLinks":[{"title":"Bacteria and bacteriophages: coevolution can be antagonistic","href":"https://pmc.ncbi.nlm.nih.gov/articles/PMC1690980/"}],"caseNotes":[{"title":"Bacteria and bacteriophages: coevolution can be antagonistic","text":"The public abstract of Buckling and Rainey’s 2002 original paper reports sustained reciprocal adaptation in bacterial-host resistance and phage infectivity: hosts developed resistance to a broader range of parasite types, while parasites gained infectivity against a broader range of host types. Replicate communities also diverged in their paths of change. This case directly limits the interpretation that coevolution equals mutually beneficial synchrony.","sourceLabel":"Buckling & Rainey 2002，DOI 10.1098/rspb.2001.1945","sourceUrl":"https://pmc.ncbi.nlm.nih.gov/articles/PMC1690980/","sourceLocator":"Original paper’s public Abstract, paragraphs two and three; Proc. R. Soc. B 269:931–936, 2002-05-07","boundary":"Only the bounded conclusions reported in the authors’ public abstract are retained; this guide did not independently review full methods and data, recertify two-way G2/G3 from the abstract, or generalize to obligations in human relationships.","href":"https://pmc.ncbi.nlm.nih.gov/articles/PMC1690980/"}],"sourceRefs":[{"section":"6.9","start_line":1482,"end_line":1489,"startLine":1482,"endLine":1489}],"outputId":"section-6-9","sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","argumentSteps":["Declare complete object contracts for A and B separately, with K, scale profiles, and time windows, ensuring each remains independently traceable.","Specify A→B and B→A channels and changed fields separately, with timing, speed, and comparisons.","Check the two G2 directions separately, distinguishing shared environments, one-way dependence, and synchronized measurement protocols.","For cross-round claims, first examine each carrier route; declare and test additional historical increments separately rather than passing them together.","Treat long-term limits, arrival deadlines, transients, and targeted interventions as different tasks, checking representational preservation for each.","Allow asymmetric or antagonistic coevolution to be reported; values, obligations to continue, and authority require separate consideration."],"teachingExamples":[{"title":"Mathematical construction: the same endpoint, different speed and intervention response","text":"Let two state deviations be z=(x,y). Model A updates x′=0.25x+0.25y, y′=0.25x+0.25y; model B updates x′=0.75x+0.125y, y′=0.125x+0.75y. Maximum row sums are 0.5 and 0.875 respectively, so for every finite initial state ||z_t||∞≤r^t||z₀||∞→0, and both have unique fixed point (0,0). Starting at (1,0), however, A gives (0.25,0.25) after one step and (0.125,0.125) after two; B gives (0.75,0.125) and then (0.578125,0.1875). If the task requires second-step maximum absolute deviation ≤0.2, A passes and B fails. If current y alone increases by δ while x stays fixed, next-step x changes by 0.25δ and 0.125δ respectively, so targeted intervention responses differ too.","assumptions":"Fully specified fixed linear two-state models without external shocks or execution limits; r is the corresponding row-sum bound, and variables are deviations rather than headcounts.","boundary":"This construction proves that terminal values cannot recover a mechanism; it does not independently establish coevolution of real objects or supply an actual intervention proposal."},{"title":"Mathematical construction: shared input can synchronize two curves perfectly","text":"Let external condition U_t vary arbitrarily, with x_t=U_t and y_t=2U_t and no links between them. They synchronize perfectly and may be highly correlated; yet replacing y alone while keeping U and the other rule fixed does not change later x. Testing a two-way relation requires asking separately whether change in each direction is caused by input from the other, rather than omitting the shared U.","assumptions":"An explicit shared-input structure with no hidden cross-terms; all sequences are constructed.","boundary":"A shared environment and two-way relations can coexist in reality; naming a shared input does not automatically negate coevolution."},{"title":"Teaching construction: one contemporaneous table cannot replace two clocks","text":"Fictional A adjusts its supply interface weekly, while B revises its usage rules quarterly. A’s change this week need not appear in B’s report that same week; B’s change next quarter may also arise from other conditions. Record separately when supply actually changes B’s feasible paths and when B’s rules return to affect A, then compare within their respective windows. Copying quarterly totals into weekly rows cannot create more independent evidence merely through more table rows.","assumptions":"Purely a teaching timeline with no institution observed; update cycles are declared beforehand.","boundary":"Neither deny delayed effects from short-run nonsynchrony nor attribute every later change to the earliest A."}],"counterexamples":[{"identity":"constructed_boundary","text":"The two sides are correlated long term, so they necessarily shape each other and both benefit.","effect":"Shared input can explain correlation, while mutual benefit is an additional value/outcome judgment.","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"Models A and B both limit to 0, so two-step recovery and targeted intervention are equivalent too.","effect":"Second-step values and response coefficients differ; the terminal-value summary has exceeded its use.","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"Only A-to-B causal evidence exists, yet two arrows are drawn and both G2 directions declared passed.","effect":"The missing direction must remain unresolved; a diagram adds no evidence.","sourceIds":["theory"]}],"questionAnswers":[{"question":"Why do two models converging to 0 differ on meeting a second-step threshold?","answer":"Maximum row sums bound convergence rates; the particular two-step differences follow from matrix recurrence. From the given initial state, A’s second-step maximum is 0.125 and B’s 0.578125, giving different results against threshold 0.2.","basis":"The source text of this section and the public derivation above"},{"question":"If only current y increases by one unit, how much does next-step x change in each model?","answer":"A increases by 0.25 and B by 0.125; sharing a fixed point does not guarantee the same intervention response.","basis":"The source text of this section and the public derivation above"},{"question":"If A affects B and B also changes, is that enough for two-way coevolution?","answer":"No. Independently trace B→A’s actual effect, timing, and comparison; B’s change cannot replace a return-direction mechanism.","basis":"The source text of this section and the public derivation above"},{"question":"If both directions have persistent carriers, must both have G3?","answer":"No. Carrier routes require separate evidence; only each additional historical-increment claim additionally requires G3.","basis":"The source text of this section and the public derivation above"},{"question":"Can coevolution be asymmetric and antagonistic?","answer":"Yes. Two-way influence is neither symmetry nor mutual benefit and creates no obligation to continue.","basis":"The source text of this section and the public derivation above"}],"figures":[{"path":"/reading-assets/S-6-9/figures/section-6-9.png","alt":"Object A: complete contract and criterion K_A, its own SP_A/T_A; object B: complete contract and criterion K_B, its own SP_B/T_B; shared third-party environment: compare common shocks/one-way dependence and synchronized measurement protocols; A to B and B to A: separately check timing, speed, and carriers, assuming neither symmetry nor mutual benefit; same terminal state may still differ: updates, deadlines, transients, interventions, retaining task-relevant differences. Both arrows are candidate directions requiring separate evidence, not automatically established by simultaneous change; the five cards do not certify actual coevolution.","caption":"Both arrows are candidate directions requiring separate evidence, not automatically established by simultaneous change; the five cards do not certify actual coevolution."}],"diagramBrief":"The current deliverable is a static diagram; interaction has not been implemented, and the selections, switches, or clicks described below are ideas for a later design only. Five cards separately record two objects, shared environment, two-way evidentiary responsibilities, and task-relevant dynamical differences. The separately labeled arrows are candidate channels each needing evidence; one direction’s evidence cannot be copied as support for the other.","applicability":{"realCase":"applicable","diagram":"applicable","reason":"The original abstract provides an explicit example of antagonistic two-way adaptation. Reading scope and support ceilings are disclosed; the mathematical model explains only nonequivalence despite a shared terminal state and does not masquerade as biological data."},"openQuestions":["Independent evaluation of the biological experiment's channel identification, temporal resolution, and competing explanations would require obtaining and checking the full methods and data. This lesson does not fill those gaps from the abstract."],"taskId":"S-6-9","sources":[{"id":"theory","title":"Historical research manuscript: Xikari: On Conditions, Structure, and Transformation, source text supplied by the user","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Historical research draft, full-text lines 1412–1419; see sourceRefs for precise section ranges","claim_support":["6.9: terminology, contracts, burden of argument, and boundaries of the original text; not certification of empirical facts"],"limits":["The author's theoretical text is the object being explained, not a substitute for external empirical material. Skill version 5.3.1 is not the theory's version.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"buckling2002","title":"Buckling and Rainey: antagonistic coevolution of bacteria and bacteriophages","url":"https://pmc.ncbi.nlm.nih.gov/articles/PMC1690980/","source_type":"primary","version_or_date":"2002-05-07；DOI 10.1098/rspb.2001.1945","locator":"Second and third paragraphs of the Abstract (abstract section on the public full-text page)","claim_support":["6.9: the original authors report reciprocal adaptation of host resistance and parasite infectivity, with divergent paths across replicate communities."],"limits":["Only the public abstract was checked. The full-text PDF was not obtained; detailed experimental methods, data, and channel identification were not reviewed here."],"access_status":"partially_read"},{"id":"theory-d0","title":"Historical research draft: Xikari §3.1, complete object contract","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Chinese source, lines 425—448","claim_support":["6.9: register D0 for each side separately. K is only an identity criterion; SP/T are not spatiotemporal labels that may be arbitrarily merged."],"limits":["Two candidate contracts do not establish either side's validity or two-way channels.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-history","title":"Historical research draft: Xikari §4.5, carriers across rounds and additional history","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Chinese source lines 620–640","claim_support":["6.9: obtain carrier evidence separately for each side; only additional historical increments add their respective G3 requirements."],"limits":["Support in one direction cannot replace support in the other.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-v2","title":"Xikari: On Conditions, Structure, and Transformation, v2, November 2026","url":"/downloads/Xikari-条件结构与转化论.md","source_type":"theory_source","version_or_date":"v2 / 2026-11-16","locator":"6.9 Conditions for coevolution; Chinese source lines 1436–1443; SHA-256 6ef2e508474d4ac1ad07d7e4e068955342c405b5f680afcfc40d68cca3d0149c","claim_support":["The current source section and this text’s conceptual explanation of v2; not a substitute for external empirical materials."],"limits":["Older research attachments retain their original manuscript identity; the previous scope of external reading has not expanded because of this edition change."],"access_status":"read"}],"lecturePath":"/reading-assets/S-6-9/lecture.md","sourcesPath":"/reading-assets/S-6-9/sources.json","sourceSlicePath":"/reading-assets/S-6-9/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-6-9/diagrams.md","editionNote":"This page’s source text and section locations correspond to v2; historical research attachments and prior external-reading records retain their own versions and scopes.","translationOf":{"language":"zh","lesson_sha256":"c465a2d92fd3d5687952d78e6f6fe89f45bed83b1ee427f9c4d58046cf2db184","source_sha256":"6ef2e508474d4ac1ad07d7e4e068955342c405b5f680afcfc40d68cca3d0149c"}},"6.10":{"title":"6.10 Dissolution, object conversion, and repair boundaries","lead":"Repair need not restore every old component, and dissolution need not mean failure. First specify what is to be preserved or regained, then compare which new states achieve that target and who has authority to choose.","explanation":["Source location: Chinese source lines 1444–1449; original anchor section-6-10. Short quotation translated from Chinese: “It does not turn time back to the old state.” See the corresponding section on this page for the current original; downloaded original research excerpts retain the historical draft.","Dissolution is judged by failure of the original contract's K. K is an identity criterion, not the entire object contract; unchanged wording does not guarantee that the object still meets it. If original K fails while another object contract may hold, distinguish termination, conversion, and reclassification. Continued use of an old name does not establish continued existence of the original object.","The distinction between phase change and dissolution is whether original K still holds. The same object may change operating regime, but when its original identity fails, that change cannot silently be called a “new phase.” A new candidate contract also cannot certify actual object conversion merely by definition. Formal conversion claims require corresponding scale mapping, preservation/loss, G4-route material, and related conditions.","Dissolution does not automatically mean failure, nor continued existence success. Success requires prior objectives, costs, and evaluation criteria. Orderly termination may be a permitted objective, while preserving an old identity may continue harming functions or others. What remains and what has ended must be answered separately from whether preservation is worthwhile.","Repair is judged against K* or F* targets disclosed before results. It may use old traces or replace components, boundaries, relations, interfaces, carriers, or scale positions. A new state meeting the target need not exactly reproduce the past. Conversely, restored appearance, an old name, or recovery of one output does not alone ensure that predetermined K*/F* are met. If only F* was selected, report only that functional achievement without additionally proving original object identity.","“An available repair window” is a more specific empirical claim. Beyond the target, compare how intervention timing affects reachability and cost, specifying permitted measures, resources, delays, and alternative paths. A plan becoming infeasible after some time does not imply every possible plan is permanently hopeless. New resources or technologies change the feasible set and must be disclosed, not used to rewrite the original window conclusion.","Historically formed damage, connections, or capabilities may act as current constraints; trace their formation and present effects through the carrier route. Whether history adds usefulness conditional on complete current constraints is a separate question, and only that question adds G3. Historically caused current damage does not require every repair comparison to prove an additional historical increment.","Empirical reachability confers no implementation authority. Target justification and who chooses, bears responsibility, or may execute require N, J, and O1–O4 review: freeze description and evidence; disclose normative premises and conflicts; compare options including inaction and check authorization; then bound execution, monitoring, stopping, appeal, rollback, and remedies. Technical comparisons for deliberation may be completed first without masquerading as authorized actual disposition."],"distinctions":[{"leftTitle":"Original K fails","leftText":"The original identity criterion no longer permits claiming preservation of the original object.","rightTitle":"All functions disappear","rightText":"A stronger claim that need not hold; other objects or functions may remain."},{"leftTitle":"Repair of K* or F*","leftText":"Achieving a previously declared identity or functional target.","rightTitle":"Returning to the historical original","rightText":"Unnecessary; paths, components, or support may change."},{"leftTitle":"Repair is reachable","leftText":"The target can be achieved with specified measures, resources, and timing.","rightTitle":"Implementation is authorized","rightText":"Additionally requires normative premises, authority, and bounded procedures."},{"leftTitle":"One plan's window closes","leftText":"The target is unreachable within the registered feasible set.","rightTitle":"Every future plan is impossible","rightText":"Does not follow by extrapolation from the former."}],"boundaries":["Dissolution, conversion, and failure are not synonyms; continued existence likewise guarantees neither function nor value.","K*/F* cannot be changed after results to match what was achieved and rescue the original repair task.","Changing a carrier can truly repair a function. Original K preservation is checked separately; both need not always hold.","Repair windows are bound to object, target, measures, and resources, not unconditional permanent verdicts of fate.","Technical feasibility creates neither named responsibility nor authority; analytical comparison is not actual deployment."],"questions":["Why does adding edge a—c both connect all three points and permit delivery of 4?","If original K requires old edge b—c itself to exist, does the new plan preserve K?","In the window model at t=3, what is the minimum remaining damage?","Can repair using a temporary different carrier be confirmed?","Why does existing empirical support not directly determine who may implement?"],"diagramPath":"/reading-assets/S-6-10/figures/section-6-10.png","caseLinks":[{"title":"Temporary island microgrids: functional repair need not restore the original connection exactly","href":"https://www.gao.gov/assets/gao-19-296.pdf"}],"caseNotes":[{"title":"Temporary island microgrids: functional repair need not restore the original connection exactly","text":"GAO's 2019 report records that Vieques and Culebra previously received power through submarine transmission lines connected to Puerto Rico's main grid. As of December 11, 2018, 7 USACE-supported generators served the islands' microgrids. This section adds the observation that supply carriers/connections may differ from the originals: “the original connection was not restored exactly” and “no functional repair occurred” are not the same claim.","sourceLabel":"GAO-19-296，2019-04-18","sourceUrl":"https://www.gao.gov/assets/gao-19-296.pdf","sourceLocator":"Printed p.7, temporary-generator and submarine-transmission-line paragraph following Figure 1","boundary":"Describes only the replacement supply configuration in the report. It does not independently establish continuous supply to every user, preservation of original-grid K, or long-term net benefits, nor authorize actual modification.","href":"https://www.gao.gov/assets/gao-19-296.pdf"}],"sourceRefs":[{"section":"6.10","start_line":1490,"end_line":1495,"startLine":1490,"endLine":1495}],"outputId":"section-6-10","sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","argumentSteps":["Check the original object contract and K, specifying which states still satisfy it and when satisfaction ends.","If K persists, examine phase. If K fails, separately examine termination, conversion, or reclassification; formal conversion additionally requires contract and evidence checks.","Disclose K*/F* before results, listing changeable components/boundaries/relations and task conditions that must not be lost.","Test candidate repaired states against each target rather than requiring every old state to return or judging appearance alone.","A repair-window claim requires comparison of intervention times, permitted measures, reachability, and costs, with the feasible set explicit.","Separate current historical carriers from additional historical increments. Action selection additionally passes N, J, and O1–O4."],"teachingExamples":[{"title":"Mathematical construction: replacing one edge can repair a function","text":"A fictional undirected service network has nodes a,b,c and original edges a—b and b—c, each capacity 4. Task F* is delivery of 4 units of the same quantity type per period from a to c; K* is connectivity among these three specified nodes. Only a supplies and c receives, b conserves flow, and there is no additional flow. The original sole path a—b—c carries 4. If b—c breaks, c is isolated, K* fails, and delivery is 0. A repair adds capacity-4 edge a—c while retaining a—b, reconnecting all three and directly carrying 4. The new edge set differs from the original while satisfying the K*/F* predetermined here.","assumptions":"Graph structure, capacities, and targets are artificial. Inputs/outputs share units and windows, capacities are realizable, and there are no additional losses. K* is only this construction's declared criterion; complete actual objects require further material.","boundary":"Mathematical reachability certifies neither actual networks, deployment authority, nor costs. If original K required preserving every old edge, the conclusion would differ; this must be specified beforehand."},{"title":"Mathematical construction: timing changes reachability, not historical inevitability","text":"Let fictional damage z_t=t for integer times starting at 0. The sole permitted measure removes m damage units once, with 0≤m≤2. After treatment z*=max(0,z_t−m), costing m budget units under budget cap 2. Target F* is z*=0. At t=1, m=1 achieves it at cost 1; at t=2, m=2 achieves it at cost 2. At t=3, every permitted m leaves at least 1, so the target is unreachable. The window under these measures/budget is therefore t≤2, not impossibility of every future repair.","assumptions":"Damage formation, measure range, and cost rule are explicit. There is no additional recovery while waiting or new measure, and t≥0.","boundary":"Only a target-reachability calculation, not a diagnosis of irreversible human conditions. New resources/measures require a newly declared question."},{"title":"Teaching construction: renaming cannot erase affected positions","text":"Using the disconnected network, registering only a and b as a new two-point service object permits study of that new candidate, but does not restore the original service target for c. Disclose how the new contract handles c, original obligations, and exit losses. Establishing a smaller object does not automatically replace the original object's task.","assumptions":"Pure teaching regrouping; no boundaries of actual organizations or populations are adjusted.","boundary":"A new object's empirical validity, conversion eligibility, and normative adoption require separate evidence, not renaming."}],"counterexamples":[{"identity":"constructed_boundary","text":"The three-node network achieves its target through a new direct edge, so it is declared unrepaired because the old path was not restored.","effect":"If the repair target permits relational change, the new state can achieve K*/F*. Historical exactness is not necessary.","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"Failure of original K is taken to mean every social objective failed and the old object must be restored.","effect":"Dissolution does not itself supply objectives or obligations; independent evaluation is required.","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"The same repair plan no longer works when applied late, so repair is declared impossible under any technology, resources, or future conditions.","effect":"This extrapolates beyond the registered feasible set. Window conclusions must retain their conditions.","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"A plan is feasible in a technical model, so the team claims authority immediately to modify actual records or infrastructure.","effect":"Feasibility cannot replace N/J/O procedures.","sourceIds":["theory"]}],"questionAnswers":[{"question":"Why does adding edge a—c both connect all three points and permit delivery of 4?","answer":"Retaining a—b and adding a—c connects b to c through a. Edge a—c has capacity 4 and this is the only same-type flow demand, so F* is reachable.","basis":"The source text of this section and the public derivation above"},{"question":"If original K requires old edge b—c itself to exist, does the new plan preserve K?","answer":"No. A functional F* may be satisfied while this original K fails; report separately under predetermined criteria.","basis":"The source text of this section and the public derivation above"},{"question":"In the window model at t=3, what is the minimum remaining damage?","answer":"At most 2 can be removed from initial damage 3, leaving at least 1, so the original target is unreachable.","basis":"The source text of this section and the public derivation above"},{"question":"Can repair using a temporary different carrier be confirmed?","answer":"Bounded confirmation is possible if predetermined K* or F* is met under disclosed support and window conditions. Persistence, original identity, and independent maintenance require separate checks.","basis":"The source text of this section and the public derivation above"},{"question":"Why does existing empirical support not directly determine who may implement?","answer":"Targets, responsibility, authorization, and procedures are not automatic products of empirical effects; N/J/O1–O4 require separate review.","basis":"The source text of this section and the public derivation above"}],"figures":[{"path":"/reading-assets/S-6-10/figures/section-6-10.png","alt":"Original network: a—b—c, both edges capacity 4, connected and able to send 4 from a to c. Broken network: b—c fails, c is isolated, K* fails, delivery 0. New network: add a—c, retain a—b; direct capacity 4, both K* and F* satisfied. Mathematical construction: K* is three-point connectivity; F* is delivery of 4 from a to c each period. The new network differs from the original edge set; actual adoption authority requires separate review.","caption":"Mathematical construction: K* is three-point connectivity; F* is delivery of 4 from a to c each period. The new network differs from the original edge set; actual adoption authority requires separate review."}],"diagramBrief":"The current deliverable is a static diagram; interaction has not been implemented. References below to selecting, switching, or clicking are future design ideas only. Three side-by-side networks show the original, broken edge, and repair by a new direct connection. A red cross marks the broken edge; blue lines mark usable capacity-4 edges. All are teaching assumptions, without actual network data.","applicability":{"realCase":"applicable","diagram":"applicable","reason":"An actual replacement supply configuration illustrates the distinction between new carriers and old configurations. Repair targets, network flows, and windows are separately explicit constructions; no original object contract is presumed for the disaster area."},"openQuestions":[],"taskId":"S-6-10","sources":[{"id":"theory","title":"Historical research manuscript: Xikari: On Conditions, Structure, and Transformation, source text supplied by the user","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Historical research draft, full-text lines 1420–1425; see sourceRefs for precise section ranges","claim_support":["6.10: terminology, contracts, burden of argument, and boundaries of the original text; not certification of empirical facts"],"limits":["The author's theoretical text is the object being explained, not a substitute for external empirical material. Skill version 5.3.1 is not the theory's version.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"gao-alternative","title":"GAO-19-296: replacement electricity-supply configurations on two islands","url":"https://www.gao.gov/assets/gao-19-296.pdf","source_type":"primary","version_or_date":"2019-04-18","locator":"Printed p.7, temporary-generator paragraph after Figure 1","claim_support":["6.10: on 2018-12-11, seven generators supported Vieques/Culebra microgrids; the islands had previously connected to the main grid through submarine transmission lines."],"limits":["The replacement-configuration fact does not automatically establish original K preservation, comprehensive continuous supply, or governance authority."],"access_status":"partially_read"},{"id":"theory-d1","title":"Historical research draft: Xikari §3.2, definitions of dissolution and repair","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Chinese source lines 450–461","claim_support":["6.10: original K failure and target K*/F*; state terms carry no inherent value or authorization."],"limits":["Mathematical target achievement does not supply evidence for actual objects.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-history","title":"Historical research draft: Xikari §4.5, current historical carriers","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Chinese source lines 620–640","claim_support":["6.10: separate historically formed current constraints from additional historical residuals."],"limits":["Only an additional increment separately requires G3.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-conversion","title":"Historical research draft: Xikari §4.6 and §5.7, responsibilities for formal conversion","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Chinese source lines 642–650; lines 1190–1220","claim_support":["6.10: a further formal object-conversion claim requires corresponding mappings, preservation/loss, and G4 conditions."],"limits":["K failure does not automatically establish another object or formal conversion.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-action","title":"Historical research draft: Xikari C12 and §14.6, norms, authorization, and procedures","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Chinese source lines 908–924; lines 2940–2953","claim_support":["6.10: separate reachability, comparisons for deliberation, and actual adoption. N, J, and O1–O4 bear different responsibilities."],"limits":["The explanation implements no real modification.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-v2","title":"Xikari: On Conditions, Structure, and Transformation, v2, November 2026","url":"/downloads/Xikari-条件结构与转化论.md","source_type":"theory_source","version_or_date":"v2 / 2026-11-16","locator":"6.10 Dissolution, object conversion, and repair boundaries; Chinese source lines 1444–1449; SHA-256 6ef2e508474d4ac1ad07d7e4e068955342c405b5f680afcfc40d68cca3d0149c","claim_support":["The current source section and this text’s conceptual explanation of v2; not a substitute for external empirical materials."],"limits":["Older research attachments retain their original manuscript identity; the previous scope of external reading has not expanded because of this edition change."],"access_status":"read"}],"lecturePath":"/reading-assets/S-6-10/lecture.md","sourcesPath":"/reading-assets/S-6-10/sources.json","sourceSlicePath":"/reading-assets/S-6-10/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-6-10/diagrams.md","editionNote":"This page’s source text and section locations correspond to v2; historical research attachments and prior external-reading records retain their own versions and scopes.","translationOf":{"language":"zh","lesson_sha256":"b753c77ebdf36cecbfd1765ff9e28d6e680773605a2fd1cd474ad87e69fd4f37","source_sha256":"6ef2e508474d4ac1ad07d7e4e068955342c405b5f680afcfc40d68cca3d0149c"}},"6.10.1":{"title":"6.10.1 Formation, Maintenance, Recovery, and Replication","lead":"Initial formation, continued maintenance, recovery after damage, and replication elsewhere may depend on different conditions.","explanation":["Formation asks how an arrangement arises; maintenance asks what keeps it operating; recovery asks how specified functional or identity goals are met again after damage; replication asks whether corresponding outcomes can be obtained with a different object, place, or scale. These four can have different answers, and earlier success guarantees no later stage.","Recovery here connects to repair in D1: specify the functional or identity goal, without automatically interpreting recovery as a return to the historical original. Maintenance may rely on different people, resources, and rules from formation. Replication may face different capabilities, authority, external conditions, and scale effects.","Failure of replication or expansion requires comparing at least four possibilities: the scheme itself failed, including that it did not cause the original result; implementation departed from the content specified beforehand; the target lacked enabling conditions specified beforehand; or scale changed the treatment or object. Each explanation needs independently checkable evidence, not selection after failure to protect the original conclusion.","Implementation content and enabling conditions must be stated before outcomes and independently checkable. ‘The conditions were actually wrong,’ introduced only after failure, enters only as a candidate for the next round. Records obtained after outcomes that check previously declared conditions should be evaluated as evidence, not categorically excluded merely because collection was late."],"keyTerms":[{"term":"Formation and maintenance","text":"Conditions for emergence and for continued operation require separate evidence."},{"term":"Replication conditions","text":"Implementation content and enabling conditions declared before outcomes and independently checkable."}],"sourceQuotes":[{"text":"The four are judged separately, and none can vouch for another. All four are also descriptive judgments and do not mean that the arrangement should be maintained, recovered, or replicated.","ref":"§6.10.1 · author's English reference edition","href":"/en/theory/part-06#section-6-10-1"}],"argumentSteps":["Formation asks how an arrangement arises; maintenance asks what keeps it operating; recovery asks how specified functional or identity goals are met again after damage; replication asks whether corresponding outcomes can be obtained with a different object, place, or scale. These four can have different answers, and earlier success guarantees no later stage.","Recovery here connects to repair in D1: specify the functional or identity goal, without automatically interpreting recovery as a return to the historical original. Maintenance may rely on different people, resources, and rules from formation. Replication may face different capabilities, authority, external conditions, and scale effects.","Failure of replication or expansion requires comparing at least four possibilities: the scheme itself failed, including that it did not cause the original result; implementation departed from the content specified beforehand; the target lacked enabling conditions specified beforehand; or scale changed the treatment or object. Each explanation needs independently checkable evidence, not selection after failure to protect the original conclusion."],"distinctions":[{"leftTitle":"Prior results","leftText":"Retain outcomes supported by evidence for the original object, window, and conditions.","rightTitle":"Conclusions for a new stage","rightText":"Maintenance, recovery, and replication each require renewed checks of conditions and outcomes."}],"teachingExamples":[{"title":"Constructed teaching scenario","text":"A trial succeeds in one team but fails when expanded to three. If training and authority requirements were specified beforehand, check their implementation. If ‘the founder must also be present every day’ is added only after failure, it remains a candidate for testing, not grounds to declare replication successful or immunize the original mechanism.","boundary":"Illustrates conditions and counterexamples only; it reports no real event or completed mechanism test."}],"caseNotes":[],"caseLinks":[],"boundaries":["The four explanations of failure are not established causes and are not claimed to exhaust all possibilities.","Past local success does not guarantee continued success under new conditions; new failure does not automatically erase the past."],"counterexamples":[{"identity":"Constructed conditional counterexample","text":"A trial succeeds in one team but fails when expanded to three. If training and authority requirements were specified beforehand, check their implementation. If ‘the founder must also be present every day’ is added only after failure, it remains a candidate for testing, not grounds to declare replication successful or immunize the original mechanism.","effect":"The four explanations of failure are not established causes and are not claimed to exhaust all possibilities.","sourceIds":["theory-v2"]}],"questions":["Can failed replication elsewhere directly negate the original success?"],"questionAnswers":[{"question":"Can failed replication elsewhere directly negate the original success?","answer":"No. First distinguish the original arrangement, implementation, enabling conditions, and scale changes, preserving achievements within the original scope. At the same time, newly added post hoc conditions cannot evade the current failure.","basis":"v2 §6.10.1"}],"openQuestions":[],"summary":"Initial formation, continued maintenance, recovery after damage, and replication elsewhere may depend on different conditions.","sourceRefs":[{"section":"6.10.1","start_line":1496,"end_line":1501,"startLine":1496,"endLine":1501}],"sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","sourceSliceHash":"425a94c218f762453e1b30251d14d4b3ed81021dd03be8ccde5404521edb829a","outputId":"section-6-10-1","taskId":"S-6-10","sources":[{"id":"theory-v2","title":"Xikari: On Conditions, Structure, and Transformation, v2, November 2026","url":"/downloads/Xikari-条件结构与转化论.md","source_type":"theory_source","version_or_date":"v2 / 2026-11-16","locator":"§6.10.1, Chinese source lines 1450–1455","claim_support":["This section's definitions, argumentative boundaries, and explicitly labeled constructed teaching explanations."],"limits":["No new external empirical test was added; examples do not serve as real-world evidence."],"access_status":"read"}],"applicability":{"realCase":"not_applicable","diagram":"not_applicable","reason":"This section explains the new v2 argument through conceptual distinctions, explicitly labeled teaching scenarios, and contrary conditions, without adding external empirical research."},"lecturePath":"","sourcesPath":"","sourceSlicePath":"","diagramsPath":"","supplementaryFiles":[],"figures":[],"diagramBrief":"Item-by-item comparison preserves conditions without adding a figure that would portray the process as a mandatory sequence.","editionNote":"This page’s source text and section locations correspond to v2; historical research attachments and prior external-reading records retain their own versions and scopes.","translationOf":{"language":"zh","lesson_sha256":"668a5a6fba64e8539933e4ebf50adf7093b447a2d4894ca69356efe4867f6636","source_sha256":"6ef2e508474d4ac1ad07d7e4e068955342c405b5f680afcfc40d68cca3d0149c"}},"6.11":{"title":"6.11 Overall gate for mechanism outputs","lead":"After writing a mechanism explanation, ask again: what evidence have we actually delivered, and how far may the conclusion go? This overall gate prevents “the system has feedback” from quietly becoming “the system has learned, recovered, and deserves preservation.”","explanation":["Source location: Chinese source lines 1456–1459; original anchor section-6-11. Short quotation translated from Chinese: “When items are missing, retain only candidate mechanisms or questions to check.” See the corresponding section on this page for the current original; downloaded original research excerpts retain the historical draft.","The six conditional mechanisms here are feedback, feedback-mediated learning, maintenance, load, phase, and selection. They share eight checks: object and scale declaration, inferential dependencies, enabling conditions, mechanism chain, minimum evidence, competing explanations, counterexamples, and failure boundaries. A common framework does not mean the same evidence for every mechanism or G3 for every branch.","Object and scale declarations specify who is discussed and within which SP/T/K scope. Inferential dependencies state what the conclusion logically relies on; enabling conditions state what the process needs; the mechanism chain connects actual sites of effect. Minimum evidence specifies supporting material; competing explanations check alternatives that could change judgment; counterexamples specify conditions limiting or refuting the claim; failure boundaries state when extrapolation stops or contracts change.","The eight items cannot substitute for one another. Drawing a chain does not supply evidence; listing competing explanations does not exclude them; stating a time window does not establish observational coverage; complete fields do not guarantee semantically correct variables, channels, or authorization references. The overall gate requires substantive proportionality, not certification merely because a table has no blanks.","Each mechanism retains its own conclusion ceiling. Feedback establishes an effective return without cross-round learning. Immediate load concerns a same-window gap without accumulated damage. Basic phase patterns do not include historical-increment hysteresis. Selection patterns do not include specified carrier mechanisms, still less value superiority. Maintenance and repair do not create perpetual preservation duties. Further claims may be proposed, but require the material they actually need.","Missing items leave candidate mechanisms or specific questions to check; broad narratives cannot fill blanks. What pauses is complete mechanism registration at the claimed level, not independently established observations, domain conclusions, or lower-level results. If parameters demonstrably changed but evidence of use is insufficient, for example, retain the update fact and mark carrier-mediated learning insufficiently identified.","Also distinguish “explicit counterevidence” from “material not yet available.” Proof that a necessary condition fails blocks that particular mechanism route. An undetermined necessary condition remains unresolved rather than establishing that the mechanism does not exist in the world. Null conclusions require their own comparisons, sensitivity, and tolerance; failure of positive support is no substitute.","Conceptual explanations and teaching constructions show how contracts work. Exact reproducibility within a construction does not mean an external object follows its rules. Adding one real fact does not automatically empirically validate an entire model. The overall gate helps readers locate gaps without claiming actual reader testing or automatic replacement of domain judgment."],"distinctions":[{"leftTitle":"Complete explanation","leftText":"Readable text addresses all eight responsibilities.","rightTitle":"Substantive support","rightText":"Each item has proportionate material and actual tests; existence of text does not establish this."},{"leftTitle":"Candidate mechanism","leftText":"An explanation worth further examination according to its specific gaps.","rightTitle":"A supported mechanism","rightText":"Meets the corresponding scope and branch conditions, permitting a bounded conclusion."},{"leftTitle":"A higher-level claim remains unproved","leftText":"For example, a learning-mechanism chain still lacks evidence of actual use.","rightTitle":"Lower-level facts denied","rightText":"For example, the parameter change itself may already be confirmed and does not disappear."},{"leftTitle":"Missing evidence","leftText":"A necessary condition cannot yet be confirmed.","rightTitle":"Counterevidence","rightText":"Proportionate material refutes a condition or claim; closure differs."}],"boundaries":["The overall gate is a set of substantive responsibilities, not a field counter or a ninth cause in the physical process.","The eight items unfold in logical order; new counterexamples may require revisiting premises. One linear completion does not promise permanent validity.","Failure of one branch does not automatically establish another; each requires its own prior claim and material.","Teaching examples generate no external empirical support, and passing machine validation certifies neither facts nor norms.","Missing items do not erase independently established facts, but prevent combining those facts into a complete claim that remains unsupported."],"questions":["What is the appropriate conclusion for a report with a parameter file but no use records?","Why do eight c_i values of 1 not imply eight e_i values of 1?","After observing one overload, what must be added to claim delayed recovery?","If a basic phase pattern is supported, must hysteresis also be declared supported?","How does explicit proof that a necessary condition fails differ from not having read relevant material?"],"diagramPath":"/reading-assets/S-6-11/figures/section-6-11.png","caseLinks":[],"caseNotes":[],"sourceRefs":[{"section":"6.11","start_line":1502,"end_line":1505,"startLine":1502,"endLine":1505}],"outputId":"section-6-11","sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","argumentSteps":["First specify which of the six mechanisms, which branch, and which conclusion level is at issue, avoiding interchangeable names.","Check all eight common responsibilities individually, connecting each to material for this object and window.","Explicitly add conditions where stronger claims require them; do not impose G3 or governance permissions indiscriminately on every route.","Distinguish a written explanation, proportionate material, completed testing, and the result obtained.","When items are missing, identify specific candidates/questions and stopping points, preserving independently known facts.","Record counterevidence and unknowns separately; retain distinct statuses for concepts, formal constructions, and actual empirical support."],"teachingExamples":[{"title":"Teaching construction: locating gaps in a “learning report”","text":"A fictional report accurately records feedback arrival, parameter change, and storage of the parameter file, but contains no material showing that later tasks read that version. The overall gate should neither declare “nothing happened” nor announce completed learning: update facts can be preserved, with gaps in actual use and task differences explicitly listed. If additional material shows that the program always reads the old version, this is more than missing evidence: the use claim has counterevidence.","assumptions":"A fictional arrangement of material, unrelated to an actual organization. Arrival/change/storage are checked by assumption; use is considered in two cases, unknown and known not to hold.","boundary":"This construction is not a diagnosis of actual learning and does not replace evidence collection in real domains."},{"title":"Mathematical construction: eight nonempty fields do not mean eight resolved requirements","text":"Let c_i=1 mean field i contains text, and e_i=1 mean its substantive condition has proportionate support. A model record may have (c₁,…,c₈)=(1,1,1,1,1,1,1,1) while (e₁,…,e₈)=(1,1,1,1,0,0,1,1): minimum evidence and competing explanations remain unresolved. Thus ∏c_i=1 while ∏e_i=0; formal completeness cannot replace substantive completeness. Here e_i is only a teaching logic marker; actual support cannot be created by the author entering a 1.","assumptions":"Binary markers demonstrate logical non-implication. Reality also requires multiple states such as unresolved; 0 cannot uniformly be read as empirical counterevidence.","boundary":"This product is not a recommended automatic fact-certification algorithm; it is only a counterexample."},{"title":"Teaching construction: blocking smuggled-in conclusions individually","text":"Six fictional statements: return changes a state once → permanent learning; one hour's demand exceeds capacity → cumulative damage must exist; two threshold ranges → additional history must exist; differential-retention pattern → a particular inheritance channel is proved; a device needs maintenance → someone has a permanent obligation; functional repair is feasible → an institution may implement it immediately. Every arrow lacks different bridging material; “complete system mechanism” cannot supply them all.","assumptions":"Composed entirely of constructed inferential leaps, not descriptions of actual people or events.","boundary":"This illustrates gap identification only, without prejudging all conclusions as necessarily false once material is supplied."}],"counterexamples":[{"identity":"constructed_boundary","text":"Eight headings are complete and the JSON passes, so all six mechanism classes hold in reality.","effect":"Syntactic completeness generates no object facts, causal support, or normative authorization.","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"The learning route lacks use material, so the earlier parameter-change record must also be false.","effect":"Missing higher-level evidence cannot erase lower-level known facts.","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"A claim has not yet been tested, so a null mechanism is recorded as supported.","effect":"Not run, unresolved, and null conclusions must remain distinct.","sourceIds":["theory"]}],"questionAnswers":[{"question":"What is the appropriate conclusion for a report with a parameter file but no use records?","answer":"Preserve verified parameter-update/storage facts; the learning mechanism still lacks use and task material and remains a candidate or unresolved.","basis":"The source text of this section and the public derivation above"},{"question":"Why do eight c_i values of 1 not imply eight e_i values of 1?","answer":"c records the presence of text, while e records substantive support; these differ, and the given vectors provide a counterexample.","basis":"The source text of this section and the public derivation above"},{"question":"After observing one overload, what must be added to claim delayed recovery?","answer":"Add formation of damage/capacity/recovery carriers, effects across windows, and proportionate comparisons; G3 is added only for an additional historical claim.","basis":"The source text of this section and the public derivation above"},{"question":"If a basic phase pattern is supported, must hysteresis also be declared supported?","answer":"No. Carrier persistence and additional historical hysteresis each require their own material and cannot be smuggled in through the basic pattern.","basis":"The source text of this section and the public derivation above"},{"question":"How does explicit proof that a necessary condition fails differ from not having read relevant material?","answer":"The former blocks that specific route; the latter usually leaves it unresolved. Neither may arbitrarily be expanded into denial of every external phenomenon.","basis":"The source text of this section and the public derivation above"}],"figures":[{"path":"/reading-assets/S-6-11/figures/section-6-11.png","alt":"1 Object and scale: who / SP / T / K, with proportionate scope; 2 Inferential dependencies: which premises support the conclusion, without making method gates into causes; 3 Enabling conditions: when it can happen, without treating names as conditions; 4 Mechanism chain: specify channels segment by segment, since diagram lines do not replace material; 5 Minimum evidence: material, comparisons, and results, since text in a field is not support; 6 Competing explanations: which explanations change the judgment, retaining comparisons and residuals; 7 Counterexamples: what limits or refutes the claim, separating counterevidence from unknowns; 8 Failure boundaries: when to stop extrapolation, without presenting candidates as established. Each of the six mechanisms implements these eight items within its own branches. Missing items become specific questions; independent facts remain, while concepts and constructions generate no external support.","caption":"Each of the six mechanisms implements these eight items within its own branches. Missing items become specific questions; independent facts remain, while concepts and constructions generate no external support."}],"diagramBrief":"The current deliverable is a static diagram; interaction has not been implemented. Any selection, switching, or clicking described below is only a future design proposal. Eight cards unfold the original text's common responsibilities without arrows of automatic confirmation. Different mechanisms need different material; the six prohibited inferential leaps are explained individually in the text.","applicability":{"realCase":"not_applicable","diagram":"applicable","reason":"This section concludes the six mechanisms' common output responsibilities, suitably illustrated by logical counterexamples and explicit teaching scenarios; no historical fact is forced into service as a shared certification of every mechanism."},"openQuestions":[],"taskId":"S-6-11","sources":[{"id":"theory","title":"Historical research manuscript: Xikari: On Conditions, Structure, and Transformation, source text supplied by the user","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Historical research manuscript, Chinese source lines 1426–1429; see sourceRefs for each section's exact range","claim_support":["6.11: terminology, contracts, burdens of argument, and boundaries of the original text; not a basis for certifying empirical facts"],"limits":["The author's theoretical text is the object being explained, not a substitute for external empirical material. Skill version 5.3.1 is not the theory's version.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-mechanisms","title":"Historical research manuscript: Xikari 6.2–6.8: six mechanisms and their branches","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Chinese source lines 1302–1411; see 6.2, 6.3, 6.5, 6.6, 6.7, and 6.8 respectively","claim_support":["6.11: the six mechanisms' distinct dependencies, material, and ceilings on conclusions; G3 enters only the corresponding additional-history branches."],"limits":["Conceptual explanation is not external support for a mechanism.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-four-states","title":"Historical research manuscript: Xikari 4.1: four states and responsibilities for null conclusions","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Chinese source lines 577–581","claim_support":["6.11: failure of the positive-support gate does not automatically support the null; distinguish not run, unresolved, counterevidence, and null conclusions."],"limits":["Formal records cannot create evidence by themselves.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-v2","title":"Xikari: On Conditions, Structure, and Transformation, v2, November 2026","url":"/downloads/Xikari-条件结构与转化论.md","source_type":"theory_source","version_or_date":"v2 / 2026-11-16","locator":"6.11 Overall Gate for Mechanism Outputs; Chinese source lines 1456–1459; SHA-256 6ef2e508474d4ac1ad07d7e4e068955342c405b5f680afcfc40d68cca3d0149c","claim_support":["The current source section and this text’s conceptual explanation of v2; not a substitute for external empirical materials."],"limits":["Older research attachments retain their original manuscript identity; the previous scope of external reading has not expanded because of this edition change."],"access_status":"read"}],"lecturePath":"/reading-assets/S-6-11/lecture.md","sourcesPath":"/reading-assets/S-6-11/sources.json","sourceSlicePath":"/reading-assets/S-6-11/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-6-11/diagrams.md","editionNote":"This page’s source text and section locations correspond to v2; historical research attachments and prior external-reading records retain their own versions and scopes.","translationOf":{"language":"zh","lesson_sha256":"93349ec5a24a54ffad187ebef2dae38befe336cde4b9eb70f0205da0461ae70c","source_sha256":"6ef2e508474d4ac1ad07d7e4e068955342c405b5f680afcfc40d68cca3d0149c"}},"6.12":{"title":"6.12 Operation Across Asynchronous Multiple Clocks","lead":"A sentence can be heard within seconds, relational expectations may change only after several interactions, and organizational resources and institutional execution have their own cycles. Stamping all changes with the same date both misjudges delayed effects and inflates temporary responses into lasting achievements.","explanation":["Chinese source location: lines 1460–1476; original anchor: section-6-12; short quotation, translated from the Chinese: “Cross-clock bridges must specify carriers, execution, confirmation, and failure conditions.” See the corresponding section on this page for the current original text; the downloaded original research excerpt preserves the historical manuscript.","A multi-circle joint state distinguishes at least five clocks: immediate, interactional, organizational, institutional, and long-term. A clock here specifies when a class of variables updates and within what window it is observed, not a fixed universal duration for each event type. One event may first change fast variables, then affect relational expectations through repeated interaction, then change resources through organizational decisions, and finally possibly enter institutional write-back. “May” does not mean that every step necessarily occurs.","The minimum immediate→interactional bridge requires a state difference to persist across multiple rounds and alter the other party's response. A single fading emotion cannot count as a stable interaction rule; equally, before the next round arrives, ineffectiveness cannot be declared prematurely. Record what carrier retains the state, whether subsequent contact occurs, and the other party's actual response.","Interactional→organizational transition requires relational or strategic changes to enter roles, processes, resources, or records. Verbal agreement and a meeting's atmosphere cannot replace implementation; role adjustments, scheduling, budgets, and work-record versions and execution each have their place. A judgment of organizational change still cannot leap directly to all institutional constraints having changed.","The organizational→institutional bridge requires verifiable changes in rules or procedures, arrangements for responsibility, and actual execution. Authorization, legal validity, and normative justification are listed separately. Publishing a document cannot replace execution; unauthorized or disputed conduct also cannot justify omitting institutional effects that actually occurred. Recording facts is neither endorsement nor permission to implement them again.","Institutional→long-term transition requires tracing continuing execution, maintenance, learning, and alternative routes, including checking for rebound after short-term compliance. Long-term is not a label stamped in advance: coverage periods, seasons, demand fluctuations, membership changes, and continuity of support must fit the claimed outcome. If observation ends on a particular date, persistence after that date cannot be fabricated.","Every cross-clock bridge specifies its carrier, execution, confirmation, and failure conditions. The carrier may be parameters, records, schedules, rules, or other states, but must be located. Execution specifies how an update actually enters a process; confirmation specifies where change is independently checked; failure conditions specify when the bridge fails to connect. Reposts sharing one publication source do not automatically add independent confirmation of execution.","Relatively fast results such as industrial expansion, signed agreements, cessation of public violence, completed facilities, and public cooperation may all have real value, yet cannot settle long-term living conditions. Continue checking execution, distribution, rights, relations, and persistence. When material is insufficient, preserve locally known results and stop distant extrapolation, neither canceling local achievements nor inventing final success.","Factual clocks and normative states cannot be merged. If rule changes or execution actually occurred, record them in the process timeline with their corresponding status, even if they violated rules, exceeded authority, or were disputed. Conversely, authorization, publication of an announcement, or an institution's declaration of completion does not mean actual execution at every local position. Both confusions distort causal timelines.","Thus distinguish no short-term change from delayed effects not yet reaching the observation window, and short-term fluctuation from long-term evolution. Update times and observation times may differ; missing records do not automatically mean absent events. But a promise of future effects cannot replace evidence missing now. Report according to each claim's horizon and stop where bridges remain unverified."],"distinctions":[{"leftTitle":"Event time","leftText":"When an action or state actually changes.","rightTitle":"Announcement / record time","rightText":"May precede or follow execution and is not interchangeable with it."},{"leftTitle":"Rule publication","leftText":"A text or decision appears.","rightTitle":"Actual institutional execution","rightText":"The process by which a rule enters specific positions, requiring independent material."},{"leftTitle":"Authorization / justification status","leftText":"Judgments concerning norms and permissions.","rightTitle":"Whether it actually occurred","rightText":"An empirical-record question; the two cannot replace one another."},{"leftTitle":"Bounded short-term achievement","leftText":"Evidenced within a particular window, object, or function.","rightTitle":"Comprehensive long-term outcome","rightText":"Requires continued checking of persistence, distribution, rights, and relations."}],"boundaries":["The five clocks impose neither a universal sequence nor fixed numbers of days; actual processes may interleave, return, or stall.","Every cross-clock bridge can fail. Success at an earlier level does not guarantee the next, and aggregate labels cannot bypass them.","Illegality, excess of authority, or dispute does not turn actual effects into non-events; explaining their formation grants no permission to implement them.","Approval and plans cannot replace execution; temporary non-observation of later effects also cannot justify declaring permanent ineffectiveness without a window.","When long-term material is not yet available, retain unknowns; do not forcibly withdraw necessary support or create dangerous interruptions for verification."],"questions":["On day 9 of the teaching timeline, may the new procedure be declared implemented?","If observation ends on day 30, may sustained attainment through day 90 be declared?","How should a process record describe an unauthorized action that was executed?","If interaction produces verbal agreement, what is still needed at minimum to reach the organizational level?","After short-term institutional compliance, why must long-term assessment still examine maintenance and alternative routes?"],"diagramPath":"/reading-assets/S-6-12/figures/section-6-12.png","caseLinks":[{"title":"Maryland renewals: submission, actual use, and approval have different dates","href":"https://health.maryland.gov/mmcp/Documents/JCRs/2023/eligibilityredetprocessJCRfinal4-24.pdf"}],"caseNotes":[{"title":"Maryland renewals: submission, actual use, and approval have different dates","text":"Maryland's 2024 report separately records submission of the mitigation plan to CMS on September 13, 2023, use of the updated renewal process beginning in November 2023, and approval of the plan in February 2024. This section adds the observation that these three event types do not share one timestamp; implementation, plan approval, and long-term results require separate evidence. Temporal order alone cannot determine the legal status of every action at the time, and the report does not use this timeline to establish long-term health effects.","sourceLabel":"Maryland FY24 Quarter 4 report, submitted 2024-05-14","sourceUrl":"https://health.maryland.gov/mmcp/Documents/JCRs/2023/eligibilityredetprocessJCRfinal4-24.pdf","sourceLocator":"Printed p. 9, item 3 mitigation plan and final paragraph, updated process utilized beginning November 2023","boundary":"Supports the reported dates and event statuses. Plan approval is not equated with authorization for every action; it does not imply every preapproval implementation was unlawful or establish long-term benefits.","href":"https://health.maryland.gov/mmcp/Documents/JCRs/2023/eligibilityredetprocessJCRfinal4-24.pdf"}],"sourceRefs":[{"section":"6.12","start_line":1506,"end_line":1522,"startLine":1506,"endLine":1522}],"outputId":"section-6-12","sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","argumentSteps":["Declare update clocks and observational coverage separately for immediate, interactional, organizational, institutional, and long-term variables.","For immediate-to-interactional transition, check repeated rounds, state retention, and the other party's response; a single emotion cannot replace them.","For interactional-to-organizational transition, check actual entry into roles/processes/resources/records; for organizational-to-institutional transition, check rules, responsibility, and execution.","For institutional-to-long-term transition, check continuing execution, maintenance, learning, and alternative routes, preserving rebounds and uncovered periods.","For each bridge, locate carriers, execution, confirmation, and failure conditions, distinguishing event time, record time, and publication time.","Register factual records alongside authorization, legal validity, and justification; neither erase events through illegality nor manufacture execution through approval.","Preserve locally known achievements; stop extrapolation beyond the horizon or population and to ultimate effects on living conditions."],"teachingExamples":[{"title":"Teaching construction: compressing several dates into one produces errors","text":"A fictional system receives feedback on day 0. Two interactions on days 1 and 3 show that the update persists and changes the other party's response. The organization decides on day 5, resources are actually allocated on day 6, a new procedure is published on day 8, and actual execution begins on day 10. If the task requires institutional execution by day 9, this construction fails; the day-8 announcement cannot substitute. If the question is only whether execution had occurred by day 11, one may answer that it had begun. The long-term target runs to day 90, but material covers only day 30, leaving 60 days unobserved. Beginning execution on day 10 is not sustained success through day 90.","assumptions":"Dates, events, and coverage are teaching assumptions. Every bridge is given in the example's text; no actual institution is claimed to operate this way.","boundary":"Meeting a deadline, beginning execution, and sustained attainment differ; lateness relative to day 9 is not permanent ineffectiveness."},{"title":"Mathematical construction: factual and authorization bits do not imply one another","text":"Let E=1 mean an action was actually executed and J=1 mean the construction's prespecified permission contract was satisfied. Case A, (E,J)=(1,0): the action occurred but permission conditions failed; both the fact and the excess-of-authority status must be recorded, without changing E to 0. Case B, (E,J)=(0,1): authorization exists but execution has not occurred, so E cannot become 1. Discussion of legal validity or normative justification requires separate fields; one J bit cannot handle them all.","assumptions":"Explicitly given binary teaching records, not a determination of any actual conduct's legal status.","boundary":"“It happened” cannot imply “it may continue to happen,” nor can authorization establish actual achievements."},{"title":"Teaching construction: an unexperienced season does not cancel current attainment","text":"A fictional facility meets prespecified service-quality targets for one month under ordinary load, with complete records; the next season's peak has not yet arrived. Its function for this month and load range may be confirmed, but year-round peak stability cannot be declared. Conversely, an unverified peak does not turn verified ordinary-period service into zero achievement.","assumptions":"No actual facility or performance data; loads and windows are teaching conditions.","boundary":"Peak evaluation must be safe, feasible, and authorized; the construction does not demand forced stress testing or withdrawal of support."}],"counterexamples":[{"identity":"constructed_boundary","text":"Long-term institutional repair is recorded as complete on the day feedback arrives.","effect":"Different update clocks are compressed into one instant, without cross-bridge material.","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"The organization approved the rule, so every local position has implemented it.","effect":"Approval differs from execution; positions and times require actual confirmation.","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"The rule change was unauthorized, so it had no effect on the real process.","effect":"Normative status does not cancel event facts; record them separately.","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"No long-term effect was seen within one month, so the feedback must have had no effect.","effect":"The horizon may be mismatched, or the feedback may truly be ineffective; compare according to the claimed window and bridging evidence.","sourceIds":["theory"]}],"questionAnswers":[{"question":"On day 9 of the teaching timeline, may the new procedure be declared implemented?","answer":"No. Execution began only on day 10; the announcement on day 8 does not satisfy the day-9 task.","basis":"The source text of this section and the public derivation above"},{"question":"If observation ends on day 30, may sustained attainment through day 90 be declared?","answer":"No. Uncovered periods remain unresolved; existing evidence within the 30-day period is retained.","basis":"The source text of this section and the public derivation above"},{"question":"How should a process record describe an unauthorized action that was executed?","answer":"Record both actual execution and unmet authority requirements, neither concealing facts nor granting permission to continue; legality and normative justification require separate checks.","basis":"The source text of this section and the public derivation above"},{"question":"If interaction produces verbal agreement, what is still needed at minimum to reach the organizational level?","answer":"Check that changes in relations/strategies enter roles, processes, resources, or records, with grounds for actual execution or use.","basis":"The source text of this section and the public derivation above"},{"question":"After short-term institutional compliance, why must long-term assessment still examine maintenance and alternative routes?","answer":"Continued operation may depend on support and uptake; short-term compliance may rebound, and long-term tasks have their own time-coverage requirements.","basis":"The source text of this section and the public derivation above"}],"figures":[{"path":"/reading-assets/S-6-12/figures/section-6-12.png","alt":"Immediate: signal arrival and fast-variable changes cannot replace repeated interaction; interaction: multiple rounds retain updates and change responses, while verbal consensus may never enter the organization; organizational: roles, processes, resources, and records, where decisions do not equal execution; institutional: rules, responsibilities, and actual execution, with legality and occurrence recorded separately; long-term: continuing execution, maintenance, and uptake, with uncovered futures unknown. The five clocks do not update on the same day. All four bridges between clocks require carriers, execution, confirmation, and failure conditions; they are not an automatic ladder of maturation.","caption":"The five clocks do not update on the same day. All four bridges between clocks require carriers, execution, confirmation, and failure conditions; they are not an automatic ladder of maturation."}],"diagramBrief":"The current deliverable is a static diagram; interaction has not yet been implemented. Any selection, switching, or clicking described below is only a design proposal for later. Five clock rows correspond to four minimum bridging responsibilities on the right, with the non-substitutability of facts and norms listed separately. The illustration prescribes no universal number of days; see the text for the specific fictional timeline.","applicability":{"realCase":"applicable","diagram":"applicable","reason":"The same official report separates submission, use, and plan approval, making it suitable for distinguishing multiple clocks. Teaching dates and the binary-authority example are separately marked fictional, avoiding legal judgments about the real case."},"openQuestions":[],"taskId":"S-6-12","sources":[{"id":"theory","title":"Historical research manuscript: Xikari: On Conditions, Structure, and Transformation, source text supplied by the user","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Historical Chinese research draft, full text lines 1430–1446; see sourceRefs for each section's exact range","claim_support":["6.12: terminology, contracts, argumentative responsibilities, and source boundaries; no empirical facts are certified on this basis"],"limits":["The author's theoretical text is the object being explained, not a substitute for external empirical material. Skill version 5.3.1 is not the theory's version.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"maryland-clocks","title":"Maryland FY24 Quarter 4: different event times","url":"https://health.maryland.gov/mmcp/Documents/JCRs/2023/eligibilityredetprocessJCRfinal4-24.pdf","source_type":"primary","version_or_date":"Report dated April 2024; submission cover letter 2024-05-14","locator":"Printed p.9, item 3 on the mitigation plan and the final paragraph on process use","claim_support":["6.12: plan submitted 2023-09-13; use of updated processes began in 2023-11; plan approved in 2024-02."],"limits":["Dates alone do not establish authorization/unlawfulness of every action or long-term health outcomes; the approval concerned that mitigation plan."],"access_status":"partially_read"},{"id":"theory-writeback","title":"Historical research draft: Xikari 6.4 and 7.1, executed write-back and H3 boundaries","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Chinese source lines 1338–1351 and 1469–1482","claim_support":["6.12: acceptance for processing, fields, execution, and persistence are separate; classification does not authorize real action."],"limits":["Factual occurrence and normative status cannot replace one another.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-v2","title":"Xikari: On Conditions, Structure, and Transformation, v2, November 2026","url":"/downloads/Xikari-条件结构与转化论.md","source_type":"theory_source","version_or_date":"v2 / 2026-11-16","locator":"6.12 Operation of asynchronous multiple clocks; Chinese source lines 1460–1476; SHA-256 6ef2e508474d4ac1ad07d7e4e068955342c405b5f680afcfc40d68cca3d0149c","claim_support":["The current source section and this text’s conceptual explanation of v2; not a substitute for external empirical materials."],"limits":["Older research attachments retain their original manuscript identity; the previous scope of external reading has not expanded because of this edition change."],"access_status":"read"}],"lecturePath":"/reading-assets/S-6-12/lecture.md","sourcesPath":"/reading-assets/S-6-12/sources.json","sourceSlicePath":"/reading-assets/S-6-12/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-6-12/diagrams.md","editionNote":"This page’s source text and section locations correspond to v2; historical research attachments and prior external-reading records retain their own versions and scopes.","translationOf":{"language":"zh","lesson_sha256":"5fcd70feeaae3e816c8b574039099aaa93e29f577d353c76f206f7e06db2184d","source_sha256":"6ef2e508474d4ac1ad07d7e4e068955342c405b5f680afcfc40d68cca3d0149c"}},"6.13":{"title":"6.13 Cross-circle cascades and coevolution","lead":"A message crossing a bridge does not mean people, resources, and action cross along with it. Cross-circle analysis must separate every hop: what exactly was transmitted, on what grounds does the next location change, and where does the process stop?","explanation":["Chinese source location: lines 1477–1488; source anchor section-6-13; short quotation, translated from Chinese: ‘At every level, recheck the object, channel, scale, and evidence.’ See the corresponding section on this page for the current source; the downloadable original research excerpt preserves the historical draft.","A cascade occurs when a local change in one circle triggers changes in others through channels. Channels may include overlapping membership, bridging interfaces, shared resources, network transmission, or downward institutional action. Membership overlap may let the same person take up two positions; shared resources may transmit use at one location into shortage elsewhere; downward institutional action may change local procedures. These are mechanism types requiring specific identification; their names do not establish that they have occurred.","Re-register objects, channels, scales, and evidence at each level. A change at A and support for A→B do not imply B→C, much less C's long-term outcomes. Observational units, tasks, states, windows, and identity criteria may change across circles; specify their correspondence instead of reusing the first location's effect size or threshold. Insufficient capacity, filtering, delay, cancellation, and local exclusion zones can all interrupt continuation.","First ask what spreads: message arrival, opinion confirmation, adoption, actual cooperation, receipt of funds, and equipment supply are different state variables. A message may cross a single bridge; action may require multiple participants to be available in the same window, confirmation from different sources, and safe on-site conditions. A network path establishes only possible connectivity in the model, not the feasibility of real action.","The same message arriving through three channels may still have only one original basis. Confirmation by different people also requires checking their source relationships and cannot automatically count as statistically independent samples. Even genuine confirmation from separate sources does not mean these people have actually cooperated. A bridge's endpoint determines where signals concentrate; sequence and duration determine whether conditions can be satisfied simultaneously; safety and authority have separate responsibilities.","A failure triggering another requires checking channels, alternative explanations, and effects hop by hop in temporal order. Multiple failures jointly obstructing recovery require checking which recovery resources must arrive together. A shared external cause damaging multiple locations requires checking common exposure. These three graphs may coexist in one accident, but multiple locations having problems cannot uniformly be written as serial contagion.","People's adoption through multiple sources and facilities' supply dependencies may influence one another, but using the same threshold cannot dispense with explanation. The former concerns information sources, trust, intentions, and action conditions; the latter may concern power capacity, logistical accessibility, and material specifications. ‘Needs two neighbors,’ if merely a model rule, is neither a universal law of human behavior nor a physical law of a power grid.","Clustering describes connections among local neighbors, not whole-network coverage directly. Local closure may reinforce signals while concentrating contact in groups already reached, reducing cross-group endpoints and effective multi-source access. A real experiment finding better diffusion in one kind of clustered network can coexist with limited cross-group coverage in another explicit model. Neither may be elevated into a monotonic law for all networks.","Coevolution additionally requires at least two objects to mutually change choice environments, transition probabilities, or constraints over a period, while retaining their respective independent identity criteria K and corresponding object identities. K is only the identity criterion within the complete object contract, not the whole contract. Synchronization from a common external cause alone, one-way influence alone, or return signals that do not alter subsequent states are insufficient for coevolution as defined here.","If the original two objects are merely merged or absorbed, first check nesting, interrupted identity, or object transformation; ‘they are now hard to distinguish’ is not the strongest proof of coevolution. Descriptive object change still differs from formal G4 transformation eligibility, which requires its own transformation evidence. Independently supported domain observations do not become invalid for lacking formal instance status in this framework.","Cascades and coevolution carry no inherent value direction. Tight coupling may aid coordination or amplify vulnerability and diffusion of responsibility; decoupling may sacrifice efficiency or protect autonomy and limit losses. Knowing a channel exists does not permit using it to manipulate people or intervene. Evaluation and action still require the normative level to judge targets, prices to be paid, rights, responsibilities, and authorization."],"distinctions":[{"leftTitle":"Message arrival","leftText":"Information has entered the target's receiving position.","rightTitle":"Action occurs","rightText":"The target possesses and actually satisfies conditions for adoption, cooperation, and resources."},{"leftTitle":"Repeated relaying","leftText":"May originate from the same original basis.","rightTitle":"Multi-source confirmation","rightText":"Requires checking origins and dependencies, and does not automatically equal actual cooperation."},{"leftTitle":"Failure cascade","leftText":"An earlier failure triggers a later one through a channel.","rightTitle":"Recovery dependencies","rightText":"Multiple supplies jointly determine whether recovery is possible, without necessarily causing each other's initial failure."},{"leftTitle":"Common external cause","leftText":"The same exposure causes changes in multiple locations.","rightTitle":"Mutual change","rightText":"Each object changes the other's subsequent conditions, requiring separate evidence for each."},{"leftTitle":"Local clustering","leftText":"A structural feature of connections among neighbors.","rightTitle":"Whole-network coverage","rightText":"Also depends on seeds, bridging, dynamic rules, and action duration."},{"leftTitle":"Coevolution","leftText":"Object identities are retained separately, with continuing mutual change.","rightTitle":"Absorption/transformation","rightText":"Original object relations or identities undergo a different kind of change; names alone cannot settle it."}],"boundaries":["An established earlier level does not remove later levels' need for their own evidence. Failure may interrupt a chain locally; the choice is not all success or all failure.","The number of source people is not inherently the number of independent samples, and the number confirming is not the number present to cooperate.","Temporal order is one type of information required for mechanism identification; order alone does not establish a causal edge.","Human threshold models, facility-supply constraints, and counts of same-source messages have different semantics and cannot be reused directly by relabeling.","High clustering may strengthen local access or reduce cross-group coverage; both models and experiments must specify their networks, rules, and observed objects.","Check K within each object contract separately; unchanged criterion text does not mean an object still meets it or continues to exist independently.","Serial failure transmission, recovery dependencies, and common causes may mix; do not force every real event into just one graph type.","Edges with insufficient evidence remain unresolved. Failure to find transmission is not proof of no transmission, and model reachability is not observed occurrence.","Explanation, evaluation, and permission have separate responsibilities; efficient coupling does not automatically confer authority to implement."],"questions":["Can four people forwarding the same report directly count as four independent confirming sources?","If each of two collaborators appears for one hour, why might they still fail to complete one hour of collaboration?","What is the final coverage of the threshold-2 models on a triangular prism and a complete bipartite graph, and why?","Does this overturn real experiments in which clustered networks spread behavior better?","When multiple failures coexist, which three explanations must at least be checked?","A and B exchange information, but B's information never changes A's subsequent conditions. Is that enough for coevolution?","If lower coupling reduces transmission, should decoupling automatically be adopted?"],"diagramPath":"/reading-assets/S-6-13/figures/section-6-13.png","caseLinks":[{"title":"The 2010 online-forum experiment: diffusion of registration behavior, not health outcomes","href":"https://ndg.asc.upenn.edu/wp-content/uploads/2016/04/Centola-2010-Science.pdf"},{"title":"Restoring power after the 2017 hurricanes: logistical supply as a condition of recovery","href":"https://www.gao.gov/assets/gao-19-296.pdf"}],"caseNotes":[{"title":"The 2010 online-forum experiment: diffusion of registration behavior, not health outcomes","text":"Centola randomly assigned participants to clustered lattice and rewired random networks while preserving node degree. The behavior being diffused was registering for a health forum; registered neighbors each triggered invitations. The study reports wider, faster diffusion in the former. The additional point here is signals from different neighbors who have adopted and the network structure; total message-forward counts cannot replace them.","sourceLabel":"Centola 2010, original paper publicly hosted by the author's institution","sourceUrl":"https://ndg.asc.upenn.edu/wp-content/uploads/2016/04/Centola-2010-Science.pdf","sourceLocator":"Science 329 (2010), methods and results on printed pp.1194–1196; limitations on pp.1196–1197 (PDF pages 2–5)","boundary":"Anonymous participants could not contact one another directly. Forum registration does not equal improved health, and the paper establishes neither a universal hard threshold nor a monotonic clustering law. The main text was checked; supplementary material and raw data were not independently verified.","href":"https://ndg.asc.upenn.edu/wp-content/uploads/2016/04/Centola-2010-Science.pdf"},{"title":"Restoring power after the 2017 hurricanes: logistical supply as a condition of recovery","text":"In its 2019 report, GAO identifies recovery barriers from documents and interviews: ports and airports in Puerto Rico and the U.S. Virgin Islands lacked power after the hurricanes, hindering delivery of repair materials; simultaneous recovery in many locations also raised material demand and strained supply. This section adds attention to continuity of recovery resources rather than repeating power-restoration percentages.","sourceLabel":"U.S. Government Accountability Office, GAO, report dated 2019-04-18","sourceUrl":"https://www.gao.gov/assets/gao-19-296.pdf","sourceLocator":"GAO-19-296, printed pp.18–19, ‘Logistical challenges’ and ‘Availability of materials’ (PDF pages 22–23)","boundary":"The report supports logistical and material constraints during recovery. It cannot establish that every initial failure propagated hop by hop, or justify applying human multi-source-adoption thresholds to electricity and logistics; the complete causal network has not been independently reconstructed.","href":"https://www.gao.gov/assets/gao-19-296.pdf"}],"sourceRefs":[{"section":"6.13","start_line":1523,"end_line":1534,"startLine":1523,"endLine":1534}],"outputId":"section-6-13","sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","argumentSteps":["Fix the change to explain, starting point, target objects, and window, registering states and scales separately at each level.","Identify whether each edge actually transmits messages, resources, behavior, or rules; specify channels and enabling conditions.","Check starting-point change, arrival, target response, and competing explanations hop by hop. Retain unresolved status at bridges not yet checked; do not continue the chain automatically.","For multi-source claims, check original sources, dependencies, and endpoints; for cooperation claims, check personnel, timing, duration, and feasibility conditions.","Separate serial failure transmission, joint recovery dependencies, and common-cause exposure; map them together if needed, without exchanging edge meanings.","Place clustering, edge counts, and shortest paths within the declared dynamic rules; model calculations prove only within-model results.","When claiming coevolution, check both independent object contracts, mutual change, and the sustained window, excluding one-way effects, common external causes, and absorption.","Report interruption points, local knowns, and out-of-scope unknowns; evaluation or real action requires separate normative and authorization responsibilities."],"teachingExamples":[{"title":"Teaching construction: three relays, two confirmations, and one action window","text":"Fictional target T receives three messages from P, Q, and R, all traceable to the same record O. If the rule requires two distinct original verification sources, the current source count is 1; three arrivals still fail the requirement. Adding source V later raises the source count to 2, but still does not satisfy a separate ‘two people cooperating simultaneously’ rule. Let the action window be [0,3), with P available only during [0,1) and Q only during [2,3). Their availability intervals have an empty intersection, so action cannot start under this rule. If Q instead is available during [0.5,1.5), the intersection is [0.5,1), only 0.5 units. A requirement of 1 continuous unit still fails; a requirement of 0.5 units is feasible if all other conditions are met.","assumptions":"The fictional rules separately define source deduplication, personnel availability, and duration. Time uses abstract units. Safety, equipment, and authorization are assumed satisfied only in the final feasibility judgment, without claiming actual occurrence. Distinct sources are not additionally assumed statistically independent.","boundary":"This establishes only the nonequivalence of arrival, confirmation, and cooperation; two sources or 0.5 time units cannot be treated as universal real-world thresholds."},{"title":"Mathematical construction: with the same six nodes and degree three, high clustering can still stop at half the network","text":"Take nodes 0–5 in undirected simple graphs. Graph P is a triangular prism with edges 01,12,20,34,45,53 and 03,14,25. Graph B is complete bipartite with partitions {0,1,2} and {3,4,5}, every cross-partition edge and no within-partition edges. Both graphs are connected, have 9 edges, and give every node degree 3. Define a node's local clustering coefficient as the number of edges among its three neighbors divided by 3. In P, every node has exactly 1 such edge, so average clustering is 1/3; in B it is 0. Let the initial active set be A₀={0,1}, with synchronous permanent-activation rule Aₜ₊₁=Aₜ∪{v:|N(v)∩Aₜ|≥2}. In P, only node 2 activates in round one, giving A₁={0,1,2}; each node in the other triangle receives only one cross-group connection, so activation stops at 3 nodes. In B, nodes 3,4,5 each receive from 0 and 1 in round one, giving A₁={0,1,3,4,5}; in round two, node 2 has three active neighbors, bringing the final count to 6. Thus higher clustering does not guarantee greater whole-network coverage in this complex-threshold model. P's node 2 receives local reinforcement in round one, while B's node 2 activates only in round two, also showing that local early progress differs from whole-network success.","assumptions":"Threshold 2, seed positions, synchronous updating, and permanent activation are explicit teaching assumptions. Node identities are fixed, with no outside seeds or decay. The construction can be enumerated exactly; it is not data from a human experiment.","boundary":"This refutes the unconditional rule ‘more clustering means more coverage.’ The two topologies also change cross-group endpoints, so the difference cannot be attributed to an independently controlled causal effect of the clustering coefficient alone. It also does not refute Centola's results under that study's design."},{"title":"Mathematical construction: different equations for three kinds of ‘problems in multiple places’","text":"In the serial-transmission model, failure bit aₜ is fixed at 1, bₜ₊₁=aₜ, and cₜ₊₁=bₜ. Starting from (a₀,b₀,c₀)=(1,0,0), states become (1,1,0) and (1,1,1), with failure entering hop by hop. The recovery model uses p and q for availability of two resources and recovery-feasibility bit r=p∧q: r=0 for 00,01,10 and r=1 for 11. This does not state that p's failure causes q's failure. The common-cause model lets external shock u determine a=u and b=u: when u=1, both fail, still without a→b. All three models can have two failure bits simultaneously equal to 1, but offer different explanations.","assumptions":"Binary deterministic rules serve to distinguish the logic. The serial-transmission example has no repair; the recovery example assumes the two resources are necessary and jointly sufficient; the common-cause example ignores other paths. Here r is the model's recovery-feasibility bit, not evidence that recovery was actually executed.","boundary":"Real events may include all three mechanisms simultaneously; a cross-sectional state alone cannot select one. Model equations also do not themselves establish real causal direction."},{"title":"Teaching construction: two-way information lines are insufficient, and so is a common shock","text":"Two fictional independent organizations A and B each retain complete object contracts. A changes scheduling, changing B's available resource periods; B adjusts supply accordingly, actually changing A's available schedules in the next round. Only this supplies a candidate mechanism of mutual change. If B's reply is archived without entering later scheduling, there is only communication return. If both stop work because of the same external shutdown order, first examine the common cause. If B has lost independent object identity and become an internal unit of A, examine nesting or object conversion instead.","assumptions":"An entirely fictional conditional comparison; “actually changes” is a construction assumption. Reality requires checking versions, execution, alternatives, and both identities, not substituting two drawn lines.","boundary":"Does not establish real organizational coevolution or infer normative justification for any restructuring from mechanism feasibility."}],"counterexamples":[{"identity":"constructed_boundary","text":"A network has a shortest path, so it must permit simultaneous action by multiple people.","effect":"A message path does not supply an overlapping cooperation window, duration, or action conditions.","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"Three retellings all originate from O but are counted as three independent confirmations.","effect":"Repeated sources inflate confirmation counts; successive arrivals may still be real facts.","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"The triangular prism has average clustering 1/3, above the complete bipartite graph's 0, so threshold-2 diffusion must reach more nodes.","effect":"The stated models have equal node counts, degrees, and edge counts and are both connected, yet yield 3 versus 6, limiting unconditional generalization.","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"A port power outage obstructs delivery of repair materials, so the port must have caused the grid's initial damage.","effect":"A recovery constraint cannot be rewritten as the initial fault's cause; check timing and channels separately.","sourceIds":["gao-recovery"]},{"identity":"constructed_boundary","text":"Two objects change simultaneously, or have merged into one object, so coevolution is established.","effect":"Common external causes and identity conversion require separate checks; synchronization or merger does not imply mutual change between two objects.","sourceIds":["theory"]}],"questionAnswers":[{"question":"Can four people forwarding the same report directly count as four independent confirming sources?","answer":"No. First deduplicate original grounds and check source relationships. Arrival of four forwards can remain a fact; independent support cannot be accumulated by headcount.","basis":"The source text of this section and the public derivation above"},{"question":"If each of two collaborators appears for one hour, why might they still fail to complete one hour of collaboration?","answer":"If available periods do not overlap, joint duration is 0; even a half-hour overlap fails a one-hour requirement. Total presence time cannot replace simultaneous conditions.","basis":"The source text of this section and the public derivation above"},{"question":"What is the final coverage of the threshold-2 models on a triangular prism and a complete bipartite graph, and why?","answer":"3 and 6, respectively. In the former, each node of the other triangle has only one active cross-group edge, so diffusion stops. In the latter, all three opposite-side nodes receive both seeds in the first round, then activate the remaining node in the second.","basis":"The source text of this section and the public derivation above"},{"question":"Does this overturn real experiments in which clustered networks spread behavior better?","answer":"No. The teaching model supplies a counterexample with different topology, seeds, and deterministic rules; the experiment retains bounded results under its own design and behavioral indicators. Neither automatically becomes a universal law.","basis":"The source text of this section and the public derivation above"},{"question":"When multiple failures coexist, which three explanations must at least be checked?","answer":"Sequential fault triggering, multiple conditions jointly obstructing recovery, and exposure to common external causes; examine timing, resource dependence, and common-cause material. These may coexist in reality.","basis":"The source text of this section and the public derivation above"},{"question":"A and B exchange information, but B's information never changes A's subsequent conditions. Is that enough for coevolution?","answer":"Insufficient. Communication return has not produced effective mutual change; independent object identities, persistence windows, and actual effects in both directions must also be checked.","basis":"The source text of this section and the public derivation above"},{"question":"If lower coupling reduces transmission, should decoupling automatically be adopted?","answer":"No. Lost coordination, resource costs, rights, and responsibilities must also be compared under normative and authorization conditions; mechanism effects do not replace reasons for action.","basis":"The source text of this section and the public derivation above"}],"figures":[{"path":"/reading-assets/S-6-13/figures/section-6-13.png","alt":"Sequential faults: A fails → B fails → C fails; check timing and channels at each step. Recovery dependence: resource P and resource Q → feasible recovery R, requiring both together, without inferring P causes Q. Common external cause: shock U → A fails; U → B fails; check common exposure, without automatically adding A→B. Teaching mechanism diagram: sequential effects on the left, jointly necessary conditions in the middle, and common external cause on the right. All three can coexist; multiple faults together do not allow arbitrary choice among explanations.","caption":"Teaching mechanism diagram: sequential effects on the left, jointly necessary conditions in the middle, and common external cause on the right. All three can coexist; multiple faults together do not allow arbitrary choice among explanations."}],"diagramBrief":"The current deliverable is a static figure; interaction has not been implemented. References below to selecting, switching, or clicking are ideas for later design only. Three panels depict serial transmission, joint recovery conditions, and common external causes, alongside this lesson's binary rules. A future interaction could vary recovery resources or external shocks to show different outcomes; presently the figure is static only.","applicability":{"realCase":"applicable","diagram":"applicable","reason":"An actual social-diffusion experiment and postdisaster logistics recovery illustrate behavioral entry and supply dependence respectively, with their statuses kept separate; models explain only differences in conditions."},"openQuestions":["Every step within specific circles still needs material on objects, channels, timing, and alternatives; no complete cascade identification or coevolution certification for a real case is supplied.","Centola's main text supports its bounded experimental results; this lesson did not independently obtain supplementary material or raw data, or conduct new participant or reader experiments.","Authorization and normative evaluation of actual decoupling, resource allocation, or organizational changes are not provided here."],"taskId":"S-6-13","sources":[{"id":"theory","title":"Historical research manuscript: Xikari: On Conditions, Structure, and Transformation, source text supplied by the user","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Historical research manuscript, Chinese full-text lines 1447–1460; see sourceRefs for each section's exact range","claim_support":["6.13: terminology, contracts, responsibilities of argument, and source boundaries; these do not certify empirical facts."],"limits":["The author's theoretical text is the object being explained, not a substitute for external empirical material. Skill version 5.3.1 is not the theory's version.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"centola-2010","title":"Damon Centola: The Spread of Behavior in an Online Social Network Experiment","url":"https://ndg.asc.upenn.edu/wp-content/uploads/2016/04/Centola-2010-Science.pdf","source_type":"primary","version_or_date":"2010-09-03，DOI 10.1126/science.1185231","locator":"Science 329(5996),1194–1197; methods pp.1194–1195, results p.1196, design limitations pp.1196–1197","claim_support":["6.13 real case: randomized network conditions, preserved degree, forum-registration indicator, and signals triggered separately by each registered neighbor; diffusion was broader and faster under clustered conditions.","6.13 support boundary: anonymity and no direct contact; extension to costly real-world behavior was an expectation or matter for further research in the original."],"limits":["Only the main text was checked, not supplementary material or raw data. Registration behavior is not treated as a health outcome; no formal G-instance or universal threshold is retrospectively awarded."],"access_status":"partially_read"},{"id":"gao-recovery","title":"GAO-19-296: 2017 Hurricane Season—Federal Support for Electricity Grid Restoration in the U.S. Virgin Islands and Puerto Rico","url":"https://www.gao.gov/assets/gao-19-296.pdf","source_type":"primary","version_or_date":"2019-04-18","locator":"Printed pp.18–19; PDF pp.22–23, subsections on logistical challenges and material availability","claim_support":["6.13 real case: documents and interviews record port/airport power outages obstructing material transport, and repair-material demand and supply constraints across locations."],"limits":["These materials support recovery constraints, not independent identification of the transmission network for every initial fault; this lesson did not reconstruct complete causal chains for individual facilities."],"access_status":"partially_read"},{"id":"theory-object","title":"Historical research manuscript: Xikari 3.1, D0 object contracts and K identity criteria","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Chinese source lines 425–448, especially 429 and 447","claim_support":["6.13: the complete object contract differs from its identity criterion K; the two objects' identities and applicable scopes require separate checks."],"limits":["Definitions do not replace real-world object identification.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-coevolution","title":"Historical research manuscript: Xikari 6.9–6.10, coevolution and identity conversion","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Chinese source lines 1412–1425","claim_support":["6.13: bidirectional effects, common external causes, ineffective returns, and absorption/repair boundaries."],"limits":["Parallel changes are not automatically bidirectional causation.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-conversion","title":"Historical research manuscript: Xikari 4.6, G4 conversion registration","url":"/reading-assets/theory.md","source_type":"theory_source","version_or_date":"manuscript-20261013-df579dbdbb68","locator":"Chinese source lines 642–650","claim_support":["6.13: descriptive changes and formal conversion eligibility must not be conflated."],"limits":["This lesson submitted no real G4-instance.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-v2","title":"Xikari: On Conditions, Structure, and Transformation, v2, November 2026","url":"/downloads/Xikari-条件结构与转化论.md","source_type":"theory_source","version_or_date":"v2 / 2026-11-16","locator":"6.13 Cross-circle cascades and coevolution; Chinese source lines 1477–1488; SHA-256 6ef2e508474d4ac1ad07d7e4e068955342c405b5f680afcfc40d68cca3d0149c","claim_support":["The current source section and this text’s conceptual explanation of v2; not a substitute for external empirical materials."],"limits":["Older research attachments retain their original manuscript identity; the previous scope of external reading has not expanded because of this edition change."],"access_status":"read"}],"lecturePath":"/reading-assets/S-6-13/lecture.md","sourcesPath":"/reading-assets/S-6-13/sources.json","sourceSlicePath":"/reading-assets/S-6-13/source-slice.md","supplementaryFiles":[],"diagramsPath":"/reading-assets/S-6-13/diagrams.md","editionNote":"This page’s source text and section locations correspond to v2; historical research attachments and prior external-reading records retain their own versions and scopes.","translationOf":{"language":"zh","lesson_sha256":"104fce107cf6210249f7441b64199d85ac0703803303467a6649787915018d9d","source_sha256":"6ef2e508474d4ac1ad07d7e4e068955342c405b5f680afcfc40d68cca3d0149c"}},"6.14":{"title":"6.14 Search Order for Mechanisms and Paths","lead":"Search order is an order for finding candidates, not a ranking of which is more likely true. Being found first, having complete cards, or following a common search practice cannot promote a candidate into an identified mechanism.","explanation":["Chinese source location: lines 1489–1502, ‘6.14 Search Order for Mechanisms and Paths.’ Brief quotation, translated from Chinese: ‘This order is only the working order for finding candidates; it does not mean that a candidate found earlier is more likely to be true’ (current Chinese source line 1493; historical quotation locator: line 1471). The lesson is separate from the source text.","This section concludes the use of Part VI: §§6.2–6.10 provide conditional mechanisms and their boundaries; §6.11 is the overall gate for mechanism outputs; §§6.12 and 6.13 address multiple clocks and cross-circle relations. This section asks how to find those materials for a specific problem without exceeding their conditions.","The first paragraph specifies two steps: filter potentially applicable mechanisms by object, scale, window, and requested output, then seek paths based on observed differences in state. Defining applicability first avoids taking a phenomenon through every mechanism in search of a matching name.","The same paragraph limits state prototypes: those for human collectives apply only to objects with the corresponding conditions. Actors, technical systems, and natural processes cannot share the same state set merely because their names sound similar. This agrees with §7.5's ‘S0–S6 can serve only as state prototypes for human intentional collectives’ and the state prototypes in §8.3. Two constructed examples: a device being ‘newly assembled’ and a lake ‘beginning eutrophication’ cannot be assigned human-collective prototypes such as S0 merely because the wording seems similar.","The second paragraph lists four types of input material: the object's currently confirmable state; confirmable direct changes after an event; channels, capacity, and clocks able to carry subsequent change; and mechanisms and external disturbances not yet distinguished. Including the last category means making room for competing explanations from the outset of the search.","Candidates have two sources: state-exit conditions suggest path candidates, while observed changes suggest mechanism candidates. Enabling conditions, propagation stages, and minimum evidence are then checked individually. The two sources answer different questions: §8.4 says a path describes ‘how a state configuration or object contract changes.’ On this lesson's interpretation, a mechanism candidate concerns which process might produce the observed change; it remains a candidate until the individual checks are complete.","Order is not probability. A candidate found first is not thereby more likely to be true. The fifth paragraph allows search order to be adjusted based on omissions, misjudgments, and cost of use. These assess search performance; they do not judge which candidate is true in this case. Treating the first match as the default answer is precisely the leap this section excludes.","The third paragraph requires retaining competing candidates that explain the same phenomenon and simple baselines whenever a candidate is used. It names three distinctions: returned signals versus learning (§6.3 requires a return to produce a retainable update that actually enters subsequent tasks); local overload versus temporary demand increases, reduced capacity, and common external causes (the full CM-LOAD conditions in §6.6 determine what counts as local overload); and cross-circle cascades versus synchronous exposure (§6.13 distinguishes one failure triggering the next from a common external cause damaging several locations simultaneously). A search match cannot justify omitting counterexamples or exclusions required by the relevant complete contracts.","The fourth paragraph requires four items for each candidate path: conditions under which it continues to hold, observable changes the mechanism should produce first, contrary signals, and stopping points. Without enabling evidence, a candidate can still organize discriminating observations, but cannot become an identified mechanism. This aligns with §6.11: when items are missing, retain only candidate mechanisms or questions for checking.","An early signal cannot merely restate the outcome in a milder form. In a constructed example, if the expected outcome is markedly longer waits, ‘waiting starts to increase’ is only a mild version of that same outcome, not an early signal of local overload. Temporary demand increases and reduced capacity can also lengthen waits, so it does not distinguish those candidates. Under §12.6, an early signal is an observable change the path's mechanism should produce first. Section 1.2 likewise calls for early and contrary signals that distinguish paths when introducing analysis of specific events. If several paths share the same evidence, repeated citation does not add independent support.","The fifth paragraph permits adjusting search order based on omissions, misjudgments, and cost of use, but requires preserving the original mechanisms' applicability boundaries and comparison with simpler search methods. Convenient searching, complete cards, or several analysts using the same order do not prove a real mechanism exists. Multiple people using the same order may share the same omissions.","The strongest objection asks why prescribe an order if it does not represent probability. On this lesson's interpretation, the order serves searching with fewer omissions and errors at a manageable cost, not ranking truth. Defining applicability first avoids seeking a name for one phenomenon across every mechanism; including undistinguished mechanisms and external disturbances among the inputs preserves space for competitors. This lesson has not compared whether these features actually reduce omissions and errors. The source requires changes to preserve applicability boundaries and face comparison with simpler search methods. Section 16.24 also bars claiming superiority to alternatives without an actual comparison. Inclusion in the framework therefore cannot establish that this order is better."],"argumentSteps":["Premise: mechanism conditions and applicability boundaries are distributed across Part VI, state prototypes, and the path library. A specific problem requires a procedure for finding candidates.","Connection: first define applicability by object, scale, window, and output. Then start from four types of material, deriving path candidates from exit conditions and mechanism candidates from observed changes, and check enabling conditions, propagation stages, and minimum evidence individually.","Conclusion: search produces candidates and arrangements for discriminating observations, not identified mechanisms.","Qualification: order is not a probability ranking. Retain competitors, simple baselines, counterexamples, and exclusions. Early signals cannot be diminished versions of the outcome, and shared evidence does not accumulate.","Evidential responsibility: adjustments must preserve applicability boundaries and be compared with simpler search methods. Convenience, completeness, and multiple users are not mechanism evidence."],"distinctions":[{"leftTitle":"Search order","leftText":"The working order for finding candidates.","rightTitle":"Ranking candidates by likelihood","rightText":"The source explicitly rejects the idea that a candidate found first is more likely true."},{"leftTitle":"Path candidate","leftText":"Proposed from state-exit conditions, describing how a state configuration might change.","rightTitle":"Candidate mechanism","rightText":"Proposed from observed changes, identifying a process that might produce them, still awaiting checks."},{"leftTitle":"Candidate","leftText":"Without enabling evidence, it can organize discriminating observations but cannot be promoted.","rightTitle":"Identified mechanism","rightText":"Enabling conditions, propagation stages, and minimum evidence must be checked individually."},{"leftTitle":"Early signal","leftText":"An observable change the mechanism should produce before the outcome.","rightTitle":"A diminished version of the outcome","rightText":"Merely restating the outcome more mildly cannot make it an early signal."},{"leftTitle":"Citing the same evidence in several places","leftText":"Still constitutes one piece of evidence.","rightTitle":"Multiple independent supports","rightText":"Must come from mutually independent materials."},{"leftTitle":"State prototypes for human collectives","leftText":"Apply only to objects satisfying the corresponding conditions.","rightTitle":"States with similar names","rightText":"Actors, technical systems, and natural processes cannot borrow prototypes merely through names."}],"boundaries":["A search match cannot justify omitting counterexamples and exclusions specified by the relevant complete contract.","Without enabling evidence, a candidate does not become an identified mechanism.","Human-collective prototypes such as S0–S6 are not applied to individuals, technical systems, or natural processes.","A mild version of the outcome cannot serve as an early signal. Early signals are observable changes the mechanism should produce first; when listing them, also check whether they distinguish paths (§1.2, §12.6).","Convenient searching, complete cards, or multiple users of the same order do not prove a real mechanism. Adjustments must preserve applicability boundaries and face comparison with simpler methods."],"counterexamples":[{"identity":"constructed_boundary","text":"Constructed conditional counterexample: ‘The load mechanism was the first search result and its conditions roughly fit, so it must be overload.’","effect":"Being found first does not mean greater likelihood of truth; distinguish temporary demand growth, reduced capacity, and common external causes as well.","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"Constructed conditional counterexample: ‘This scheduling system's release notes call its stages “consolidation” and “expansion,” similar to S0 “anchor consolidation” and S2 “first expansion,” so use S0–S6 to stage the system itself.’","effect":"State prototypes apply only to human collectives meeting the corresponding conditions. Similar names do not qualify a technical system.","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"Constructed conditional counterexample: ‘The feedback form has reached the department, so the department has learned.’","effect":"Returned signals must be distinguished from learning; learning requires a retainable update actually entering subsequent tasks.","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"Constructed conditional counterexample: ‘Five analysts independently completed the same search card and agreed, confirming the mechanism.’","effect":"Multiple people using the same order do not prove a mechanism; a shared search procedure can produce shared omissions.","sourceIds":["theory"]},{"identity":"constructed_boundary","text":"Constructed conditional counterexample: ‘Two paths both cite the same waiting-time record, so there are two independent pieces of support.’","effect":"Repeated citation of shared evidence does not add independent support.","sourceIds":["theory"]}],"teachingExamples":[{"title":"Teaching construction: searching for candidates when waiting times increase","text":"Imagine a community service office where, two weeks after a new appointment rule launches, waiting times at the document-processing counter's morning appointment sessions increase markedly. Records distinguish that counter and time slot rather than using only an office-wide mean. First define applicability: the object is the reception process, not a human collective to which state prototypes apply, so S0–S6 are not used. The scale is one counter and one time slot, focusing on the morning document counter while recording other counters and periods as comparisons. The window spans four weeks before to four weeks after launch. The requested output is candidate mechanisms and discriminating observations, not attribution of responsibility. The four input types are queue records by counter and time, the increase in waits, staff service hours plus the appointment system and weekly roster, and undistinguished factors such as the new rule, a seasonal epidemic, and closure of a nearby office.\\nCandidate A, local overload: under §6.6 CM-LOAD, measure same-type demand and available capacity at the same position and within the same window, recording their locations and distributions. The expected prior change is a gap in which same-type demand exceeds available capacity at that counter and time, before waits become markedly longer. Contrary signals include no measurable gap there, or longer waits distributed uniformly across counters and periods.\\nCandidate B, a temporary demand increase: office-wide arrivals should rise first. Contrary signals are unchanged arrivals or arrivals increasing only after waits lengthen.\\nCandidate C, reduced capacity: available service hours should fall first, or individual processing times should rise with arrivals unchanged. The contrary signal is neither changing.\\nCandidate D, a common external cause: an external factor simultaneously increases arrivals and reduces staffing, aligned in time with the changes. Contrary signals are its absence or lack of temporal alignment.\\nSimple baseline: the before-and-after difference falls within fluctuations in the same season of previous years.\\nDo not call ‘waiting starts to increase’ Candidate A's early signal, count the same queue record as independent support for A and B, or default to A because it comes first on the search card.","assumptions":"The office, rule, window, external factors, and all observables are teaching assumptions, not any real institution or event. This example omits each candidate's continuation conditions and stopping points.","boundary":"This illustrates only search and recording structure. It identifies no true candidate and is neither a formal load-mechanism instance nor causal identification. Only part of §6.6's complete conditions is illustrated; actual use requires returning to the source."}],"questions":["Is a candidate found earlier more likely true? On what basis may search order be adjusted?","Where do path candidates and mechanism candidates respectively come from?","Which four items must a candidate path specify at minimum? What can it still do without enabling evidence?","If the expected outcome is markedly longer waits, why is ‘waiting starts to increase’ not an early signal of local overload?","Can complete cards and multiple analysts using the same search order prove a mechanism? What comparison is required when adjusting the order?"],"questionAnswers":[{"question":"Is a candidate found earlier more likely true? On what basis may search order be adjusted?","answer":"No. The source says the order is only for finding candidates, not evidence that earlier ones are more likely true. Search order may be adjusted based on omissions, misjudgments, and cost of use, while preserving the original mechanisms' applicability boundaries and facing comparison with simpler search methods.","basis":"§6.14, second and fifth paragraphs."},{"question":"Where do path candidates and mechanism candidates respectively come from?","answer":"Path candidates come from state-exit conditions; mechanism candidates come from observed changes. Both then require individual checks of enabling conditions, propagation stages, and minimum evidence.","basis":"§6.14, second paragraph."},{"question":"Which four items must a candidate path specify at minimum? What can it still do without enabling evidence?","answer":"Continuation conditions, observable changes the mechanism should produce first, contrary signals, and stopping points. Without enabling evidence, it can still organize discriminating observations but cannot become an identified mechanism.","basis":"§6.14, fourth paragraph."},{"question":"If the expected outcome is markedly longer waits, why is ‘waiting starts to increase’ not an early signal of local overload?","answer":"It merely restates the outcome more mildly. Temporary demand growth and reduced capacity can also lengthen waits, so it fails to distinguish competitors. Under §12.6, an early signal is an observable change the path's mechanism should produce first.","basis":"§6.14, third and fourth paragraphs; §12.6."},{"question":"Can complete cards and multiple analysts using the same search order prove a mechanism? What comparison is required when adjusting the order?","answer":"No. Adjustments must preserve the original mechanisms' applicability boundaries and face comparison with simpler search methods.","basis":"§6.14, fifth paragraph."}],"openQuestions":["This section requires distinguishing local overload from temporary demand growth, reduced capacity, and common external causes. Specific observational conditions belong to §6.6 CM-LOAD; the lesson does not prescribe a uniform criterion on the author's behalf.","This lesson has not compared this search order with simpler search methods."],"applicability":{"realCase":"not_applicable","diagram":"not_applicable","reason":"This section specifies a working order for finding candidates. The lesson uses a teaching construction only to illustrate search and recording; it is no formal mechanism instance and adds no figure."},"summary":"Search order is only a working order for finding candidates; earlier discovery does not mean greater likelihood of truth. Retain competing candidates and simple baselines when using a candidate. Without enabling evidence, it may still organize discriminating observations, but cannot become an identified mechanism.","caseLinks":[],"caseNotes":[],"figures":[],"sourceRefs":[{"section":"6.14","start_line":1535,"end_line":1552,"startLine":1535,"endLine":1552}],"outputId":"section-6-14","taskId":"S-6-14","sourceHash":"51795bb7988f2669a324a52666c320cfba1382f597f7b5c6a1431844572da1fb","sources":[{"id":"theory","title":"Historical Chinese research manuscript: Xikari—On Conditions, Structure, and Transformation","url":"/downloads/Xikari-条件结构与转化论.md","source_type":"theory_source","version_or_date":"Source dated 2026-10-17","locator":"§6.14, historical Chinese manuscript lines 1467–1480","claim_support":["6.14: the order for seeking mechanism and path candidates, competing candidates, and recording requirements"],"limits":["The author's theoretical text is the object being explained; it does not replace external empirical evidence.","This entry preserves the original research’s version, locations, and reading scope; it is not a record of external-source review for v2. For the current theory, see theory-v2."],"access_status":"read"},{"id":"theory-v2","title":"Xikari: On Conditions, Structure, and Transformation, v2, November 2026","url":"/downloads/Xikari-条件结构与转化论.md","source_type":"theory_source","version_or_date":"v2 / 2026-11-16","locator":"6.14 Search Order for Mechanisms and Paths; Chinese source lines 1489–1502; SHA-256 6ef2e508474d4ac1ad07d7e4e068955342c405b5f680afcfc40d68cca3d0149c","claim_support":["The current source section and this text’s conceptual explanation of v2; not a substitute for external empirical materials."],"limits":["Older research attachments retain their original manuscript identity; the previous scope of external reading has not expanded because of this edition change."],"access_status":"read"}],"editionNote":"This page’s source text and section locations correspond to v2; historical research attachments and prior external-reading records retain their own versions and scopes.","translationOf":{"language":"zh","lesson_sha256":"b98647351a62d6704aa9ad208eb3b6a29d0d3c54e8eeaacc355d7ef2bc6d54ed","source_sha256":"6ef2e508474d4ac1ad07d7e4e068955342c405b5f680afcfc40d68cca3d0149c"}}}},"headers":[],"relativePath":"en/theory/part-06.md","filePath":"en/theory/part-06.md"}`),c={name:"en/theory/part-06.md"};function l(d,e,u,h,p,m){const a=s("SectionLesson");return r(),o("div",null,[e[0]||(e[0]=t("",1)),i(a,{section:"intro-06-part"}),e[1]||(e[1]=t("",1)),i(a,{section:"6.1"}),e[2]||(e[2]=t("",1)),i(a,{section:"6.2"}),e[3]||(e[3]=t("",1)),i(a,{section:"6.2.1"}),e[4]||(e[4]=t("",1)),i(a,{section:"6.3"}),e[5]||(e[5]=t("",1)),i(a,{section:"6.4"}),e[6]||(e[6]=t("",1)),i(a,{section:"6.5"}),e[7]||(e[7]=t("",1)),i(a,{section:"6.6"}),e[8]||(e[8]=t("",1)),i(a,{section:"6.7"}),e[9]||(e[9]=t("",1)),i(a,{section:"6.8"}),e[10]||(e[10]=t("",1)),i(a,{section:"6.9"}),e[11]||(e[11]=t("",1)),i(a,{section:"6.10"}),e[12]||(e[12]=t("",1)),i(a,{section:"6.10.1"}),e[13]||(e[13]=t("",1)),i(a,{section:"6.11"}),e[14]||(e[14]=t("",1)),i(a,{section:"6.12"}),e[15]||(e[15]=t("",1)),i(a,{section:"6.13"}),e[16]||(e[16]=t("",1)),i(a,{section:"6.14"}),e[17]||(e[17]=t("",3))])}const y=n(c,[["render",l]]);export{g as __pageData,y as default};
